sparql_query:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?property ?value
WHERE {
  ?hazard a kwg-ont:Hazard .

  OPTIONAL { ?hazard ?property ?value . }

  # Include temporal information if available (endsAt, startsFrom, hasTemporalScope)
  OPTIONAL {
    {?hazard kwg-ont:endsAt ?fix . 
     ?fix time:inXSDDateTime ?endTime}
    UNION
    {?hazard kwg-ont:startsFrom ?fix . 
     ?fix time:inXSDDateTime ?startTime}
    UNION
    {?hazard kwg-ont:hasTemporalScope ?tempScope .
     ?tempScope a time:Interval ;
                time:hasBeginning ?beginTime ;
                time:hasEnd ?endTime}
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?propertyLabel ?value
WHERE {
  # Identify any geographical place (administrative regions or S2 cells)
  { ?place a kwg-ont:AdministrativeRegion } UNION
  { ?place a kwg-ont:S2Cell }

  # Find health‑related properties defined for that place
  OPTIONAL {
    ?place ?property ?value .
    FILTER (
      ?property IN (
        kwg-ont:hospitalStatus,   -- open/closed status of hospitals
        kwg-ont:hospitalType,     -- type of hospital (general acute, children, etc.)
        kwg-ont:helipadAvailability,  -- helipad availability at a hospital
        kwg-ont:traumaCareLevel   -- trauma care level designation for health facilities
      )
    ) .
    OPTIONAL { ?property rdfs:label ?propertyLabel . }
    # Ensure the value is bound (may be literal or URI)
    BIND(COALESCE(?value, "unknown") AS ?value)
  }
}
ORDER BY ?place ?propertyLabel

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?place ?attributeValue
WHERE {
  ?place a (kwg-ont:AdministrativeRegion_2 |
            kwg-ont:AdministrativeRegion_3 |
            kwg-ont:S2Cell |
            kwg-ont:USCensusMSA |
            kwg-ont:ZipCodeArea |
            kwg-ont:NWZone) .
  {
    SELECT DISTINCT ?place
    WHERE {
      { ?place a kwg-ont:AdministrativeRegion_2 } UNION
      { ?place a kwg-ont:AdministrativeRegion_3 } UNION
      { ?place a kwg-ont:S2Cell } UNION
      { ?place a kwg-ont:USCensusMSA } UNION
      { ?place a kwg-ont:ZipCodeArea } UNION
      { ?place a kwg-ont:NWZone }
    }
  }
  OPTIONAL {
    # Population (total)
    ?popObs a sosa:Observation ;
            sosa:observedProperty kwg-ont:censusObservableProperty.totalPopulation ;
            sosa:result ?populationValue .
    FILTER EXISTS { 
      ?cObsCollection a sosa:ObservationCollection ;
                      sosa:hasMember ?popObs ;
                      sosa:hasFeatureOfInterest ?place
    }
    BIND(?populationValue AS ?attributeValue)
  }
  OPTIONAL {
    # Household units (total)
    ?hObs a sosa:Observation ;
          sosa:observedProperty kwg-ont:censusObservableProperty.householdUnits ;
          sosa:result ?householdsValue .
    FILTER EXISTS { 
      ?cObsCollection2 a sosa:ObservationCollection ;
                       sosa:hasMember ?hObs ;
                       sosa:hasFeatureOfInterest ?place
    }
    BIND(?householdsValue AS ?attributeValue)
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT COUNT(DISTINCT ?earthquake)
WHERE {
  ?earthquake a kwg-ont:Earthquake .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hazardType ?property ?value
WHERE {
  ?event a kwg-ont:NOAAHazardEvent ;
         rdfs:subClassOf+ ?hazardType .  # retrieve all NOAA storm-specific hazard types (subclasses of NOAAHazardEvent)

  OPTIONAL { ?event ?property ?value . }  # collect any available property-value pairs for the event

  FILTER NOT EXISTS {
    ?nonStorm a kwg-ont:NOAAHazardEvent ;
              rdfs:subClassOf+ ?nonStormType .
    FILTER(?nonStormType NOT IN (
      kwg-ont:NOAABlizzard, kwg-ont:NOAAHurricane, kwg-ont:NOAATornado,
      kwg-ont:NOAAWinterStorm, kwg-ont:NOAAStormSurgeTide,
      kwg-ont:NOAATropicalDepression, kwg-ont:NOAATropicalStorm,
      kwg-ont:NOAARipCurrent, kwg-ont:NOAASneakerwave
    ))
  }
}
ORDER BY ?hazardType ?property

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?region ?property ?value
WHERE {
  { ?region a (kwg-ont:S2Cell | kwg-ont:USClimateDivision |
                kwg-ont:DroughtZone | kwg-ont:NWZone |
                kwg-ont:USCensusMSA | kwg-ont:AdministrativeRegion) }
    UNION
  { ?region a (kwg-ont:S2CellLevel9 | kwg-ont:S2CellLevel11 |
                kwg-ont:S2CellLevel13 |
                kwg-ont:AdministrativeRegion_0 |
                kwg-ont:AdministrativeRegion_1 |
                kwg-ont:AdministrativeRegion_2 |
                kwg-ont:AdministrativeRegion_3 |
                kwg-ont:AdministrativeRegion_4 |
                kwg-ont:AdministrativeRegion_5 |
                kwg-ont:AdministrativeRegion_6) }
  OPTIONAL { ?region geo:hasGeometry ?geom . }

  # Climate division specific attributes
  OPTIONAL {
    ?cd a kwg-ont:USClimateDivision .
    BIND(?cd AS ?region)
    FILTER(?cd = ?region)
    ?obs a kwg-ont:ClimateObservation ;
         sosa:observedProperty ?property ;
         sosa:result ?result .
    ?result kwg-ont:value ?value .
  }

  # Drought zone attributes
  OPTIONAL {
    ?dz a kwg-ont:DroughtZone .
    BIND(?dz AS ?region)
    FILTER(?dz = ?region)
    ?obs2 a kwg-ont:DroughtZoneOverlapObservation ;
          sosa:observedProperty ?property ;
          sosa:result ?result2 .
    ?result2 kwg-ont:compositePercentageInformation ?value .
  }

  # Air quality site attributes
  OPTIONAL {
    ?aqsite a kwg-ont:AirQualitySite .
    BIND(?aqsite AS ?region)
    FILTER(?aqsite = ?region)
    ?obs3 a kwg-ont:CensusACS5YearEstimatesObservation ;
          sosa:observedProperty ?property ;
          sosa:result ?result3 .
    ?result3 kwg-ont:value ?value .
  }

  # Other climate-specific properties (e.g., magnitude, impact)
  OPTIONAL {
    ?haz a kwg-ont:NOAAHazardEvent .
    BIND(?haz AS ?region)
    FILTER(?haz = ?region)
    { 
      SELECT ?haz ?property ?value
      WHERE {
        VALUES ?property {
          kwg-ont:magnitudeObservableProperty.maxWindSpeed
          kwg-ont:impactObservableProperty.damageCrop
          # Add other relevant properties here
        }
        ?obs4 a sosa:Observation ;
              sosa:observedProperty ?property ;
              sosa:result ?result4 .
        ?result4 kwg-ont:value ?value .
        FILTER(?haz = subject(?obs4))
      }
    }
  }
}
ORDER BY ?region ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?earthquake ?type ?property ?value
WHERE {
  ?earthquake a kwg-ont:Earthquake .
  OPTIONAL { ?earthquake rdf:type ?type . }
  OPTIONAL { ?earthquake ?property ?value . }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?event ?property ?value
WHERE {
  ?event a kwg-ont:NOAAHazardEvent ;
         rdfs:label ?eventName .

  ?obs a sosa:Observation ;
       sosa:wasGeneratedBy ?event ;
       sosa:observedProperty ?property ;
       sosa:resultValue ?value .

  OPTIONAL { ?property rdfs:label ?propertyName . }
  OPTIONAL { ?value rdfs:label ?valueLabel . }
}
ORDER BY ?eventName

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?impactDetail
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
               kwg-ont:affectedByInverse ?hazard .

  ?impactObservation a sosa:Observation ;
                     sosa:observedProperty ?impactProp ;
                     sosa:hasFeatureOfInterest ?hazardEvent .

  BIND(?impactObservation AS ?impactDetail)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?attribute ?damage ?impactTemp
WHERE {
  ?hazard a kwg-ont:NOAAHurricane ;
          kwg-ont:hasTemporalScope ?tempStart ;
          OPTIONAL { ?hazard ?attrProp ?attribute . }   # any hurricane-specific attribute
          kwg-ont:affectedByInverse ?event .

  ?event a kwg-ont:HazardEpisode ;
         sosa:hasMember/sosa:wasGeneratedBy/geo:hasGeometry ?geometry ;  # ensure geographical place is involved

  OPTIONAL {
    ?damage a kwg-ont:ImpactObservation ;
            sosa:observedProperty ?impactProp ;
            sosa:resultTime ?impactTemp .   # temporal data if available
  }
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?damageType ?damageValue
WHERE {
  ?tornado rdf:type kwg-ont:NOAATornado .

  ?eventSegment a kwg-ont:EventSegment ;
                kwg-ont:startsFrom ?startFix ;
                kwg-ont:endsAt ?endFix .

  ?tornado kwg-ont:hasPart ?eventSegment .

  # Temporal extent filter (example using a specific period; replace with desired values)
  FILTER( ?startFix ^time:inXSDDateTime >= "2023-01-01T00:00:00"^^xsd:dateTime )
  FILTER( ?endFix   ^time:inXSDDateTime <= "2023-12-31T23:59:59"^^xsd:dateTime )

  # Geographical relation (the tornado event overlaps a specific place)
  {
    SELECT DISTINCT ?damageType ?damageValue
    WHERE {
      ?tornado kwg-ont:affectedBy ?damage .

      ?damage a kwg-ont:ImpactObservation ;
              kwg-ont:impactType ?damageType ;
              kwg-ont:impactValue ?damageValue .

      # Optional: further restrict to specific damage types (e.g., property, crop)
      FILTER(?damageType IN (kwg-ont:impactObservableProperty.damageCrop,
                             kwg-ont:impactObservableProperty.damageProperty))
    }
  }

  # Ensure the tornado is spatially related to a geographical place
  {
    SELECT DISTINCT *
    WHERE {
      ?tornado geo:sfWithin ?place .

      # Example place URI (replace with actual place URI you are interested in)
      FILTER(?place = <http://example.org/place/MyCity>)
    }
  }
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?damageDetail
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          kwg-ont:affectedBy ?target .

  # Ensure the hazard is storm-specific (sub-class of NOAAHazard)
  FILTER NOT EXISTS { ?hazard a [] ; MINUS { ?hazard a kwg-ont:NOAAHazardEvent } }

  # Link to an affected geographical place
  ?target a geo:SpatialObject ;
          geo:hasGeometry ?geometry .

  # Restrict the hazard to a certain temporal extent (example filter)
  ?temporalScope a time:Interval ;
                 time:hasBeginning ?start ;
                 time:hasEnd ?end .
  FILTER( ?start >= "2023-01-01"^^xsd:date && ?end <= "2024-12-31"^^xsd:date )

  # Retrieve damage details (e.g., impact observations)
  ?impact a kwg-ont:ImpactObservation ;
          kwg-ont:hasValue ?damageDetail .

  SERVICE <http://localhost:7200/repositories/kwg> {
    GRAPH ?g {
      ?hazard kwg-ont:affectedBy ?target .
      ?target geo:hasGeometry ?geometry .
      OPTIONAL { ?temporalScope time:hasBeginning ?start ; time:hasEnd ?end }
      OPTIONAL { ?impact kwg-ont:hasValue ?damageDetail }
    }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?type ?startDate ?endDate
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard a ?concreteType . }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?population ?households
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazardType (COUNT(*) AS ?count)
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType ?hazardType .
}
GROUP BY ?hazardType

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?attribute (STR(?range) AS ?rangeLabel)
WHERE {
  ?attribute rdf:type owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place ;
             rdfs:range ?range .

  FILTER (CONTAINS(LCASE(STR(?attribute)), "flood"))
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazardEvent
       ?type
       OPTIONAL {?hazardEvent kwgl-ont:hasName        ?name}
       OPTIONAL {?hazardEvent kwgl-ont:hasStartDate   ?startDate}
       OPTIONAL {?hazardEvent kwgl-ont:hasEndDate     ?endDate}
       OPTIONAL {?hazardEvent kwgl-ont:affectedAreaInAcres  ?affectedArea}
       OPTIONAL {?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage}
       OPTIONAL {?hazardEvent kwgl-ont:damageToCropsInDollars           ?cropsDamage}
       OPTIONAL {?hazardEvent kwgl-ont:hasKWGEntity   ?kWGE}
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType ?type .
  FILTER(?type = kwglr:earthquake)
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?event
  ?affectedAreaInAcres
  ?damageToCropsInDollars
  ?damageToInfrastructureInDollars
  ?dollarDamageOfFiresImpactingPlace2018
  ?dollarDamageOfFiresImpactingPlace2019
  ?dollarDamageOfFiresImpactingPlace2020
  ?dollarDamageOfFiresImpactingPlace2021
  ?dollarDamageOfFiresImpactingPlace2022
  ?dollarDamageOfFloodsImpactingPlace2018
  ?dollarDamageOfFloodsImpactingPlace2019
  ?dollarDamageOfFloodsImpactingPlace2020
  ?dollarDamageOfFloodsImpactingPlace2021
  ?dollarDamageOfFloodsImpactingPlace2022
  ?dollarDamageOfHurricanesImpactingPlace2018
  ?dollarDamageOfHurricanesImpactingPlace2019
  ?dollarDamageOfHurricanesImpactingPlace2020
  ?dollarDamageOfHurricanesImpactingPlace2021
  ?dollarDamageOfHurricanesImpactingPlace2022
  ?dollarDamageOfLandslidesImpactingPlace2018
  ?dollarDamageOfLandslidesImpactingPlace2019
  ?dollarDamageOfLandslidesImpactingPlace2020
  ?dollarDamageOfLandslidesImpactingPlace2021
  ?dollarDamageOfLandslidesImpactingPlace2022
  ?dollarDamageOfStormSurgesImpactingPlace2018
  ?dollarDamageOfStormSurgesImpactingPlace2019
  ?dollarDamageOfStormSurgesImpactingPlace2020
  ?dollarDamageOfStormSurgesImpactingPlace2021
  ?dollarDamageOfStormSurgesImpactingPlace2022
  ?dollarDamageOfTornadoesImpactingPlace2018
  ?dollarDamageOfTornadoesImpactingPlace2019
  ?dollarDamageOfTornadoesImpactingPlace2020
  ?dollarDamageOfTornadoesImpactingPlace2021
  ?dollarDamageOfTornadoesImpactingPlace2022
WHERE {
  ?event a kwgl-ont:HazardEvent .

  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }

  # Damage by fire
  OPTIONAL { ?event kwgl-ont:dollarDamageOfFiresImpactingPlace2018 ?dollarDamageOfFiresImpactingPlace2018 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfFiresImpactingPlace2019 ?dollarDamageOfFiresImpactingPlace2019 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfFiresImpactingPlace2020 ?dollarDamageOfFiresImpactingPlace2020 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfFiresImpactingPlace2021 ?dollarDamageOfFiresImpactingPlace2021 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfFiresImpactingPlace2022 ?dollarDamageOfFiresImpactingPlace2022 }

  # Damage by flood
  OPTIONAL { ?event kwgl-ont:dollarDamageOfFloodsImpactingPlace2018 ?dollarDamageOfFloodsImpactingPlace2018 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfFloodsImpactingPlace2019 ?dollarDamageOfFloodsImpactingPlace2019 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfFloodsImpactingPlace2020 ?dollarDamageOfFloodsImpactingPlace2020 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfFloodsImpactingPlace2021 ?dollarDamageOfFloodsImpactingPlace2021 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfFloodsImpactingPlace2022 ?dollarDamageOfFloodsImpactingPlace2022 }

  # Damage by hurricane
  OPTIONAL { ?event kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?dollarDamageOfHurricanesImpactingPlace2018 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?dollarDamageOfHurricanesImpactingPlace2019 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 ?dollarDamageOfHurricanesImpactingPlace2020 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 ?dollarDamageOfHurricanesImpactingPlace2021 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 ?dollarDamageOfHurricanesImpactingPlace2022 }

  # Damage by landslide
  OPTIONAL { ?event kwgl-ont:dollarDamageOfLandslidesImpactingPlace2018 ?dollarDamageOfLandslidesImpactingPlace2018 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfLandslidesImpactingPlace2019 ?dollarDamageOfLandslidesImpactingPlace2019 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfLandslidesImpactingPlace2020 ?dollarDamageOfLandslidesImpactingPlace2020 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfLandslidesImpactingPlace2021 ?dollarDamageOfLandslidesImpactingPlace2021 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfLandslidesImpactingPlace2022 ?dollarDamageOfLandslidesImpactingPlace2022 }

  # Damage by storm surge
  OPTIONAL { ?event kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2018 ?dollarDamageOfStormSurgesImpactingPlace2018 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2019 ?dollarDamageOfStormSurgesImpactingPlace2019 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2020 ?dollarDamageOfStormSurgesImpactingPlace2020 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2021 ?dollarDamageOfStormSurgesImpactingPlace2021 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2022 ?dollarDamageOfStormSurgesImpactingPlace2022 }

  # Damage by tornado
  OPTIONAL { ?event kwgl-ont:dollarDamageOfTornadoesImpactingPlace2018 ?dollarDamageOfTornadoesImpactingPlace2018 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfTornadoesImpactingPlace2019 ?dollarDamageOfTornadoesImpactingPlace2019 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfTornadoesImpactingPlace2020 ?dollarDamageOfTornadoesImpactingPlace2020 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfTornadoesImpactingPlace2021 ?dollarDamageOfTornadoesImpactingPlace2021 }
  OPTIONAL { ?event kwgl-ont:dollarDamageOfTornadoesImpactingPlace2022 ?dollarDamageOfTornadoesImpactingPlace2022 }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?damageProperty ?damageValue
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?value }      BIND(?value AS ?damageValue) ON SHAPES { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?value }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?value }    BIND(?value AS ?damageValue) ON SHAPES { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?value }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?value }BIND(?value AS ?damageValue) ON SHAPES { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?value }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?value }BIND(?value AS ?damageValue) ON SHAPES { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?value }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?value }BIND(?value AS ?damageValue) ON SHAPES { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?value }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?value } BIND(?value AS ?damageValue) ON SHAPES { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?value }

  BIND(
    COALESCE(
      ?dollarDamageOfFiresImpactingPlace,
      ?dollarDamageOfFloodsImpactingPlace,
      ?dollarDamageOfHurricanesImpactingPlace,
      ?dollarDamageOfLandslidesImpactingPlace,
      ?dollarDamageOfStormSurgesImpactingPlace,
      ?dollarDamageOfTornadoesImpactingPlace
    ) AS ?damageValue
  )

  BIND(
    COALESCE(
      kwgl-ont:dollarDamageOfFiresImpactingPlace,
      kwgl-ont:dollarDamageOfFloodsImpactingPlace,
      kwgl-ont:dollarDamageOfHurricanesImpactingPlace,
      kwgl-ont:dollarDamageOfLandslidesImpactingPlace,
      kwgl-ont:dollarDamageOfStormSurgesImpactingPlace,
      kwgl-ont:dollarDamageOfTornadoesImpactingPlace
    ) AS ?damageProperty
  )

  FILTER(?damageValue != [])
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?place ?damage
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType kwglr:tornado ;
         kwgl-ont:impactedBy ?place .

  OPTIONAL { ?event kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damage . }
  # FILTER for temporal extent can be added here if date properties are present
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place ?damageProperty ?damageValue
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType ?hazardType .

  # Restrict to storm‑specific hazards (e.g., hurricane, tropicalStorm, etc.)
  FILTER (?hazardType IN (
    kwglr:hurricane,
    kwglr:tropicalDepression,
    kwglr:tropicalStorm,
    kwglr:stormSurgeTide
  ))

  # Temporal extent filter – adjust the dates as needed for your query window
  FILTER (kwgl-ont:hasStartDate ?event >= "2020-01-01"^^xsd:date)
  FILTER (kwgl-ont:hasEndDate   ?event <= "2022-12-31"^^xsd:date)

  # Link event to the impacted place and retrieve storm‑specific damage amounts
  ?event kwgl-ont:hasImpacted ?place .
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace          ?damageValue . BIND(kwgl-ont:dollarDamageOfHurricanesImpactingPlace AS ?damageProperty) }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace         ?damageValue . BIND(kwgl-ont:dollarDamageOfStormSurgesImpactingPlace AS ?damageProperty) }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace           ?damageValue . BIND(kwgl-ont:dollarDamageOfTornadoesImpactingPlace AS ?damageProperty) }
}

