          kwg-ont:hasTemporalScope ?temporalScope ;
          geo:hasGeometry ?geometry .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?place ?name
WHERE {
  ?place a geo:Feature ;
         geo:hasDefaultGeometry ?geom .   # ensure it is a geographical place with geometry
  OPTIONAL { ?place kwg-ont:hasName ?name } .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?place ?property ?value
WHERE {
  { 
    ?place a kwg-ont:Hazard ;
           kwg-ont:spatialRelation|kwg-ont:sfWithin ?place .
    ?hazardObs a sosa:Observation ;
               sosa:hasFeatureOfInterest ?hazard ;
               sosa:observedProperty ?property ;
               sosa:hasSimpleResult ?value .
    FILTER(?hazard = ?place)
  }
  UNION
  { 
    ?place a kwg-ont:HazardEpisode ;
           kwg-ont:episodeHasPart ?event .
    ?impactObs a kwg-ont:ImpactObservation ;
               sosa:hasFeatureOfInterest ?event ;
               sosa:observedProperty ?property ;
               sosa:hasSimpleResult ?value .
    FILTER(?place = ?hazardEpisode)
  }
  UNION
  { 
    ?place a kwg-ont:AdministrativeRegion_3 ;
           kwg-ont:sfWithin|kwg-ont:spatialRelation ?cell .
    ?publicHealthObs a kwg-ont:PublicHealthObservation ;
                     sosa:hasFeatureOfInterest ?place ;
                     sosa:observedProperty ?property ;
                     sosa:hasSimpleResult ?value .
  }
  UNION
  { 
    ?place a kwg-ont:DroughtZone ;
           kwg-ont:sfWithin|kwg-ont:spatialRelation ?cell .
    ?droughtObs a kwg-ont:DroughtZoneOverlapObservation ;
                sosa:hasFeatureOfInterest ?place ;
                sosa:observedProperty ?property ;
                sosa:hasSimpleResult ?value .
  }
  UNION
  { 
    ?place a kwg-ont:VulnerabilityObservableProperty ;
           sosa:hasFeatureOfInterest ?place .
    ?vulnObs a kwg-ont:VulnerabilityObservation ;
             sosa:observedProperty ?property ;
             sosa:hasSimpleResult ?value .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place ?attributeType ?value
WHERE {
  ?observation a kwg-ont:CensusACS5YearEstimatesObservation ;
               sosa:hasFeatureOfInterest ?place ;
               sosa:observedProperty ?attributeType ;
               sosa:hasSimpleResult ?value .

  ?place a geo:SpatialObject .

  FILTER(?attributeType IN (
    kwg-ont:censusObservableProperty.totalPopulation,
    kwg-ont:censusObservableProperty.malePopulation,
    kwg-ont:censusObservableProperty.femalePopulation,
    kwg-ont:censusObservableProperty.householdUnits
  ))
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT COUNT(DISTINCT ?earthquake) ?earthquake
WHERE {
  ?earthquake a kwg-ont:Earthquake .
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT DISTINCT ?attribute (COUNT(DISTINCT ?hazard) AS ?count)
WHERE {
  ?hazard a kwg-ont:NOAATornado ;
          sosa:hasFeatureOfInterest ?place .
  ?observation a sosa:Observation ;
               sosa:observedProperty ?attribute ;
               sosa:hasFeatureOfInterest ?hazard .
  ?place a geo:SpatialObject .   # any geographical place
}
GROUP BY ?attribute

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?hazard ?attribute ?value
WHERE {
  # Storm-specific hazards (those that are subclasses of NOAAHazardEvent)
  ?hazard a kwg-ont:NOAAHazardEvent ;
          kwg-ont:hasTemporalScope ?time ;
          geo:hasGeometry ?geom .

  # Retrieve any observable property and its value for the hazard
  ?obs a sosa:Observation ;
       sosa:hasFeatureOfInterest ?hazard ;
       sosa:observedProperty ?attribute ;
       sosa:hasSimpleResult ?value .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?hazard ?attribute ?value
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          a kwg-ont:Flood .   # flood-specific hazard events
  ?obs a sosa:Observation ;
       sosa:hasFeatureOfInterest ?hazard ;
       sosa:observedProperty ?attribute ;
       sosa:hasSimpleResult ?value .
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?earthquake ?type ?detail
WHERE {
  ?earthquake a kwg-ont:Earthquake ;
              kwg-ont:hasTemporalScope ?time .

  OPTIONAL { ?earthquake kwg-ont:depth ?depth . }
  OPTIONAL { ?earthquake kwg-ont:mag ?magnitude . }
  OPTIONAL { ?earthquake geo:hasGeometry ?geometry . }

  BIND (CONCAT("Depth:", COALESCE(STR(?depth), "unknown"),
               ", Magnitude:", COALESCE(STR(?magnitude), "unknown"),
               ", Geometry:", COALESCE(STR(?geometry), "none")) AS ?detail)

  BIND (kwg-ont:Earthquake AS ?type)
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?hazardEvent ?impactProperty ?impactValue
WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?hazardEvent ;
       sosa:observedProperty ?impactProperty ;
       sosa:hasSimpleResult ?impactValue .
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?impactObservation
WHERE {
  ?hazard a kwg-ont:Hazard ;
          kwg-ont:affectedBy ?impactObservation .
  ?impactObservation a kwg-ont:ImpactObservation .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?attributeValue ?impactProperty ?impactValue ?temporalData
WHERE {
  # Hurricane-specific hazard (NOAAHazardEvent with type NOAAHurricane)
  ?hazard a kwg-ont:NOAAHurricane ;
          geo:hasGeometry ?geom ;               # ensure it is related to a geographical place via geometry
          sosa:observedProperty ?attributeProp ;
          sosa:resultTime ?temporalData .       # optional temporal data of the hazard itself

  # Hazard attribute (any observable property and its value)
  ?hazard ?attributeProp ?attributeValue .

  # Impact details related to the same hurricane event
  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:hasFeatureOfInterest ?hazard ;
                     sosa:observedProperty ?impactProperty ;
                     sosa:resultTime ?temporalData2 ;   # temporal data of the impact observation (if available)
                     sosa:hasSimpleResult ?impactValue .

  # Bind optional temporal data
  BIND(COALESCE(?temporalData, ?temporalData2) AS ?temporalDataFinal)

  # Select only needed variables for final output
  VALUES ?selectedVars { ?hazard ?attributeProp ?attributeValue ?impactProperty ?impactValue ?temporalDataFinal }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?damageDetail ?temporalExtent ?place
WHERE {
  ?hazard a kwg-ont:NOAATornado ;
          sosa:hasSimpleResult ?damageDetail ;
          kwg-ont:hasTemporalScope ?temporalExtent .

  ?hazard kwg-ont:spatialRelation ?place .
  FILTER ( ?temporalExtent >= iri_to_uri("2023-01-01T00:00:00Z") && 
           ?temporalExtent <= iri_to_uri("2024-12-31T23:59:59Z") )
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazardEvent ?impactProperty ?impactValue
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
               kwg-ont:hasTemporalScope ?tempScope ;
               geo:hasGeometry ?geom ;
               geo:asWKT ?wkt .          # optional geometry retrieval

  FILTER (exists { ?hazardEvent a kwg-ont:NOAATornado })   # storm-specific hazard example
  FILTER (exists { ?hazardEvent kwg-ont:spatialRelation ?place })
  FILTER (?tempScope >= "2023-01-01T00:00:00"^^xsd:dateTime && ?tempScope <= "2024-12-31T23:59:59"^^xsd:dateTime)

  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:hasFeatureOfInterest ?hazardEvent ;
                     sosa:observedProperty ?impactProperty ;
                     sosa:hasSimpleResult ?impactValue .
}

