WHERE {
  ?university a coresr-ont:University ;
              coresr-ont:locatedAt ?location .
  ?location coresr-ont:atState ?state .
  ?state coresr-ont:inCity ?city .
  ?university coresr-ont:hasPart ?college .
  FILTER NOT EXISTS { ?college a coresr-ont:Department }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?state ?university
WHERE {
  ?pub coresr-ont:submittedBy ?author .
  ?author coresr-ont:advisedBy ?advisor .
  ?advisor a coresr-ont:Advisor ;
           coresr-ont:associatedWith ?dept .
  ?dept a coresr-ont:Department ;
        coresr-ont:partOf ?college .
  ?college a coresr-ont:College ;
           coresr-ont:partOf ?univ .
  ?univ a coresr-ont:University ;
        coresr-ont:locatedAt ?loc .
  ?loc coresr-ont:atState ?state .

  # Count publications per university within each state
  {
    SELECT ?univ (COUNT(DISTINCT ?pub) AS ?cnt)
    WHERE {
      ?pub coresr-ont:submittedBy ?author2 .
      ?author2 coresr-ont:advisedBy ?advisor2 .
      ?advisor2 a coresr-ont:Advisor ;
                coresr-ont:associatedWith ?dept2 .
      ?dept2 a coresr-ont:Department ;
             coresr-ont:partOf ?college2 .
      ?college2 a coresr-ont:College ;
                coresr-ont:partOf ?univ2 .
      ?univ2 a coresr-ont:University ;
              coresr-ont:locatedAt ?loc2 .
      ?loc2 coresr-ont:atState ?state .
    }
    GROUP BY ?univ
  } ORDER BY DESC(?cnt) LIMIT 1
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication
WHERE {
  ?publication a coresr-ont:Publication .
  SELECT ?pub (COUNT(DISTINCT ?dept) AS ?cnt)
  WHERE {
    ?pub coresr-ont:hasContributor ?contrib .
    ?contrib a coresr-ont:Contributor ;
             coresr-ont:isPerformedBy ?agent .
    ?agent coresr-ont:associatedWith ?dept .
  }
  GROUP BY ?pub
  HAVING (?cnt > 1)
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?pubType (AVG(?diffDays) AS ?avgDiff)
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:dateOfSubmission ?subDate ;
       coresr-ont:dateOfPublication ?pubDate ;
       coresr-ont:hasPublicationType ?pt .

  BIND((xsd:dateTime(?pubDate) - xsd:dateTime(?subDate)) / ^xsd:dayTimeDuration('P1D') AS ?diffDays)

  BIND(coresr-ont:typeAsString(?pt) AS ?pubType)
}
GROUP BY ?pubType
ORDER BY DESC(?avgDiff)
LIMIT 1

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?author ?fieldOfStudy
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .  # ensures the author has an advisor
  ?pub a coresr-ont:Publication ;
       coresr-ont:submittedBy ?author ;   # publication submitted by that author
       coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

