  ?publication a coresr-ont:Publication ;
               coresr-ont:submittedBy ?author .
  ?author coresr-ont:associatedWith ?dept1 .

  FILTER EXISTS {
    ?publication coresr-ont:submittedBy ?otherAuthor .
    ?otherAuthor coresr-ont:associatedWith ?dept2 .
    FILTER (?dept1 != ?dept2)
  }
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?pubType (AVG(?diff) AS ?avgDiff)
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:dateOfSubmission ?subDate ;
       coresr-ont:dateOfPublication ?pubDate ;
       coresr-ont:hasPublicationType ?pt .

  BIND ((xsd:dateTime(?pubDate) - xsd:dateTime(?subDate)) / (xsd:dayTimeDuration('P1D') * 24 * 60 * 60) AS ?diff)

  BIND (strafter(str(?pt), '#') AS ?pubType)   # extract local name of the publication type
}
GROUP BY ?pubType
ORDER BY DESC(?avgDiff)
LIMIT 1

