PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?place ?attribute ?value
WHERE {
  ?place a kwg-ont:HazardEpisode ;
         kwg-ont:hasNarrative ?narrative .

  OPTIONAL { ?place kwg-ont:nominatedBy ?president . }
  OPTIONAL { ?place kwg-ont:nominatedTime ?nominationDate . }
  OPTIONAL { ?place kwg-ont:hasDeclaration ?declaration . 
             ?declaration kwg-ont:hasDeclarationDate ?declarationDate . }

  BIND("narrative" AS ?attribute) 
  BIND(?narrative AS ?value)

  UNION

  { 
    ?place a kwg-ont:HazardEpisode ;
           kwg-ont:nominatedBy ?president .
    BIND("nominated_by" AS ?attribute) 
    BIND(?president AS ?value)
  }

  UNION

  {
    ?place a kwg-ont:HazardEpisode ;
           kwg-ont:nominatedTime ?nominationDate .
    BIND("nominated_time" AS ?attribute) 
    BIND(?nominationDate AS ?value)
  }

  UNION

  {
    ?place a kwg-ont:HazardEpisode ;
           kwg-ont:hasDeclaration ?declaration .
    ?declaration kwg-ont:hasDeclarationDate ?declarationDate .
    BIND("declaration_date" AS ?attribute) 
    BIND(?declarationDate AS ?value)
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place ?attributeType ?value
WHERE {
  ?place a kwg-ont:AdministrativeRegion ;
         geo:hasGeometry ?geometry .  # Ensure it is a geographical place

  # Population attribute
  OPTIONAL {
    ?place kwg-ont:censusObservableProperty.totalPopulation ?pop .
    BIND(kwg-ont:censusObservableProperty.totalPopulation AS ?attributeType)
    BIND(?pop AS ?value)
  }

  # Household units attribute
  OPTIONAL {
    ?place kwg-ont:censusObservableProperty.householdUnits ?hh .
    BIND(kwg-ont:censusObservableProperty.householdUnits AS ?attributeType)
    BIND(?hh AS ?value)
  }
}
ORDER BY ?place

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT COUNT(DISTINCT ?hazard) {
  ?hazard a kwg-ont:Earthquake .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT DISTINCT ?attribute (COUNT(DISTINCT ?hazard) AS ?count)
WHERE {
  ?hazard a kwg-ont:NOAATornado ;
          sosa:hasSimpleResult ?result .
  ?result a kwg-ont:TornadoMagnitudeObservationCollection ;
          sosa:observedProperty ?attribute .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?hazardEvent ?attributeName ?attributeValue
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
               sosa:hasMember ?observation .
  ?observation a sosa:Observation ;
               sosa:observedProperty ?attributeName ;
               sosa:hasSimpleResult ?attributeValue .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?hazard ?attribute ?value
WHERE {
  ?hazard a kwg-ont:Hazard ;
          geo:hasGeometry ?geom .

  # Retrieve hazard-specific attributes (observable properties and their values)
  OPTIONAL { ?hazard sosa:observedProperty ?attribute ; sosa:hasResult ?result . }
  OPTIONAL { ?result kwg-ont:value ?value . }
}
ORDER BY ?hazard

PREFIX qudt: <http://qudt.org/1.1/schema/qudt#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT ?place ?property ?value
WHERE {
  ?place a kwg-ont:USClimateDivision ;
         geo:hasGeometry ?geom .

  ?result a kwg-ont:ClimateDivisionObservationResult ;
          sosa:hasFeatureOfInterest ?place ;
          kwg-ont:value ?quantity .

  ?quantity a <http://qudt.org/2.1/schema/qudt#QuantityValue> ;
            qudt:numericValue ?value ;
            qudt:unit ?unit .

  BIND (IRI(CONCAT(STR(kwg-ont:climateObservableProperty.), STRAFTER(STR(?property), "kwg-ont:"))) AS ?property)
}
ORDER BY ?place ?property

PREFIX : <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?hazard ?property ?value
WHERE {
  ?hazard a :Earthquake ;
          ?property ?value .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?event ?impactProperty ?impactValue
WHERE {
  ?event a kwg-ont:NOAAHazardEvent ;
         sosa:hasMember ?impactObservation .
  ?impactObservation a sosa:Observation ;
                     sosa:observedProperty ?impactProperty ;
                     sosa:hasSimpleResult ?impactValue .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT ?damageDetail
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
               kwg-ont:affectedByInverse ?hazard .
  ?impactObservation a sosa:Observation ;
                     sosa:observedProperty ?damageProp ;
                     sosa:hasFeatureOfInterest ?hazardEvent .
  BIND(?impactObservation AS ?damageDetail)
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?attribute ?damageImpactDetail ?temporalData
WHERE {
  # Hurricane-specific hazard events related to a geographical place
  ?hazard a kwg-ont:NOAAHazardEvent ;
          a kwg-ont:NOAAHurricane ;
          geo:hasGeometry ?geom .   # ensures the hazard is linked to a geometry (geographical place)

  # Hazard attributes (e.g., magnitude, category)
  OPTIONAL { 
    ?hazard sosa:observedProperty ?attributeProp ;      # property representing an attribute
    ?hazard sosa:hasResult/sosa:hasSimpleResult ?attributeValue .   # the actual value of the attribute
    BIND(CONCAT(STR(?attributeProp), ': ', STR(?attributeValue)) AS ?attribute)
  }

  # Damage impact details (e.g., deaths, injuries, property damage) and their temporal data if available
  OPTIONAL {
    ?impact a kwg-ont:ImpactObservation ;
            sosa:observedProperty ?damageProp ;          # type of damage impact (deathDirect, injuryIndirect, etc.)
            sosa:hasSimpleResult ?damageValue .           # the measured value/label of the impact
    OPTIONAL { ?impact time:inXSDDateTime ?temporalStamp }   # optional temporal stamp of when the impact was recorded
    BIND(CONCAT(STR(?damageProp), ': ', STR(?damageValue)) AS ?damageImpactDetail)
    BIND(COALESCE(STR(?temporalStamp), '') AS ?temporalData)
  }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?damageDetail
WHERE {
  ?hazard a kwg-ont:NOAATornado ;
          kwg-ont:hasPart ?eventSegment ;
          geo:hasGeometry ?geom .

  ?eventSegment a kwg-ont:EventSegment ;
                kwg-ont:startsFrom ?startFix ;
                kwg-ont:endsAt ?endFix .

  ?startFix a kwg-ont:Fix ;
            time:inXSDDateTime ?startTime .
  ?endFix a kwg-ont:Fix ;
          time:inXSDDateTime ?endTime .

  FILTER ( ?startTime >= "2023-01-01T00:00:00"^^xsd:dateTime
           && ?endTime   <= "2023-12-31T23:59:59"^^xsd:dateTime )

  OPTIONAL { 
    ?impact a kwg-ont:ImpactObservation ;
            sosa:observedProperty ?damageProp ;
            sosa:result ?damageDetail .
    FILTER ( ?impact sosa:hasFeatureOfInterest ?eventSegment )
  }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?damageDetail
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          kwg-ont:hasPart* ?eventSegment .

  ?eventSegment a kwg-ont:EventSegment ;
                kwg-ont:startsFrom|kwg-ont:endsAt ?fix .

  ?fix a kwg-ont:Fix ;
       geo:hasGeometry ?geometry .

  ?damageDetail a kwg-ont:ImpactObservation ;
                sosa:observedProperty ?impactProp ;
                sosa:phenomenonTime ?time .

  FILTER ( ?time >= iri(time:start) && ?time <= iri(time:end) )
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?name WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?property (GROUP_CONCAT(DISTINCT ?value; SEPARATOR='|') AS ?values)
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place ?property ?value . 
             FILTER(isDATATYPE(?property)) }
}
GROUP BY ?place ?property

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?population ?households
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households . }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?hazardType (COUNT(DISTINCT ?event) AS ?count)
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType ?hazardType .
  FILTER(?hazardType = kwglr:earthquake)
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?attribute (COUNT(DISTINCT ?place) AS ?placeCount)
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  FILTER CONTAINS(LCASE(STR(?attribute)), "tornado")

  ?place a kwgl-ont:Place ;
         ?attribute ?value .
}
GROUP BY ?attribute

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?attribute (STR(?range) AS ?rangeLabel)
WHERE {
  ?attribute rdf:type owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:HazardEvent ;
             rdfs:range ?range .

  ?hazard kwgl-ont:hasHazardType kwglr:stormSurgeTide .
  ?hazard ?attribute ?value .

  OPTIONAL { ?attribute rdfs:label ?attrLabel . }
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?attribute (STR(?range) AS ?rangeLabel)
WHERE {
  ?attribute rdf:type owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place ;
             rdfs:range ?range .

  FILTER(regex(STR(?attribute), "flood", "i"))
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?attribute
