  OPTIONAL { ?event kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?event kwgl-ont:hasName ?name . }
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?numberOfDeaths . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?damageToCropsInDollars ?damageToInfrastructureInDollars
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars ;
               kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars .
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?hazardAttr ?damageImpactAttr ?tempAttr
WHERE {
  { ?hazardAttr a owl:DatatypeProperty ;
                rdfs:domain kwgl-ont:Hurricane } .
    OPTIONAL { ?hazardAttr rdfs:range ?range . }

  UNION
    { ?damageImpactAttr a owl:DatatypeProperty ;
                        rdfs:domain kwgl-ont:Place ;
                        FILTER (CONTAINS(str(?damageImpactAttr), "dollarDamageOfHurricanesImpactingPlace")) .
      OPTIONAL { ?damageImpactAttr rdfs:range ?range . }
    } .

  UNION
    { ?tempAttr a owl:DatatypeProperty ;
                rdfs:domain kwgl-ont:HazardEvent ;
                FILTER (CONTAINS(str(?tempAttr), "hasStartDate") || CONTAINS(str(?tempAttr), "hasEndDate")) .
      OPTIONAL { ?tempAttr rdfs:range ?range . }
    } .
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?event ?place ?damageCrops ?damageInfrastructure
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType kwglr:tornado ;
         kwgl-ont:damageToCropsInDollars ?damageCrops ;
         kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure .

  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?event kwgl-ont:hasEndDate   ?endDate   . }

  FILTER (bound(?startDate) && bound(?endDate))
  FILTER (?startDate >= "2020-01-01"^^xsd:date && ?endDate <= "2023-12-31"^^xsd:date)

  ?event kwgl-ont:hasImpacted ?place .
  ?place a kwgl-ont:Place .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?hazard ?type ?temporalScope
WHERE {
  ?hazard a kwg-ont:Hazard .
  OPTIONAL { ?hazard rdfs:subClassOf ?type . }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?temporalScope . }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?place ?name
WHERE {
  ?place a kwg-ont:AdministrativeRegion ;
         rdfs:label ?name .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?place ?concernProperty ?concernValue
WHERE {
  ?place a kwg-ont:Hazard .
  OPTIONAL { 
    ?place ?concernProperty ?concernValue . 
    FILTER NOT EXISTS { 
      ?c a kwg-ont:VulnerabilityObservableProperty ; rdfs:label ?lbl . 
      FILTER(CONTAINS(str(?concernProperty), str(?c))) 
    }
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?place ?attribute ?value
WHERE {
  ?place a kwg-ont:AdministrativeRegion .
  ?observation a kwg-ont:CensusACS5YearEstimatesObservation ;
               sosa:observedProperty ?property ;
               sosa:hasFeatureOfInterest ?place ;
               sosa:hasSimpleResult ?value .
  ?property rdfs:subClassOf+ kwg-ont:CensusObservableProperty .

  VALUES ?attribute {
    "population" 
    "householdUnits"
  }
  FILTER (STRSTARTS(STR(?property), STR(kwg-ont:censusObservableProperty.totalPopulation)) && ?attribute = "population")
  UNION
  FILTER (STRSTARTS(STR(?property), STR(kwg-ont:censusObservableProperty.householdUnits)) && ?attribute = "householdUnits")
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?earthquakeHazard (COUNT(DISTINCT ?h) AS ?count)
WHERE {
  ?h a kwg-ont:Hazard ;
     rdfs:subClassOf* kwg-ont:Earthquake .
}
GROUP BY ?earthquakeHazard

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?tornadoAttribute (COUNT(DISTINCT ?attribute) AS ?count)
WHERE {
  ?hazard a kwg-ont:NOAATornado ;
          sosa:observedProperty ?attribute .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
SELECT DISTINCT ?hazardType ?property ?value ?place
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
  OPTIONAL { ?hazardEvent geo:hasGeometry ?geometry . }
  OPTIONAL { BIND(geo:asWKT(?geometry) AS ?placeGeom) } 

  ?hazardType rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
  FILTER (?hazardType = ?hazardEvent)

  OPTIONAL {
    ?hazardEvent ?property ?value .
    FILTER (isIRI(?property) && 
            (strstarts(str(?property), "http://stko-kwg.geog.ucsb.edu/lod/ontology/magnitudeObservableProperty.") ||
             strstarts(str(?property), "http://stko-kwg.geog.ucsb.edu/lod/ontology/stormTrackletObservableProperty.") ||
             strstarts(str(?property), "http://stko-kwg.geog.ucsb.edu/lod/ontology/stormTrackObservableProperty.")))
  }
}
ORDER BY ?hazardType ?property

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?floodEvent ?property ?value ?place
WHERE {
  ?floodEvent a kwg-ont:NOAAHazardEvent ;
              rdfs:subClassOf+ kwg-ont:NOAAFlood .  # ensure it is a flood-specific hazard

  OPTIONAL { ?floodEvent ?property ?value }        # retrieve any available attribute/value pairs

  OPTIONAL {
    ?floodEvent geo:hasGeometry ?geometry .
    ?geometry geo:sfWithin/kwg-ont:spatialRelation* ?place .   # link to geographical place via geometry containment or direct spatial relation
    FILTER NOT EXISTS { ?place a kwg-ont:Hazard }               # ensure the place is not itself a hazard class
  }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?property ?value
WHERE {
  ?place a kwg-ont:AdministrativeRegion ;
         geo:hasGeometry|geo:hasDefaultGeometry [] .

  OPTIONAL {
    ?obs sosa:hasFeatureOfInterest ?place ;
         sosa:observedProperty ?property ;
         sosa:hasSimpleResult ?value .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?hazardType ?superType ?property ?value
WHERE {
  ?hazardType a kwg-ont:Hazard .
  OPTIONAL { ?hazardType rdfs:subClassOf ?superType . }
  OPTIONAL { ?hazardType ?property ?value . }
}
ORDER BY ?hazardType

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?hazardEvent ?impactProperty ?impactValue
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
  ?impactObservation a kwg-ont:ImpactObservation ;
                    sosa:hasFeatureOfInterest ?hazardEvent ;
                    sosa:observedProperty ?impactProperty ;
                    sosa:hasSimpleResult ?impactValue .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>

SELECT DISTINCT ?impactDetail
WHERE {
  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:hasFeatureOfInterest ?hazard .
  ?impactObservation kwg-ont:hasSimpleResult ?impactDetail .
  ?hazard a kwg-ont:Hazard .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazardType ?attributeProp ?attributeValue ?impactProp ?impactValue ?temporalData
WHERE {
  # Hurricane-specific hazard types (subclasses of NOAAHazardEvent that represent hurricanes)
  ?hazardType rdfs:subClassOf+ kwg-ont:NOAAHazardEvent ;
              rdfs:subClassOf ?specificHurricaneType .
  FILTER(regex(str(?specificHurricaneType), "Hurricane", "i"))

  # Hazard attributes related to the geographical place (via observed properties)
  OPTIONAL {
    ?observation sosa:observedProperty ?attributeProp ;
                 sosa:hasFeatureOfInterest ?hazardInstance ;
                 sosa:phenomenonTime ?temporalData .
    ?hazardInstance a ?specificHurricaneType ;
                    geo:asWKT ?geom .      # ensures the hazard is linked to a geographical place
    FILTER NOT EXISTS { ?observation sosa:hasSimpleResult [] }  # exclude simple results that are not attributes
    BIND(?attributeProp AS ?attributeProp)
    BIND(?observation AS ?attributeValue)  # placeholder for attribute value; actual literal would be bound via specific patterns if defined
  }

  # Damage impact details (via ImpactObservation and its observed properties)
  OPTIONAL {
    ?impactObs a kwg-ont:ImpactObservation ;
               sosa:hasFeatureOfInterest ?hazardInstance ;
               sosa:observedProperty ?impactProp ;
               sosa:phenomenonTime ?temporalData2 .
    BIND(?impactProp AS ?impactProp)
    BIND(?impactObs AS ?impactValue)  # placeholder for impact value; actual literal would be bound via hasSimpleResult if defined
  }

  # Temporal data, either from the hazard or the impact observation
  OPTIONAL { BIND(COALESCE(?temporalData, ?temporalData2) AS ?temporalData) }
}
ORDER BY ?hazardType ?attributeProp ?impactProp

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?impact ?property ?value
WHERE {
  ?impact a kwg-ont:ImpactObservation ;
          sosa:hasFeatureOfInterest ?hazard .

  ?hazard a kwg-ont:NOAATornado .  % tornado-specific hazard

  OPTIONAL { ?hazard geo:hasGeometry ?geom . }  % related to a geographical place (optional, just to ensure spatial relation)

  OPTIONAL {
    BIND(BINDING_EXISTS(?impact ?property ?value) AS ?exists)
    FILTER NOT EXISTS { ?impact ?exclProp ?exclValue .
                        VALUES ?exclProp { kwg-ont:phenomenonTime geo:hasGeometry } }
    ?impact ?property ?value .
  }

  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?temporalExtent .
    FILTER ( ?temporalExtent >= "$START_TEMPORAL"^^xsd:dateTime && ?temporalExtent <= "$END_TEMPORAL"^^xsd:dateTime )
  }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?impactProperty ?impactValue
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          kwg-ont:hasTemporalScope ?eventTime .

  FILTER ( ?eventTime instanceof time:Interval )

  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:hasFeatureOfInterest ?hazard ;
                     sosa:phenomenonTime ?impactTime ;
                     sosa:observedProperty ?impactProperty .

  FILTER ( ?impactTime >= ?eventTime/^time:hasBeginning && ?impactTime <= ?eventTime/^time:hasEnd )

  ?impactObservation kwg-ont:hasSimpleResult ?impactValue .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?name
WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?name .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place 
       (kwgl-ont:percentBelowPovertyLine AS ?percentBelowPovertyLine)
       (kwgl-ont:percentDiabetic      AS ?percentDiabetic)
       (kwgl-ont:percentObese         AS ?percentObese)
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?p1 . }
  OPTIONAL { ?place kwgl-ont:percentDiabetic      ?p2 . }
  OPTIONAL { ?place kwgl-ont:percentObese         ?p3 . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?population ?households
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population } .
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
SELECT DISTINCT ?hazardType (COUNT(DISTINCT ?event) AS ?count)
FROM <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
WHERE {
  ?event a kwglr:Earthquake ;
         kwgl-ont:hasHazardType ?hazardType .
}
GROUP BY ?hazardType
ORDER BY ?hazardType

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attr (COUNT(DISTINCT ?place) AS ?count)
WHERE {
  ?event a kwgl-ont:Tornado ;
         kwgl-ont:hasImpacted ?place .
  ?event ?p ?o .
  BIND(?p AS ?attr)
}
GROUP BY ?attr
ORDER BY ?attr

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?hazardAttribute ?place
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType ?hazardType .

  FILTER (?hazardType IN (
    kwglr:hurricane,
    kwglr:tornado,
    kwglr:stormSurgeTide,
    kwglr:winterStorm,
    kwglr:wildfire
  ))

  # Retrieve relevant hazard‑specific details (date range, damages)
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?event kwgl-ont:hasEndDate   ?endDate   }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfra }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars          ?damageCrop }

  # Link to the impacted place
  ?event kwgl-ont:hasImpacted ?place .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place 
       (kwgl-ont:averageCoolingDegreeDaysPerMonth AS ?avgCDD)
WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:averageCoolingDegreeDaysPerMonth ?avgCDD .
}
UNION
SELECT ?place 
       (kwgl-ont:averageHeatingDegreeDaysPerMonth AS ?avgHDD)
WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:averageHeatingDegreeDaysPerMonth ?avgHDD .
}
UNION
SELECT ?place 
       (kwgl-ont:averageMonthlyTemperatureInCelsius AS ?avgTempC)
WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:averageMonthlyTemperatureInCelsius ?avgTempC .
}
UNION
SELECT ?place 
       (kwgl-ont:maximumMonthlyTemperatureInCelsius AS ?maxTempC)
WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:maximumMonthlyTemperatureInCelsius ?maxTempC .
}
UNION
SELECT ?place 
       (kwgl-ont:minimumMonthlyTemperatureInCelsius AS ?minTempC)
WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:minimumMonthlyTemperatureInCelsius ?minTempC .
}
UNION
SELECT ?place 
       (kwgl-ont:dollarDamageOfFiresImpactingPlace AS ?fireDamageUSD)
WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:dollarDamageOfFiresImpactingPlace ?fireDamageUSD .
}
UNION
SELECT ?place 
       (kwgl-ont:numberOfDeaths AS ?deaths)
WHERE {
  ?place a kwgl-ont:HazardEvent ;
         kwgl-ont:numberOfDeaths ?deaths .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?event
       ?affectedAreaInAcres
       ?damageToCropsInDollars
       ?damageToInfrastructureInDollars
       ?numberOfDeaths
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres ;
         kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars ;
         kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars ;
         kwgl-ont:numberOfDeaths ?numberOfDeaths .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazardEvent ?damageToCropsInDollars ?damageToInfrastructureInDollars
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars ;
               kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazardEvent ?attributeName ?attributeValue ?place (COALESCE(?start ?end) AS ?temporalData)
FROM <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
WHERE {
  # Identify hurricane events and their related places
  ?hazardEvent a kwgl-ont:Hurricane ;
               kwgl-ont:hasImpacted ?place .

  # Retrieve all hazard‑specific attributes of the hurricane event
  OPTIONAL { 
    ?hazardEvent ?attrPredicate ?attributeValue . 
    BIND (STR(?attrPredicate) AS ?attributeName)
  }

  # Gather any temporal information (start or end date) for the hurricane
  OPTIONAL {
    ?hazardEvent kwgl-ont:hasStartDate ?start .
    UNION
    { ?hazardEvent kwgl-ont:hasEndDate   ?end . }
  }
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?event ?impactedPlace 
       ?cropDamage ?infrastructureDamage ?deathCount 
WHERE {
  ?event a kwgl-ont:Tornado ;
         kwgl-ont:hasImpacted ?impactedPlace .

  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars    ?cropDamage        }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths           ?deathCount       }

  FILTER ( 
    EXISTS {
      ?event kwgl-ont:hasStartDate ?startDate .
      FILTER ( xsd:date(?startDate) >= "2023-01-01"^^xsd:date )
    } &&
    EXISTS {
      ?event kwgl-ont:hasEndDate   ?endDate .
      FILTER ( xsd:date(?endDate)   <= "2024-12-31"^^xsd:date )
    }
  )
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?event ?damageToCrops ?damageToInfrastructure 
       ?affectedArea ?startDate ?endDate
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType ?hazardType .

  FILTER (?hazardType IN (kwgl-ont:hurricane,
                          kwgl-ont:tornado,
                          kwgl-ont:stormSurgeTide))

  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCrops }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea }
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate }

  FILTER EXISTS {
    ?event kwgl-ont:hasImpacted ?place .
    ?place a kwgl-ont:Place .

    # Temporal extent filter (adjust the literals as needed)
    FILTER (?startDate >= "2022-01-01"^^xsd:date && ?endDate <= "2023-12-31"^^xsd:date)
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazard ?type ?startDate ?endDate
WHERE {
  ?hazard a kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate   ?endDate . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?name WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?attribute ?value
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households . }
  BIND (kwgl-ont:hasPopulation AS ?attribute) ON FILTER EXISTS { ?place kwgl-ont:hasPopulation ?_ . }
  BIND (?population AS ?value)
  UNION
  BIND (kwgl-ont:hasNumberOfHouseHolds AS ?attribute) ON FILTER EXISTS { ?place kwgl-ont:hasNumberOfHouseHolds ?_ . }
  BIND (?households AS ?value)
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazardType (COUNT(DISTINCT ?event) AS ?count)
WHERE {
  ?event a kwgl-ont:Earthquake ;
         kwgl-ont:hasHazardType ?hazardType .
}
GROUP BY ?hazardType

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?label
  ?range
WHERE {
  ?attribute rdf:type owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place .

  OPTIONAL { ?attribute rdfs:label ?label . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") ||
    CONTAINS(LCASE(STR(?label)), "flood")
  )
}
ORDER BY ?attribute

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazardEvent ?typeLabel ?details
WHERE {
  ?hazardEvent a kwgl-ont:Earthquake ;
               kwgl-ont:hasHazardType ?type .

  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?area . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }

  BIND (COALESCE(?name, "") AS ?nameVal)
  BIND (COALESCE(str(?deaths), "") AS ?deathsVal)
  BIND (COALESCE(str(?infrastructureDamage), "") AS ?infraVal)
  BIND (COALESCE(str(?cropDamage), "") AS ?cropVal)
  BIND (COALESCE(str(?area), "") AS ?areaVal)
  BIND (COALESCE(str(?startDate), "") AS ?startVal)
  BIND (COALESCE(str(?endDate), "") AS ?endVal)

  BIND (CONCAT("Name: ", ?nameVal,
               "; Deaths: ", ?deathsVal,
               "; Infrastructure Damage ($): ", ?infraVal,
               "; Crop Damage ($): ", ?cropVal,
               "; Affected Area (acres): ", ?areaVal,
               "; Start Date: ", ?startVal,
               "; End Date: ", ?endVal) AS ?details)

  OPTIONAL { ?type rdfs:label ?typeLabel }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?event
  ?damageToCropsInDollars
  ?damageToInfrastructureInDollars
WHERE {
  ?event a kwgl-ont:HazardEvent .

  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?damageProperty ?value
WHERE {
  ?place kwgl-ont:impactedBy ?hazard .   # ensure the place is impacted by a hazard event
  OPTIONAL { ?place kwgl-ont:damageToCropsInDollars ?value . BIND(kwgl-ont:damageToCropsInDollars AS ?damageProperty) }
  OPTIONAL { ?place kwgl-ont:damageToInfrastructureInDollars ?value . BIND(kwgl-ont:damageToInfrastructureInDollars AS ?damageProperty) }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?value . BIND(kwgl-ont:dollarDamageOfFiresImpactingPlace AS ?damageProperty) }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?value . BIND(kwgl-ont:dollarDamageOfFloodsImpactingPlace AS ?damageProperty) }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?value . BIND(kwgl-ont:dollarDamageOfHurricanesImpactingPlace AS ?damageProperty) }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?value . BIND(kwgl-ont:dollarDamageOfLandslidesImpactingPlace AS ?damageProperty) }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?value . BIND(kwgl-ont:dollarDamageOfStormSurgesImpactingPlace AS ?damageProperty) }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?value . BIND(kwgl-ont:dollarDamageOfTornadoesImpactingPlace AS ?damageProperty) }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place
       ?hurricaneCount
       ?damageDollars
       ?startDate
       ?endDate
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType kwgl-ont:hurricane .   # hurricane‑specific hazard

  ?event kwgl-ont:hasImpacted ?place .                # related to a geographical place

  OPTIONAL { ?event kwgl-ont:numberOfHurricanesImpactingPlace ?hurricaneCount } 
  OPTIONAL { ?event kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?damageDollars }
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?event kwgl-ont:hasEndDate   ?endDate }
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?damageAmount
WHERE {
  ?hazard a kwgl-ont:Tornado ;
          kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damageAmount ;
          kwgl-ont:hasStartDate ?startDate ;
          kwgl-ont:hasEndDate   ?endDate .

  FILTER (xsd:date(?startDate) >= "2022-01-01"^^xsd:date && xsd:date(?endDate) <= "2022-12-31"^^xsd:date)

  ?place a kwgl-ont:Place ;
         kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damageAmount .
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?damageProperty ?damageValue
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType ?hazardType .

  FILTER (?hazardType IN (kwgl-ont:hurricane, kwgl-ont:stormSurgeTide))

  ?hazard kwgl-ont:hasStartDate ?startDate ;
          kwgl-ont:hasEndDate   ?endDate .

  # Temporal extent filter – adjust the literals as needed
  FILTER (?startDate >= "2020-01-01"^^xsd:date && ?endDate <= "2022-12-31"^^xsd:date)

  ?hazard kwgl-ont:impactedBy ?place .

  OPTIONAL { 
    BIND (IF(BOUND(?d2018), ?d2018,
             IF(BOUND(?d2019), ?d2019,
                 IF(BOUND(?d2020), ?d2020,
                     IF(BOUND(?d2021), ?d2021, ?d2022)))) AS ?damageValue)
    BIND (IF(BOUND(?d2018), kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018,
             IF(BOUND(?d2019), kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019,
                 IF(BOUND(?d2020), kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020,
                     IF(BOUND(?d2021), kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021, 
                         kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022)))) AS ?damageProperty)
    OPTIONAL { ?place ?damageProperty ?d2018 }
    OPTIONAL { ?place ?damageProperty ?d2019 }
    OPTIONAL { ?place ?damageProperty ?d2020 }
    OPTIONAL { ?place ?damageProperty ?d2021 }
    OPTIONAL { ?place ?damageProperty ?d2022 }
  }
}
ORDER BY ?place

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?event ?eventType ?startDate ?endDate
       ?impactedPlace ?placeName
       ?affectedArea ?damageCrops ?damageInfra ?numberOfDeaths
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?event kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?event kwgl-ont:hasEndDate   ?endDate   . }

  OPTIONAL {
    ?event kwgl-ont:hasImpacted ?place .
    ?place kwgl-ont:hasName ?placeName .
  }

  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres      ?affectedArea        . }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars   ?damageCrops         . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfra . }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths           ?numberOfDeaths      . }

  BIND(COALESCE(str(?hazardType), "unknown") AS ?eventType)
}
ORDER BY ?event

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?place
  (CONCAT('hasPopulation: ', STR(?pop)) AS ?healthAttr)
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?pop . }
}
UNION
SELECT DISTINCT
  ?place
  (CONCAT('percentBelowPovertyLine: ', STR(?pov)) AS ?healthAttr)
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?pov . }
}
UNION
SELECT DISTINCT
  ?place
  (CONCAT('percentDiabetic: ', STR(?diag)) AS ?healthAttr)
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diag . }
}
UNION
SELECT DISTINCT
  ?place
  (CONCAT('percentObese: ', STR(?obes)) AS ?healthAttr)
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:percentObese ?obes . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?hazardType (COUNT(DISTINCT ?event) AS ?count)
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType ?hazardType .
  FILTER regex(STR(?hazardType), "earthquake", "i")
} GROUP BY ?hazardType

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute (COUNT(DISTINCT ?place) AS ?count)
WHERE {
  ?attribute rdf:type owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place ;
             rdfs:label ?label .
  FILTER(CONTAINS(LCASE(STR(?label)), "tornado"))

  ?place a kwgl-ont:Place ;
         ?attribute ?value .
}
GROUP BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?label
WHERE {
  ?attribute rdf:type owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place ;
             rdfs:label ?label .

  FILTER (CONTAINS(LCASE(STR(?attribute)), "storm") || CONTAINS(LCASE(STR(?label)), "storm"))
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
WHERE {
  ?attribute rdf:type owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place .

  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "flood")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
WHERE {
  ?attribute rdf:type owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place .
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazardEvent
  ?eventType
  (GROUP_CONCAT(?prop; SEPARATOR='|') AS ?details)
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .

  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?area . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamage . }

  BINDINGS (?prop) AS (
    (str(?name)        -> "name")
    (concat("start date:", STR(?startDate))   -> "start_date")
    (concat("end date:", STR(?endDate))       -> "end_date")
    (concat("deaths:", STR(?deaths))          -> "deaths")
    (concat("affected area (acres):", STR(?area)) -> "affected_area_acres")
    (concat("infrastructure damage ($):", STR(?infrastructureDamage)) -> "infrastructure_damage")
    (concat("crop damage ($):", STR(?cropDamage)) -> "crop_damage")
  )

  FILTER EXISTS {
    ?hazardEvent kwgl-ont:hasHazardType ?eventType .
    FILTER (?eventType = kwglr:earthquake)
  }
}
GROUP BY ?hazardEvent ?eventType

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?event
       ?hasName
       ?hasStartDate
       ?hasEndDate
       ?hasHazardType
       ?affectedAreaInAcres
       ?damageToCropsInDollars
       ?damageToInfrastructureInDollars
       ?numberOfDeaths
WHERE {
  ?event a kwgl-ont:HazardEvent .
  OPTIONAL { ?event kwgl-ont:hasName          ?hasName }
  OPTIONAL { ?event kwgl-ont:hasStartDate    ?hasStartDate }
  OPTIONAL { ?event kwgl-ont:hasEndDate      ?hasEndDate }
  OPTIONAL { ?event kwgl-ont:hasHazardType   ?hasHazardType }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars          ?damageToCropsInDollars }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths               ?numberOfDeaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?event ?property ?value
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         ?property ?value .

  FILTER ( 
    ?property IN (
      kwgl-ont:damageToCropsInDollars,
      kwgl-ont:damageToInfrastructureInDollars,
      kwgl-ont:affectedAreaInAcres,
      kwgl-ont:numberOfDeaths
    )
  )
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?property (STR(?label) AS ?labelStr)
WHERE {
  { ?property rdf:type owl:DatatypeProperty ;
              rdfs:domain kwgl-ont:HazardEvent ;
              rdfs:range ?range .
    OPTIONAL { ?property rdfs:label ?label } }
  UNION
  { ?property rdf:type owl:DatatypeProperty ;
              rdfs:domain kwgl-ont:Place ;
              rdfs:range xsd:nonNegativeInteger .
    FILTER (CONTAINS(LCASE(STR(?property)), "hurricane")) 
    OPTIONAL { ?property rdfs:label ?label } }
  UNION
  { ?event a kwgl-ont:Hurricane ;
           kwgl-ont:hasStartDate ?startDate ;
           kwgl-ont:hasEndDate ?endDate .
    BIND(kwgl-ont:hasStartDate AS ?property)
    OPTIONAL { ?prop rdfs:label ?label } }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?event ?damageCrops ?damageInfrastructure
WHERE {
  ?event rdf:type kwgl-ont:Tornado ;
         kwgl-ont:hasStartDate ?start ;
         kwgl-ont:hasEndDate ?end .
  FILTER ( ?start >= "2020-01-01"^^xsd:date && ?end <= "2023-12-31"^^xsd:date )
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?damage
WHERE {
  { 
    ?event a (kwgl-ont:Hurricane) ;
           kwgl-ont:hasHazardType ?hazardType . 
    FILTER(?hazardType IN (
      kwglr:hurricane,
      kwglr:tropicalStorm,
      kwglr:tropicalDepression))
    OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damage }
    OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damage }
  } 
  UNION
  {
    ?place a kwgl-ont:Place ;
           kwgl-ont:impactedBy / kwgl-ont:hasHazardType ?hazardType .
    FILTER(?hazardType IN (
      kwglr:hurricane,
      kwglr:tornado,
      kwglr:stormSurgeTide))
    OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?damage }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damage }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?damage }
  }
  FILTER (BOUND(?damage))
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?doiString
WHERE {
  ?publication a coresr-ont:Publication .
  OPTIONAL { 
    ?publication coresr-ont:hasIdentifier ?doi . 
    ?doi coresr-ont:doiAsString ?doiString 
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?department
WHERE {
