PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazard ?place 
       ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars
       ?dollarDamageOfHurricanesImpactingPlace ?startDate ?endDate
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType kwglr:hurricane ;   # hurricane-specific hazard
          kwgl-ont:impactedBy ?place .               # related to a geographical place

  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }

  # Damage impact details for hurricanes on the place
  OPTIONAL {
    ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfHurricanesImpactingPlace .
  }

  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate   ?endDate }
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?damageYear ?damageAmount
WHERE {
  ?hazard a kwgl-ont:Tornado ;
          kwgl-ont:hasStartDate ?startDate ;
          kwgl-ont:hasEndDate   ?endDate .

  FILTER (?startDate >= "2022-01-01"^^xsd:date && ?endDate <= "2022-12-31"^^xsd:date)

  ?hazard kwgl-ont:impactedBy ?place .

  OPTIONAL { BIND (kwgl-ont:dollarDamageOfTornadoesImpactingPlace2018 AS ?damageProp) }
  OPTIONAL { BIND (kwgl-ont:dollarDamageOfTornadoesImpactingPlace2019 AS ?damageProp) }
  OPTIONAL { BIND (kwgl-ont:dollarDamageOfTornadoesImpactingPlace2020 AS ?damageProp) }
  OPTIONAL { BIND (kwgl-ont:dollarDamageOfTornadoesImpactingPlace2021 AS ?damageProp) }
  OPTIONAL { BIND (kwgl-ont:dollarDamageOfTornadoesImpactingPlace2022 AS ?damageProp) }

  ?place ?damageProp ?damageAmount .

  BIND (YEAR(STR(?damageProp)) AS ?damageYear)
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?hazard ?temporalScope ?geometry
WHERE {
  ?hazard a kwg-ont:Hazard .
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?temporalScope . }
  OPTIONAL { ?hazard geo:hasGeometry ?geometry . }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
SELECT ?place ?name
WHERE {
  ?place a geo:SpatialObject ;
         rdfs:label ?name .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?place ?property ?value
WHERE {
  ?place a kwg-ont:AdministrativeRegion ;            # any geographical place (administrative region)
    geo:hasGeometry ?geom .                         # ensure it is a geographic feature

  {                                                   # public health observations related to the place
    ?phObs a kwg-ont:PublicHealthObservation ;
           sosa:hasFeatureOfInterest ?place ;
           sosa:observedProperty ?property ;
           sosa:hasSimpleResult ?value .
  }
  UNION
  {                                                   # vulnerability observations related to the place
    ?vulnObs a kwg-ont:VulnerabilityObservation ;
             sosa:hasFeatureOfInterest ?place ;
             sosa:observedProperty ?property ;
             sosa:hasSimpleResult ?value .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?hazard (COUNT(?hazard) AS ?count)
WHERE {
  ?hazard a kwg-ont:Hazard ;
          a kwg-ont:Earthquake .
} GROUP BY ?hazard

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?attribute (COUNT(DISTINCT ?hazard) AS ?count)
WHERE {
  ?hazard a kwg-ont:NOAATornado ;
          sosa:observedProperty ?property .
  ?property rdfs:subClassOf+ kwg-ont:MagnitudeObservableProperty .
}
GROUP BY ?attribute

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?hazardEvent ?observableProperty ?propertyLabel ?value
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
  OPTIONAL { ?hazardEvent rdfs:label ?propertyLabel . }
  ?hazardEvent geo:hasGeometry ?geometry .
  ?geometry geo:asWKT ?geomWKT .   # geometry details for the place
  ?obs kwg-ont:hasFeatureOfInterest ?hazardEvent ;
       sosa:observedProperty ?observableProperty ;
       sosa:hasSimpleResult ?value .
  FILTER ( ?observableProperty IN (
    kwg-ont:StormTrackletObservableProperty,
    kwg-ont:StormTrackObservableProperty
  ) )
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT DISTINCT ?hazardEvent ?attributeProperty ?attributeValue
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
               geo:hasGeometry ?geometry .

  # Restrict to flood-specific hazards (both general Flood and FlashFlood types)
  FILTER (?hazardEvent = kwg-ont:NOAAFlood || ?hazardEvent = kwg-ont:NOAAFlashFlood)

  # Retrieve observable properties that describe the hazard event
  ?observation a sosa:Observation ;
               sosa:observedProperty ?attributeProperty ;
               sosa:hasFeatureOfInterest ?hazardEvent ;
               sosa:hasSimpleResult ?attributeValue .
}
ORDER BY ?hazardEvent ?attributeProperty

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?hazard ?details ?type
WHERE {
  ?hazard a kwg-ont:Hazard .
  OPTIONAL { ?hazard geo:hasGeometry ?geometry . }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?temporalScope . }
  BIND (CONCAT("Hazard ID: ", STR(?hazard),
               "; Geometry: ", COALESCE(STR(?geometry), "None"),
               "; Temporal Scope: ", COALESCE(STR(?temporalScope), "None")) AS ?details)
  BIND (TYPE_OF_SUBCLASS(?hazard) AS ?type)
}

# Helper function to retrieve the specific subclass type of a hazard
# In SPARQL this can be approximated with UNION of patterns for each known concrete subclass:
BIND (
  COALESCE(
    IF(?hazard a kwg-ont:Earthquake, "kwg-ont:Earthquake",
       IF(?hazard a kwg-ont:FEMADisaster, "kwg-ont:FEMADisaster",
         ...
         "Unknown"
       )
    )
  ) AS ?type
)

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?hazardEvent ?impactProperty ?simpleResult
WHERE {
  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:hasFeatureOfInterest ?hazardEvent ;
                     sosa:observedProperty ?impactProperty ;
                     sosa:hasSimpleResult ?simpleResult .
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?attribute ?value ?impactType ?damageValue ?temporal
WHERE {
  # Hurricane‑specific hazard (sub‑class of NOAAHazardEvent)
  ?hazard a kwg-ont:NOAAHazardEvent ;
          rdfs:subClassOf+ kwg-ont:NOAATropicalStorm .   # assumes tropical storm class represents hurricanes

  # Hazard attributes related to the geographical place
  {
    SELECT ?hazard ?attribute ?value
    WHERE {
      ?obs a sosa:Observation ;
           sosa:hasFeatureOfInterest ?hazard ;
           sosa:observedProperty ?attribute .
      OPTIONAL { ?obs sosa:hasSimpleResult ?value }
    }
  }

  # Damage impact details and their temporal data (if available)
  {
    SELECT ?hazard ?impactType ?damageValue ?temporal
    WHERE {
      ?imp a kwg-ont:ImpactObservation ;
           sosa:hasFeatureOfInterest ?hazard ;
           sosa:observedProperty ?impactType .
      OPTIONAL { ?imp sosa:hasSimpleResult ?damageValue }
      OPTIONAL { ?imp sosa:phenomenonTime ?temporal }
    }
  }
}

