PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place 
       OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace ?numFloods }
       OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?damageFlood }
       OPTIONAL { ?place kwgl-ont:affectedAreaInAcres ?areaAcres }
WHERE {
  ?place a kwgl-ont:Place .
  # Ensure the place is associated with at least one flood hazard
  FILTER EXISTS {
    ?hazard a kwgl-ont:HazardEvent ;
           kwgl-ont:hasHazardType kwgl-ont:flood ;
           kwgl-ont:impactedBy ?place .
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?property ?value
WHERE {
  ?place a kwgl-ont:Place .
  { 
    VALUES ?property {
      kwgl-ont:averageCoolingDegreeDaysPerMonth
      kwgl-ont:averageHeatingDegreeDaysPerMonth
      kwgl-ont:averageMonthlyTemperatureInCelsius
      kwgl-ont:maximumMonthlyTemperatureInCelsius
      kwgl-ont:minimumMonthlyTemperatureInCelsius
    }
    ?place ?property ?value .
  } UNION {
    VALUES ?property {
      kwgl-ont:dollarDamageOfFiresImpactingPlace
      kwgl-ont:dollarDamageOfFloodsImpactingPlace
      kwgl-ont:dollarDamageOfHurricanesImpactingPlace
      kwgl-ont:dollarDamageOfLandslidesImpactingPlace
      kwgl-ont:dollarDamageOfStormSurgesImpactingPlace
      kwgl-ont:dollarDamageOfTornadoesImpactingPlace
    }
    ?place ?property ?value .
  } UNION {
    VALUES ?property {
      kwgl-ont:numberOfEarthquakesImpactingPlace
      kwgl-ont:numberOfFiresImpactingPlace
      kwgl-ont:numberOfFloodsImpactingPlace
      kwgl-ont:numberOfHurricanesImpactingPlace
      kwgl-ont:numberOfLandslidesImpactingPlace
      kwgl-ont:numberOfStormSurgesImpactingPlace
      kwgl-ont:numberOfTornadoesImpactingPlace
    }
    ?place ?property ?value .
  } 
}

