SELECT ?hazardEvent ?type ?name ?startDate ?endDate 
       ?affectedAreaInAcres ?damageToInfrastructureInDollars ?damageToCropsInDollars
WHERE {
  ?hazardEvent a kwgl-ont:Earthquake .          # Earthquake hazards are instances of kwgl-ont:Earthquake
  ?hazardEvent kwgl-ont:hasHazardType ?type .   # Their type is given by hasHazardType (should be kwglr:earthquake)
  OPTIONAL { ?hazardEvent kwgl-ont:hasName          ?name        } 
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate     ?startDate   }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate       ?endDate     }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres      ?affectedAreaInAcres      }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars        ?damageToCropsInDollars        }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?event ?damageCrops ?damageInfrastructure
WHERE {
  ?event a kwgl-ont:HazardEvent .
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place 
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
         kwgl-ont:hasImpacted ?place .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazard ?attributeValue ?damageDetail ?tempStart ?tempEnd
WHERE {
  ?hazard a kwgl-ont:Hurricane ;
          kwgl-ont:hasImpacted ?place .

  # Hurricane‑specific attributes (all numeric properties defined for HazardEvent)
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?attributeValue . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?attributeValue . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?attributeValue . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?attributeValue . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?tempStart . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?tempEnd . }

  # Damage impact details for the impacted place
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?damageDetail . }
}
ORDER BY ?hazard

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?damageDetail
WHERE {
  ?hazardEvent a kwgl-ont:Tornado ;
               kwgl-ont:hasHazardType kwgl-ont:tornado ;
               kwgl-ont:impactedBy ?place .

  ?place a kwgl-ont:Place ;
         kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damageDetail .

  FILTER (bound(?hazardEvent) && bound(?place))
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazardEvent ?damageProperty ?damageValue
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType ?hazardType .

  FILTER (?hazardType IN (kwglr:hurricane,
                          kwglr:tropicalStorm,
                          kwglr:tropicalDepression,
                          kwglr:stormSurgeTide))

  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageValue . BIND ("damageToInfrastructureInDollars" AS ?damageProperty) }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageValue . BIND ("damageToCropsInDollars" AS ?damageProperty) }

  FILTER (BOUND(?damageValue))

  ?place a kwgl-ont:Place ;
         kwgl-ont:hasImpacted ?hazardEvent .

  OPTIONAL {
    ?hazardEvent kwgl-ont:hasStartDate ?startDate .
    ?hazardEvent kwgl-ont:hasEndDate   ?endDate .
    FILTER (?startDate >= "2020-01-01"^^xsd:date && ?endDate <= "2022-12-31"^^xsd:date)
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?details ?when
WHERE {
  { ?hazard a kwg-ont:Hazard . }
  UNION
  { ?event a kwg-ont:NOAAHazardEvent . OPTIONAL { ?event geo:hasDefaultGeometry ?geometry . } }

  # Details can be geometry, name or disaster ID where available
  OPTIONAL { ?hazard/geo:hasDefaultGeometry ?details . }
  OPTIONAL { ?event kwg-ont:hasDisasterName ?details . }
  OPTIONAL { ?event kwg-ont:noaaDisasterID ?details . }

  # When can be the temporal scope (instant or interval) of the hazard/event
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?when . }
  UNION
  OPTIONAL { ?event sosa:phenomenonTime ?when . }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
SELECT ?place ?name WHERE {
  ?place a geo:Feature ;
         geo:hasDefaultGeometry ?geometry .
  OPTIONAL { ?place rdfs:label ?name }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?place ?healthAttribute
WHERE {
  { 
    # Health-related observations linked to administrative places (e.g., PublicHealthObservation)
    ?obs a kwg-ont:PublicHealthObservation ;
         sosa:hasFeatureOfInterest ?place .
    ?obs a ?healthClass .  # capture the class/type of the observation as health attribute
    BIND(IRI(STR(?healthClass)) AS ?healthAttribute)
  }
  UNION
  { 
    # Health-related hazards affecting places (e.g., DroughtZone, Earthquake)
    ?hazard a kwg-ont:DroughtZone ;
            kwg-ont:spatialRelation ?place .
    BIND(kwg-ont:DroughtZone AS ?healthAttribute) .
    BIND(?hazard AS ?place)
  }
  UNION
  { 
    ?hazard a kwg-ont:Earthquake ;
            kwg-ont:spatialRelation ?place .
    BIND(kwg-ont:Earthquake AS ?healthAttribute) .
    BIND(?hazard AS ?place)
  }
  UNION
  { 
    # Health care facilities as health attributes of places
    ?facility a kwg-ont:HealthCareFacility ;
              kwg-ont:sfWithin ?place .
    BIND(kwg-ont:HealthCareFacility AS ?healthAttribute) .
    BIND(?facility AS ?place)
  }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?place ?property ?value
WHERE {
  ?observation a sosa:Observation ;
               sosa:observedProperty ?property ;
               sosa:resultValue ?value ;
               sosa:hasFeatureOfInterest ?place .

  { ?property = kwg-ont:censusObservableProperty.femalePopulation ||
                ?property = kwg-ont:censusObservableProperty.householdUnits ||
                ?property = kwg-ont:censusObservableProperty.malePopulation ||
                ?property = kwg-ont:censusObservableProperty.totalPopulation }

  { ?place a geo:Feature } .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?earthquake (COUNT(?earthquake) AS ?count)
WHERE {
  ?earthquake a kwg-ont:Earthquake .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT DISTINCT ?tornadoAttr (COUNT(DISTINCT ?tornadoAttr) AS ?count)
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
               a kwg-ont:NOAATornado .
  ?obsCollection a kwg-ont:ObservationCollection ;
                 sosa:hasMember ?observation .
  ?observation a kwg-ont:MagnitudeObservation ;
               sosa:observedProperty ?tornadoAttr ;
               sosa:hasFeatureOfInterest ?hazardEvent .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?hazard ?attribute ?value
WHERE {
  # Storm-specific hazards (storm tracks and tracklets)
  { ?hazard a kwg-ont:StormTrack } 
   UNION 
  { ?hazard a kwg-ont:StormTracklet }

  # Retrieve observed properties that are specific to storms
  ?obs a kwg-ont:StormTrackObservation ;
       sosa:hasFeatureOfInterest ?hazard ;
       sosa:observedProperty ?attribute ;
       sosa:result ?value .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?hazard ?attribute ?value
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          a kwg-ont:Flood .

  OPTIONAL { 
    ?observation a kwg-ont:MagnitudeObservation ;
                 sosa:observedProperty ?attribute ;
                 sosa:resultValue ?value ;
                 sosa:hasFeatureOfInterest ?hazard .
    FILTER (isIRI(?attribute) && STRSTARTS(STR(?attribute), "http://example.org/kwg-ont#magnitudeObservableProperty"))
  }

  UNION

  OPTIONAL { 
    ?droughtZone a kwg-ont:DroughtZone ;
                 kwg-ont:hasTemporalScope ?ts .
    ?overlapObs a kwg-ont:DroughtZoneOverlapObservation ;
                sosa:observedProperty ?attribute ;
                sosa:resultValue ?value ;
                sosa:hasFeatureOfInterest ?droughtZone .
    FILTER (isIRI(?attribute) && STRSTARTS(STR(?attribute), "http://example.org/kwg-ont#DroughtIntensity"))
  }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?climateProperty ?place
WHERE {
  ?obs a kwg-ont:ClimateObservation ;
       sosa:observedProperty ?climateProperty .

  # Identify the geographical place (FeatureOfInterest) for each climate observation
  OPTIONAL { ?obs sosa:hasFeatureOfInterest ?place . }
  FILTER NOT EXISTS {
    # Prefer places that are explicitly linked via hasFeatureOfInterest;
    # otherwise, fall back to spatial relation if present.
    BIND(coalesce(?place, NULL) AS ?fallback)
    FILTER NOT EXISTS { ?obs kwg-ont:spatialRelation ?fallback . }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?earthquake ?type ?detailProp ?detailValue
WHERE {
  ?earthquake a kwg-ont:Earthquake ;
              kwg-ont:typeOfHazard ?type .

  OPTIONAL { ?earthquake kwg-ont:earthquakeObservableProperty:depth ?detailProp ; ?detailProp ?detailValue }
  OPTIONAL { ?earthquake kwg-ont:earthquakeObservableProperty:dmin ?detailProp ; ?detailProp ?detailValue }
  OPTIONAL { ?earthquake kwg-ont:earthquakeObservableProperty:mag ?detailProp ; ?detailProp ?detailValue }
  OPTIONAL { ?earthquake kwg-ont:earthquakeObservableProperty:type ?detailProp ; ?detailProp ?detailValue }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?hazardEvent ?observableProperty ?resultValue
WHERE {
  ?impactObservationCollection a kwg-ont:ImpactObservationCollection ;
                              sosa:hasFeatureOfInterest ?hazardEvent ;
                              sosa:hasMember ?impactObservation .
  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:observedProperty ?observableProperty ;
                     sosa:result ?resultValue .
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT DISTINCT ?impactObservation
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
  ?impactObservation a kwg-ont:ImpactObservation ;
                    sosa:hasFeatureOfInterest ?hazardEvent .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?attributeValue ?impactType ?damageDetails ?temporalData
WHERE {
  # Hurricane-specific hazard and its attributes related to a geographical place
  ?hazard a kwg-ont:NOAAHazardEvent ;
          a kwg-ont:NOAAHurricane ;
          sosa:hasFeatureOfInterest ?place .
  ?observation a sosa:Observation ;
               sosa:observedProperty ?attributeProp ;
               sosa:hasFeatureOfInterest ?hazard ;
               sosa:resultForm ?result .
  ?result a kwg-ont:HazardObservableProperty ;  # generic observable property for hazards
          rdf:value ?attributeValue .

  # Damage impact details and their temporal data (if available)
  ?impactObs a kwg-ont:ImpactObservation ;
             sosa:observedProperty ?impactTypeProp ;
             sosa:hasFeatureOfInterest ?hazard .
  ?impactObsResult a kwg-ont:ImpactObservableProperty ;  # result of impact observation
                  rdf:value ?damageDetails .

  OPTIONAL {
    ?impactObs sosa:phenomenonTime ?temporalData .
  }

  FILTER(?attributeProp != kwg-ont:Hazard)   # ensure we get specific attribute properties
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazardEvent ?damageProperty ?propertyDamageValue ?deathDirect ?injuryDirect
WHERE {
  # Storm-specific hazards (e.g., hurricane, tornado, etc.)
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
               a [ owl:oneOf (kwg-ont:NOAATornado kwg-ont:NOAAHurricane) ] .   # adjust the list as needed

  # Link to an observation that records damage details
  ?obs a sosa:Observation ;
       sosa:hasFeatureOfInterest ?hazardEvent ;
       sosa:observedProperty ?damageProp .

  # Ensure the observation is within the requested temporal extent
  ?obs time:atTime ?eventTime .
  FILTER ( ?eventTime >= $temporalStart && ?eventTime <= $temporalEnd )

  # The observed property must be a damage‑related impact observable property
  VALUES ?damageProp {
    kwg-ont:impactObservableProperty.damageCrop
    kwg-ont:impactObservableProperty.damageProperty
  }

  # Retrieve the actual damage value (e.g., amount, area)
  OPTIONAL { 
    ?obs sosa:result ?result .
    ?result a sosa:Result ;
            sosa:value ?propertyDamageValue .
  }

  # Retrieve direct death count if present
  OPTIONAL {
    FILTER NOT EXISTS { ?obs2 sosa:observedProperty kwg-ont:impactObservableProperty.deathDirect }
    BIND(?deathDirect AS ?deathDirect)
  }

  # Retrieve direct injury count if present
  OPTIONAL {
    FILTER NOT EXISTS { ?obs3 sosa:observedProperty kwg-ont:impactObservableProperty.injuryDirect }
    BIND(?injuryDirect AS ?injuryDirect)
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?details ?when
WHERE {
  ?hazard a kwg-ont:Hazard .
  OPTIONAL { ?hazard geo:hasGeometry ?geometry . }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?temporal . }
  BIND(COALESCE(?temporal, "") AS ?when)
  BIND(CONCAT("Hazard: ", STR(?hazard), 
              ". Geometry: ", IF(BOUND(?geometry), STR(?geometry), "none"),
              ". Temporal Scope: ", STR(?when)) AS ?details)
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?place ?name
WHERE {
  ?place a kwg-ont:AdministrativeRegion ;
         kwg-ont:hasName ?name .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?place ?healthConcernOrAttribute
WHERE {
  ?place a kwg-ont:AdministrativeRegion .

  OPTIONAL { ?place a kwg-ont:Hazard ; kwg-ont:hasTemporalScope ?time . BIND(?time AS ?healthConcernOrAttribute) }
  OPTIONAL { ?obs a sosa:Observation ;
                sosa:hasFeatureOfInterest ?place ;
                sosa:observedProperty ?prop .
             BIND(str(?prop) AS ?healthConcernOrAttribute) }
}

The query retrieves every `AdministrativeRegion` (i.e., all geographical places in the schema) and, for each place, returns any associated health‑related concern or attribute.  
- If the place itself is a `Hazard`, its temporal scope (`hasTemporalScope`) is returned as the health concern.  
- If there are observations linked to the place via `sosa:hasFeatureOfInterest` whose observed property represents a health‑related metric, that property’s URI is captured (using its string form) as the health attribute.  

This covers all available health‑related concerns or attributes for each geographical place according to the provided schema.

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?region ?observableProperty ?value
WHERE {
  ?region a kwg-ont:AdministrativeRegion ;
          sosa:hasFeatureOfInterest ?observation .

  ?observation a kwg-ont:CensusACS5YearEstimatesObservation ;
               sosa:observedProperty ?observableProperty ;
               sosa:hasSimpleResult ?value .

  FILTER(?observableProperty IN (
    kwg-ont:censusObservableProperty.totalPopulation,
    kwg-ont:censusObservableProperty.malePopulation,
    kwg-ont:censusObservableProperty.femalePopulation,
    kwg-ont:censusObservableProperty.householdUnits
  ))
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT COUNT(DISTINCT ?earthquake) ?earthquake
WHERE {
  ?earthquake a kwg-ont:Earthquake .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?attribute (COUNT(DISTINCT ?hazard) AS ?count)
WHERE {
  ?hazard a kwg-ont:NOAATornado ;
          sosa:observedProperty ?attribute .
}
GROUP BY ?attribute

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?hazardEvent ?observableProperty ?observation
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
               sosa:hasFeatureOfInterest ?place .

  # Storm-specific hazard events (storm tracks, tracklets, and smoke plumes)
  FILTER (?hazardEvent = kwg-ont:StormTrack 
          || ?hazardEvent = kwg-ont:StormTracklet
          || ?hazardEvent = kwg-ont:SmokePlumeSnapshot)

  ?observation a sosa:Observation ;
               sosa:hasFeatureOfInterest ?hazardEvent ;
               sosa:observedProperty ?observableProperty .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?hazardEvent ?property ?value
WHERE {
  # Flood-specific hazard events
  VALUES ?floodEvents {
    kwg-ont:NOAAFlood
    kwg-ont:NOAAFlashFlood
    kwg-ont:NOAACoastalFlood
    kwg-ont:NOAALakeshoreFlood
    kwg-ont:NOAAStormSurgeTide
  }
  ?hazardEvent a ?floodEvents ;
               sosa:hasSimpleResult ?value .

  # Associated observable property (e.g., magnitude, impact, etc.)
  OPTIONAL {
    ?observation sosa:observedProperty ?property ;
                 sosa:resultTime ?time ;      # optional timestamp of the observation
                 sosa:hasFeatureOfInterest ?hazardEvent .
  }
}
ORDER BY ?hazardEvent ?property

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?earthquake ?type ?prop ?value
WHERE {
  ?earthquake a kwg-ont:Earthquake ;
              kwg-ont:hasTemporalScope ?time .

  OPTIONAL { ?earthquake geo:hasGeometry ?geometry . }
  OPTIONAL { ?earthquake geo:hasDefaultGeometry ?defaultGeometry . }

  # Retrieve earthquake-specific observable properties and their values
  {
    SELECT ?earthquake ?prop ?value
    WHERE {
      ?obs a sosa:EarthquakeObservation ;
           sosa:hasFeatureOfInterest ?earthquake ;
           sosa:observedProperty ?prop ;
           sosa:hasSimpleResult ?value .
    }
  }

  # Determine the type (class) of each earthquake hazard
  SELECT ?earthquake (GROUP_CONCAT(DISTINCT STR(?type)) AS ?type)
  WHERE {
    ?earthquake a ?type .
  }
  GROUP BY ?earthquake
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?hazardEvent ?impactProperty ?impactValue
WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?hazardEvent ;
       sosa:observedProperty ?impactProperty ;
       sosa:hasSimpleResult ?impactValue .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?impactObservation WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:hasFeatureOfInterest ?hazardEvent .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?hazard ?hazardAttr ?damageImpact ?temporalData
WHERE {
  # Hurricane-specific hazard (NOAAHazardEvent with hurricane type)
  ?hazard a kwg-ont:NOAAHurricane ;
          sosa:observedProperty ?hazardAttr .

  # Damage impact details linked to the same hazard event, including temporal information if available
  ?impact a kwg-ont:ImpactObservation ;
          sosa:hasFeatureOfInterest ?hazard ;
          sosa:observedProperty ?damageImpact ;
          sosa:phenomenonTime ?temporalData .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?damageProperty ?damageCrop ?deathDirect ?deathIndirect ?injuryDirect ?injuryIndirect
WHERE {
  ?hazard a kwg-ont:NOAATornado ;
          kwg-ont:hasTemporalScope ?tempScope ;
          kwg-ont:spatialRelation ?place .

  FILTER(?tempScope >= "2023-01-01"^^xsd:dateTime && ?tempScope <= "2024-12-31"^^xsd:dateTime)

  ?impact a kwg-ont:ImpactObservation ;
          sosa:hasFeatureOfInterest ?hazard ;
          sosa:observedProperty ?prop ;
          sosa:hasSimpleResult ?value .

  VALUES ?prop {
    kwg-ont:impactObservableProperty.damageProperty
    kwg-ont:impactObservableProperty.damageCrop
    kwg-ont:impactObservableProperty.deathDirect
    kwg-ont:impactObservableProperty.deathIndirect
    kwg-ont:impactObservableProperty.injuryDirect
    kwg-ont:impactObservableProperty.injuryIndirect
  }

  BIND(COALESCE(?value, "") AS ?val)
  BIND(IF(STRSTARTS(str(?prop), "damageProperty"), ?val, NULL) AS ?damageProperty)
  BIND(IF(STRSTARTS(str(?prop), "damageCrop"),      ?val, NULL) AS ?damageCrop)
  BIND(IF(STRSTARTS(str(?prop), "deathDirect"),    ?val, NULL) AS ?deathDirect)
  BIND(IF(STRSTARTS(str(?prop), "deathIndirect"),  ?val, NULL) AS ?deathIndirect)
  BIND(IF(STRSTARTS(str(?prop), "injuryDirect"),   ?val, NULL) AS ?injuryDirect)
  BIND(IF(STRSTARTS(str(?prop), "injuryIndirect"), ?val, NULL) AS ?injuryIndirect)
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?damageDetail
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          a ?stormHazard .  # storm-specific hazard (e.g., kwg-ont:NOAATornado, kwg-ont:NOAAHurricane, etc.)

  ?hazard kwg-ont:hasTemporalScope ?temporalExtent .
  FILTER( ?temporalExtent >= $startTimeFilter && ?temporalExtent <= $endTimeFilter )

  ?hazard kwg-ont:spatialRelation ?place .   # relation to a geographical place
  FILTER(?place = <PLACE_URI>)               # replace <PLACE_URI> with the desired administrative region / S2Cell URI

  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:hasFeatureOfInterest ?hazard ;
                     sosa:observedProperty kwg-ont:impactObservableProperty ;
                     sosa:hasSimpleResult ?damageDetail .
}

