  FILTER NOT ( ?college = ?university )
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?state ?university
WHERE {
  # Count publications per university, grouped by the state in which its location resides
  {
    SELECT ?u (COUNT(DISTINCT ?pub) AS ?cnt)
    WHERE {
      ?u a coresr-ont:University ;
         coresr-ont:locatedAt ?loc .
      ?loc coresr-ont:atState ?state .
      ?author a coresr-ont:Author ;
              coresr-ont:advisedBy ?advisor .
      ?advisor a coresr-ont:Advisor ;
               coresr-ont:advises ?author .
      ?pub a coresr-ont:Publication ;
           coresr-ont:submittedBy ?author .
    }
    GROUP BY ?u
  } ORDER BY DESC(?cnt)
  # Return the top university (most publications) for each state
  {
    SELECT ?state ?university
    WHERE {
      { SELECT ?u ?s (COUNT(DISTINCT ?pub) AS ?cnt) 
        WHERE {
          ?u a coresr-ont:University ;
             coresr-ont:locatedAt ?loc .
          ?loc coresr-ont:atState ?s .
          ?author a coresr-ont:Author ;
                  coresr-ont:advisedBy ?advisor .
          ?advisor a coresr-ont:Advisor ;
                   coresr-ont:advises ?author .
          ?pub a coresr-ont:Publication ;
               coresr-ont:submittedBy ?author .
        }
        GROUP BY ?u ?s
      } 
    }
    ORDER BY DESC(?cnt)
    LIMIT 1
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?pubType (AVG(?diffDays) AS ?avgDiff)
FROM : 
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:dateOfSubmission ?subDate ;
       coresr-ont:dateOfPublication ?pubDate ;
       coresr-ont:hasPublicationType ?pt .

  BIND ((xsd:dateTime(?pubDate) - xsd:dateTime(?subDate)) / (xsd:dayTimeDuration('P1D')^^xsd:duration) AS ?diffDays)

  BIND (strafter(str(?pt), '#') AS ?pubType)   # extract the local name of the publication type
}
GROUP BY ?pubType
ORDER BY DESC(?avgDiff)
LIMIT 1

