GROUP BY ?hazardType
HAVING (?hazardType = kwglr:earthquake)

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?attr (COUNT(DISTINCT ?place) AS ?count)
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place ?attr ?value } .
  FILTER NOT EXISTS {
    ?hazard a kwgl-ont:HazardEvent ;
           kwgl-ont:hasHazardType ?type .
    BIND(kwglr:tornado AS ?tornadoType)
    FILTER(?type = ?tornadoType)
    OPTIONAL { ?place ?attr ?value } .
  }
}
GROUP BY ?attr

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?attribute ?value
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType kwglr:flood .
  ?hazard kwgl-ont:impactedBy ?place .

  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?value . BIND ("affectedAreaInAcres" AS ?attribute) }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?value . BIND ("damageToCropsInDollars" AS ?attribute) }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?value . BIND ("damageToInfrastructureInDollars" AS ?attribute) }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?value . BIND ("hasStartDate" AS ?attribute) }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?value . BIND ("hasEndDate" AS ?attribute) }
  OPTIONAL { ?hazard kwgl-ont:hasName ?value . BIND ("hasName" AS ?attribute) }
  OPTIONAL { ?hazard kwgl-ont:hasKWGEntity ?value . BIND ("hasKWGEntity" AS ?attribute) }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?predicate ?value
WHERE {
  ?place a kwgl-ont:Place .
  FILTER REGEX(STR(?predicate), "^(average|maximum|minimum)MonthlyTemperatureInCelsius|average(Cooling|Heating)DegreeDaysPerMonth")
  {
    SELECT ?place ?predicate (MAX(?prop) AS ?value)
    WHERE {
      VALUES ?predicate {
        kwgl-ont:averageMonthlyTemperatureInCelsius
        kwgl-ont:maximumMonthlyTemperatureInCelsius
        kwgl-ont:minimumMonthlyTemperatureInCelsius
        kwgl-ont:averageCoolingDegreeDaysPerMonth
        kwgl-ont:averageHeatingDegreeDaysPerMonth
      }
      ?place ?predicate ?prop .
    }
    GROUP BY ?place ?predicate
  }
}
ORDER BY ?place ?predicate

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazard ?name ?type
WHERE {
