       ?affectedAreaInAcres 
       ?damageToCropsInDollars 
       ?damageToInfrastructureInDollars 
       ?numberOfDeaths
WHERE {
  ?event a kwgl-ont:HazardEvent .
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?numberOfDeaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place (kwgl-ont:damageToInfrastructureInDollars AS ?damage)
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasImpacted ?place .
  OPTIONAL { ?place kwgl-ont:damageToInfrastructureInDollars ?damage }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazard ?attributeValue ?damageAttribute ?damageValue ?startDate ?endDate
WHERE {
  ?hazard a kwgl-ont:Hurricane ;
          kwgl-ont:hasHazardType kwglr:hurricane ;
          kwgl-ont:impactedBy ?place .

  # Hurricane‑specific attributes (numeric properties defined for HazardEvent)
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?attributeValue }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?attributeValue }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?attributeValue }

  # Damage impact details (damage properties defined for Place)
  OPTIONAL {
    BIND(kwgl-ont:dollarDamageOfHurricanesImpactingPlace AS ?damageAttribute)
    ?place ?damageAttribute ?damageValue
  }

  # Temporal data if available
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate   ?endDate   }

} ORDER BY ?hazard

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?place ?damageYear ?damageAmount
WHERE {
  ?hazard a kwgl-ont:Tornado ;
          kwgl-ont:hasHazardType kwglr:tornado ;
          kwgl-ont:hasStartDate ?startDate ;
          kwgl-ont:hasEndDate   ?endDate .

  FILTER(?startDate >= "2020-01-01"^^xsd:date && ?endDate <= "2022-12-31"^^xsd:date)

  ?hazard kwgl-ont:impactedBy/kwgl-ont:dollarDamageOfTornadoesImpactingPlace?2018   ?d2018 .
  ?hazard kwgl-ont:impactedBy/kwgl-ont:dollarDamageOfTornadoesImpactingPlace?2019   ?d2019 .
  ?hazard kwgl-ont:impactedBy/kwgl-ont:dollarDamageOfTornadoesImpactingPlace?2020   ?d2020 .
  ?hazard kwgl-ont:impactedBy/kwgl-ont:dollarDamageOfTornadoesImpactingPlace?2021   ?d2021 .
  ?hazard kwgl-ont:impactedBy/kwgl-ont:dollarDamageOfTornadoesImpactingPlace?2022   ?d2022 .

  BINDINGS (?damageYear ?damageAmount) {
    ("2018"^^xsd:gYear, ?d2018)
    ("2019"^^xsd:gYear, ?d2019)
    ("2020"^^xsd:gYear, ?d2020)
    ("2021"^^xsd:gYear, ?d2021)
    ("2022"^^xsd:gYear, ?d2022)
  }

  FILTER(BOUND(?damageAmount))

  ?place a kwgl-ont:Place ;
         kwgl-ont:dollarDamageOfTornadoesImpactingPlace?2018   ?d2018 ;
         kwgl-ont:dollarDamageOfTornadoesImpactingPlace?2019   ?d2019 ;
         kwgl-ont:dollarDamageOfTornadoesImpactingPlace?2020   ?d2020 ;
         kwgl-ont:dollarDamageOfTornadoesImpactingPlace?2021   ?d2021 ;
         kwgl-ont:dollarDamageOfTornadoesImpactingPlace?2022   ?d2022 .
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?damageProperty ?damageValue
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType ?stormHazard .

  FILTER(?stormHazard IN (
    kwglr:hurricane,
    kwglr:tropicalStorm,
    kwglr:tropicalDepression,
    kwglr:stormSurgeTide
  ))

  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageValue . BIND(kwgl-ont:damageToInfrastructureInDollars AS ?damageProperty) }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageValue . BIND(kwgl-ont:damageToCropsInDollars AS ?damageProperty) }

  FILTER(?hazard kwgl-ont:hasStartDate >= "2020-01-01"^^xsd:date)
  FILTER(?hazard kwgl-ont:hasEndDate   <= "2022-12-31"^^xsd:date)

  ?place a kwgl-ont:Place ;
         kwgl-ont:impactedBy ?hazard .
}

