WHERE {
  ?publication a coress-ont:Publication .
  ?author1 a coress-ont:Author ;
           coress-ont:submits ?publication .
  ?dept1 a coress-ont:Department ;
         coress-ont:departmentOf ?college1 .
  ?author1 coress-ont:worksInDepartment ?dept1 .

  ?author2 a coress-ont:Author ;
           coress-ont:submits ?publication .
  FILTER (?author2 != ?author1)
  ?dept2 a coress-ont:Department ;
         coress-ont:departmentOf ?college2 .
  ?author2 coress-ont:worksInDepartment ?dept2 .

  FILTER (?dept1 != ?dept2)
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publicationType (AVG(?duration) AS ?avgDuration)
FROM <http://example.org/kg-core-scholar-shallow>
WHERE {
  ?pub a coress-ont:Publication ;
       coress-ont:dateOfSubmission ?submissionDate ;
       coress-ont:dateOfPublication ?publicationDate ;
       coress-ont:hasPublicationType ?publicationType .

  BIND (daysAfter(?publicationDate, ?submissionDate) AS ?duration)
}
GROUP BY ?publicationType
ORDER BY DESC(?avgDuration)
LIMIT 1

# Helper function to calculate difference in days between two xsd:date values
BIND (FLOOR((xsd:dateTime(?publicationDate) - xsd:dateTime(?submissionDate)) / (24*3600)) AS daysAfter(?publicationDate, ?submissionDate))

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department (COUNT(*) AS ?missingCount)
WHERE {
  ?agent a coress-ont:Agent ;
        coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName }
}
GROUP BY ?department
ORDER BY DESC(?missingCount)
LIMIT 1

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?name .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place (GROUP_CONCAT(DISTINCT ?attribute; SEPARATOR='|') AS ?attributes)
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name }
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyPercent }
  OPTIONAL { ?place kwgl-ont:percentObese ?obesityPercent }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabetesPercent }
  OPTIONAL { ?place kwgl-ont:numberOfEarthquakesImpactingPlace ?eqCount }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfEarthquakesImpactingPlace ?eqDollarDamage } 
  OPTIONAL { ?place kwgl-ont:numberOfFiresImpactingPlace ?fireCount }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?fireDollarDamage }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?hurricaneCount }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?hurricaneDollarDamage }
  OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace ?tornadoCount }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?tornadoDollarDamage }
  OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsius ?avgTempC }
  OPTIONAL { ?place kwgl-ont:averageCoolingDegreeDaysPerMonth ?coolingDD }
  OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonth ?heatingDD }
  OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsius ?maxTempC }
  OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsius ?minTempC }

  BIND(CONCAT("Name=", COALESCE(STR(?name), "null")) AS ?attr1)
  BIND(CONCAT("Population=", COALESCE(STR(?population), "null")) AS ?attr2)
  BIND(CONCAT("Poverty Percent=", COALESCE(STR(?povertyPercent), "null")) AS ?attr3)
  BIND(CONCAT("Obesity Percent=", COALESCE(STR(?obesityPercent), "null")) AS ?attr4)
  BIND(CONCAT("Diabetes Percent=", COALESCE(STR(?diabetesPercent), "null")) AS ?attr5)
  BIND(CONCAT("Earthquake Count=", COALESCE(STR(?eqCount), "null")) AS ?attr6)
  BIND(CONCAT("Earthquake Damage=$", COALESCE(STR(?eqDollarDamage), "null")) AS ?attr7)
  BIND(CONCAT("Fire Count=", COALESCE(STR(?fireCount), "null")) AS ?attr8)
  BIND(CONCAT("Fire Damage=$", COALESCE(STR(?fireDollarDamage), "null")) AS ?attr9)
  BIND(CONCAT("Hurricane Count=", COALESCE(STR(?hurricaneCount), "null")) AS ?attr10)
  BIND(CONCAT("Hurricane Damage=$", COALESCE(STR(?hurricaneDollarDamage), "null")) AS ?attr11)
  BIND(CONCAT("Tornado Count=", COALESCE(STR(?tornadoCount), "null")) AS ?attr12)
  BIND(CONCAT("Tornado Damage=$", COALESCE(STR(?tornadoDollarDamage), "null")) AS ?attr13)
  BIND(CONCAT("Avg Temp C=", COALESCE(STR(?avgTempC), "null")) AS ?attr14)
  BIND(CONCAT("Cooling DD=", COALESCE(STR(?coolingDD), "null")) AS ?attr15)
  BIND(CONCAT("Heating DD=", COALESCE(STR(?heatingDD), "null")) AS ?attr16)
  BIND(CONCAT("Max Temp C=", COALESCE(STR(?maxTempC), "null")) AS ?attr17)
  BIND(CONCAT("Min Temp C=", COALESCE(STR(?minTempC), "null")) AS ?attr18)

  BIND(IF(BOUND(?name), ?attr1, "") AS ?a1)
  BIND(IF(BOUND(?population), ?attr2, "") AS ?a2)
  BIND(IF(BOUND(?povertyPercent), ?attr3, "") AS ?a3)
  BIND(IF(BOUND(?obesityPercent), ?attr4, "") AS ?a4)
  BIND(IF(BOUND(?diabetesPercent), ?attr5, "") AS ?a5)
  BIND(IF(BOUND(?eqCount), ?attr6, "") AS ?a6)
  BIND(IF(BOUND(?eqDollarDamage), ?attr7, "") AS ?a7)
  BIND(IF(BOUND(?fireCount), ?attr8, "") AS ?a8)
  BIND(IF(BOUND(?fireDollarDamage), ?attr9, "") AS ?a9)
  BIND(IF(BOUND(?hurricaneCount), ?attr10, "") AS ?a10)
  BIND(IF(BOUND(?hurricaneDollarDamage), ?attr11, "") AS ?a11)
  BIND(IF(BOUND(?tornadoCount), ?attr12, "") AS ?a12)
  BIND(IF(BOUND(?tornadoDollarDamage), ?attr13, "") AS ?a13)
  BIND(IF(BOUND(?avgTempC), ?attr14, "") AS ?a14)
  BIND(IF(BOUND(?coolingDD), ?attr15, "") AS ?a15)
  BIND(IF(BOUND(?heatingDD), ?attr16, "") AS ?a16)
  BIND(IF(BOUND(?maxTempC), ?attr17, "") AS ?a17)
  BIND(IF(BOUND(?minTempC), ?attr18, "") AS ?a18)

  BIND(CONCAT(
    COALESCE(?a1, ""), 
    IF(STRLEN(?a1) > 0 && (BOUND(?a2)||BOUND(?a3)||...||BOUND(?a18)), "|", ""),
    COALESCE(?a2, ""), 
    IF(STRLEN(?a2) > 0 && (BOUND(?a3)||...||BOUND(?a18)), "|", ""),
    ...,
    COALESCE(?a18, "")
  ) AS ?attributes)
}
GROUP BY ?place

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?population ?households 
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population } .
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hazardType (COUNT(DISTINCT ?event) AS ?count)
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType ?hazardType .
  FILTER(?hazardType = kwglr:earthquake)
}
GROUP BY ?hazardType

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardAttribute (COUNT(DISTINCT ?place) AS ?attributeCount)
WHERE {
  ?hEvent a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType kwglr:tornado .

  BIND(kwgl-ont:affectedAreaInAcres AS ?hazardAttribute)

  OPTIONAL { 
    ?hEvent kwgl-ont:impactedBy/kwgl-ont:hasImpacted ?place .
    FILTER NOT EXISTS {
      [] a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType kwglr:tornado ;
         kwgl-ont:impactedBy/kwgl-ont:hasImpacted ?place .
    }
  }
}
GROUP BY ?hazardAttribute

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazardEvent ?placeName 
                ?startDate ?endDate 
                ?affectedAreaAcres ?cropDamageDollars ?infrastructureDamageDollars ?deaths
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType [ a kwglr:stormSurgeTide | kwglr:hurricane | kwglr:tornado | kwglr:thunderstormWind | kwglr:strongWind | kwglr:highWind ] ;
               kwgl-ont:hasImpacted ?place ;
               kwgl-ont:hasStartDate ?startDate ;
               kwgl-ont:hasEndDate ?endDate ;
               kwgl-ont:affectedAreaInAcres ?affectedAreaAcres ;
               kwgl-ont:damageToCropsInDollars ?cropDamageDollars ;
               kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamageDollars ;
               kwgl-ont:numberOfDeaths ?deaths .
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?placeName .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hazardEvent ?eventName ?affectedPlace ?placeName 
       ?areaAcres ?damageCrops ?damageInfrastructure ?startDate ?endDate ?deathCount
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType kwglr:flood ;   # flood‑specific hazard type
               kwgl-ont:hasName        ?eventName    .

  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres      ?areaAcres      }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars   ?damageCrops    }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate            ?startDate      }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate              ?endDate        }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths          ?deathCount     }

  # Link to the geographical place impacted
  ?hazardEvent kwgl-ont:hasImpacted ?affectedPlace .
  ?affectedPlace a kwgl-ont:Place ;
                 kwgl-ont:hasName ?placeName .
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?place ?property ?value
WHERE {
  ?place a kwgl-ont:Place .
  { ?place kwgl-ont:averageCoolingDegreeDaysPerMonth ?value }
  UNION { ?place kwgl-ont:averageHeatingDegreeDaysPerMonth ?value }
  UNION { ?place kwgl-ont:averageMonthlyTemperatureInCelsius ?value }
  UNION { ?place kwgl-ont:maximumMonthlyTemperatureInCelsius ?value }
  UNION { ?place kwgl-ont:minimumMonthlyTemperatureInCelsius ?value }
  UNION { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?value }
  UNION { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?value }
  UNION { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?value }
  UNION { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?value }
  UNION { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?value }
  UNION { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?value }
  UNION { ?place kwgl-ont:numberOfEarthquakesImpactingPlace ?value }
  UNION { ?place kwgl-ont:numberOfFiresImpactingPlace ?value }
  UNION { ?place kwgl-ont:numberOfFloodsImpactingPlace ?value }
  UNION { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?value }
  UNION { ?place kwgl-ont:numberOfLandslidesImpactingPlace ?value }
  UNION { ?place kwgl-ont:numberOfStormSurgesImpactingPlace ?value }
  UNION { ?place kwgl-ont:numberOfTornadoesImpactingPlace ?value }
  UNION { ?place kwgl-ont:percentBelowPovertyLine ?value }
  UNION { ?place kwgl-ont:percentDiabetic ?value }
  UNION { ?place kwgl-ont:percentObese ?value }
  UNION { ?place kwgl-ont:numberOfEarthquakesImpactingPlace2018 ?value }
  UNION { ?place kwgl-ont:numberOfEarthquakesImpactingPlace2019 ?value }
  UNION { ?place kwgl-ont:numberOfEarthquakesImpactingPlace2020 ?value }
  UNION { ?place kwgl-ont:numberOfEarthquakesImpactingPlace2021 ?value }
  UNION { ?place kwgl-ont:numberOfEarthquakesImpactingPlace2022 ?value }
  UNION { ?place kwgl-ont:numberOfFiresImpactingPlace2018 ?value }
  UNION { ?place kwgl-ont:numberOfFiresImpactingPlace2019 ?value }
  UNION { ?place kwgl-ont:numberOfFiresImpactingPlace2020 ?value }
  UNION { ?place kwgl-ont:numberOfFiresImpactingPlace2021 ?value }
  UNION { ?place kwgl-ont:numberOfFiresImpactingPlace2022 ?value }
  UNION { ?place kwgl-ont:numberOfFloodsImpactingPlace2018 ?value }
  UNION { ?place kwgl-ont:numberOfFloodsImpactingPlace2019 ?value }
  UNION { ?place kwgl-ont:numberOfFloodsImpactingPlace2020 ?value }
  UNION { ?place kwgl-ont:numberOfFloodsImpactingPlace2021 ?value }
  UNION { ?place kwgl-ont:numberOfFloodsImpactingPlace2022 ?value }
  UNION { ?place kwgl-ont:numberOfHurricanesImpactingPlace2018 ?value }
  UNION { ?place kwgl-ont:numberOfHurricanesImpactingPlace2019 ?value }
  UNION { ?place kwgl-ont:numberOfHurricanesImpactingPlace2020 ?value }
  UNION { ?place kwgl-ont:numberOfHurricanesImpactingPlace2021 ?value }
  UNION { ?place kwgl-ont:numberOfHurricanesImpactingPlace2022 ?value }
  UNION { ?place kwgl-ont:numberOfLandslidesImpactingPlace2018 ?value }
  UNION { ?place kwgl-ont:numberOfLandslidesImpactingPlace2019 ?value }
  UNION { ?place kwgl-ont:numberOfLandslidesImpactingPlace2020 ?value }
  UNION { ?place kwgl-ont:numberOfLandslidesImpactingPlace2021 ?value }
  UNION { ?place kwgl-ont:numberOfLandslidesImpactingPlace2022 ?value }
  UNION { ?place kwgl-ont:numberOfStormSurgesImpactingPlace2018 ?value }
  UNION { ?place kwgl-ont:numberOfStormSurgesImpactingPlace2019 ?value }
  UNION { ?place kwgl-ont:numberOfStormSurgesImpactingPlace2020 ?value }
  UNION { ?place kwgl-ont:numberOfStormSurgesImpactingPlace2021 ?value }
  UNION { ?place kwgl-ont:numberOfStormSurgesImpactingPlace2022 ?value }
  UNION { ?place kwgl-ont:numberOfTornadoesImpactingPlace2018 ?value }
  UNION { ?place kwgl-ont:numberOfTornadoesImpactingPlace2019 ?value }
  UNION { ?place kwgl-ont:numberOfTornadoesImpactingPlace2020 ?value }
  UNION { ?place kwgl-ont:numberOfTornadoesImpactingPlace2021 ?value }
  UNION { ?place kwgl-ont:numberOfTornadoesImpactingPlace2022 ?value }
  BIND (xsd:string(STR(?property)) AS ?property)
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?event ?name ?type ?startDate ?endDate 
       ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars
       ?numberOfDeaths
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType kwglr:earthquake ;
         kwgl-ont:hasName        ?name          ;
         kwgl-ont:hasStartDate   ?startDate     ;
         kwgl-ont:hasEndDate     ?endDate       ;
         kwgl-ont:affectedAreaInAcres    ?affectedAreaInAcres ;
         kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars ;
         kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars ;
         kwgl-ont:numberOfDeaths          ?numberOfDeaths .

  BIND(kwglr:earthquake AS ?type)
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazardEvent 
       ?damageToCropsInDollars 
       ?damageToInfrastructureInDollars 
       ?numberOfDeaths 
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?damageCrops ?damageInfrastructure 
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:damageToCropsInDollars ?damageCrops ;
               kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure .
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent
       ?name
       ?affectedAreaInAcres
       ?damageToCropsInDollars
       ?damageToInfrastructureInDollars
       ?startDate
       ?endDate
       ?place
       ?dollarDamageHurricanePlace
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType kwglr:hurricane ;
               kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate }

  # Retrieve damage impact on the related place (any year)
  OPTIONAL {
    VALUES ?yearProp {
      kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018
      kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019
      kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020
      kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021
      kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022
    }
    ?place ?yearProp ?dollarDamageHurricanePlace .
  }

  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name }
  OPTIONAL { ?place kwgl-ont:hasName ?placeName }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hazardEvent ?placeName 
       ?cropDamage ?infrastructureDamage 
       ?start ?end
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType kwglr:tornado ;
               kwgl-ont:damageToCropsInDollars    ?cropDamage ;
               kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage ;
               kwgl-ont:hasStartDate  ?start ;
               kwgl-ont:hasEndDate    ?end ;
               kwgl-ont:hasImpacted   ?place .

  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?placeName .
}
ORDER BY ?hazardEvent

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazardEvent ?damageCrops ?damageInfrastructure
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType ?hazardType ;
               kwgl-ont:damageToCropsInDollars ?damageCrops ;
               kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure .
  FILTER (?hazardType IN (kwglr:hurricane, kwglr:tornado,
                          kwglr:thunderstormWind, kwglr:strongWind,
                          kwglr:highWind, kwglr:blizzard, kwglr:winterStorm,
                          kwglr:tropicalStorm, kwglr:tropicalDepression))
  ?hazardEvent kwgl-ont:hasStartDate ?startDate ;
               kwgl-ont:hasEndDate   ?endDate .
  FILTER (?startDate >= "2023-01-01"^^xsd:date && ?endDate <= "2024-12-31"^^xsd:date)
  ?hazardEvent kwgl-ont:hasImpacted ?place .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?doiValue
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:hasIdentifier ?doi .
  ?doi a coresr-ont:DOI ;
       coresr-ont:doiAsString ?doiValue .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?university ?cityName
WHERE {
  ?university a coresr-ont:University ;
              coresr-ont:locatedAt ?location .
  ?location a coresr-ont:Location ;
            coresr-ont:atState ?state .
  ?state a coresr-ont:State ;
         coresr-ont:inCity ?city .
  ?city a coresr-ont:City ;
        coresr-ont:nameAsString ?cityName .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author ?advisor
WHERE {
  ?author coresr-ont:advisedBy ?advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?pubType
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:hasPublicationType ?pubType .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?agent ?department
WHERE {
  ?agent coresr-ont:associatedWith ?department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?fieldOfStudy
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?city ?college
WHERE {
  ?university a coresr-ont:University ;
              coresr-ont:locatedAt ?location .

  ?location a coresr-ont:Location ;
            coresr-ont:atState ?state .

  ?state a coresr-ont:State ;
         coresr-ont:inCity ?city .

  ?college a coresr-ont:College ;
           coresr-ont:partOf ?university .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:submittedBy ?author .
  ?author coresr-ont:associatedWith ?dept1 .
  FILTER NOT EXISTS {
    ?author coresr-ont:associatedWith ?dept2 .
    FILTER (?dept1 != ?dept2)
  }
  # Ensure at least one other author from a different department exists
  ?publication coresr-ont:submittedBy ?otherAuthor .
  ?otherAuthor coresr-ont:associatedWith ?otherDept .
  FILTER (?otherAuthor != ?author && ?otherDept != ?dept1)
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?pubType (AVG(?diffDays) AS ?avgDiff)
WHERE {
  ?pub coresr-ont:dateOfSubmission ?subDate ;
       coresr-ont:dateOfPublication ?pubDate ;
       coresr-ont:hasPublicationType ?pubType .
  FILTER (BOUND(?subDate) && BOUND(?pubDate))
  BIND ((xsd:dateTime(?pubDate) - xsd:dateTime(?subDate)) / ^xsrduration:"P1D" AS ?diffDays)
}
GROUP BY ?pubType
ORDER BY DESC(?avgDiff)
LIMIT 1

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?author ?fieldOfStudy
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .   # ensures the author has an advisor
  ?pub a coresr-ont:Publication ;
       coresr-ont:submittedBy ?author ;
       coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department (COUNT(*) AS ?missingFamilyNameCount)
WHERE {
  ?agent coresr-ont:associatedWith ?department .
  OPTIONAL { ?agent coresr-ont:hasContactInformation [ a coresr-ont:FamilyName ] } 
  FILTER (!BOUND(?familyName))
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?name WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place
       ?property
       ?value
WHERE {
  ?place a kwgl-ont:Place .

  { 
    # Direct health‑related attributes of Place
    VALUES ?property {
      kwgl-ont:percentBelowPovertyLine
      kwgl-ont:percentDiabetic
      kwgl-ont:percentObese
    }
    OPTIONAL { ?place ?property ?value . }
  }

  UNION

  { 
    # Count and damage attributes related to specific hazards
    VALUES ?hazard {
      kwglr:fire          # fires (wildfires, etc.)
      kwglr:flood
      kwglr:hurricane
      kwglr:earthquake
      kwglr:drought
      kwglr:heat
      kwglr:coldWindChill
      kwglr:excessiveHeat
      kwglr:extremeColdWindChill
    }

    # Count of hazard events impacting the place
    OPTIONAL {
      BIND (IRI(CONCAT(STR(?hazard), "String")) AS ?countProp)
      FILTER (EXISTS { ?place ?countProp ?value . })
      BIND (?countProp AS ?property)
      ?place ?countProp ?value .
    }

    # Dollar damage of the same hazard impacting the place
    OPTIONAL {
      BIND (IRI(CONCAT(STR(kwgl-ont:dollarDamageOf), 
                       REPLACE(STR(?hazard), "kwglr:", ""),
                       "ImpactingPlace")) AS ?damageProp)
      FILTER (EXISTS { ?place ?damageProp ?value . })
      BIND (?damageProp AS ?property)
      ?place ?damageProp ?value .
    }
  }

}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place
       ( ?population AS ?population )
       ( ?households AS ?numberOfHouseHolds )
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households . }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?hazardType (COUNT(DISTINCT ?event) AS ?count)
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType ?hazardType .
  FILTER(?hazardType = kwglr:earthquake)
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?attribute (COUNT(DISTINCT ?place) AS ?placeCount)
WHERE {
  ?hazard a kwgl-ont:Tornado ;
          kwgl-ont:hasImpacted ?place .

  ?place a kwgl-ont:Place ;
         ?attribute ?value .

  FILTER NOT EXISTS { ?property rdfs:subPropertyOf* ?attribute }
}
GROUP BY ?attribute

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?attribute (STR(?attribute) AS ?attributeStr)
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:HazardEvent ; FILTER(STRENDS(STR(?attribute), "ImpactingPlace")) }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?label . }

  FILTER(
    CONTAINS(LCASE(STR(?attribute)), "storm") ||
    (EXISTS {?attribute rdfs:subPropertyOf* ?parent} && CONTAINS(LCASE(STR(?parent)), "storm"))
  )
}
ORDER BY ?attribute

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?attribute (STR(?range) AS ?rangeLabel)
WHERE {
  ?attribute rdf:type owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place ;
             rdfs:range ?range .

  FILTER(regex(STR(?attribute), "flood", "i"))
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?property
WHERE {
  ?property a owl:DatatypeProperty ;
            rdfs:domain kwgl-ont:Place .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hazardEvent ?typeLabel ?name ?startDate ?endDate 
       ?affectedAreaAcres ?damageCropsDollars ?damageInfrastructureDollars ?numberOfDeaths
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .

  ?hazardEvent kwgl-ont:hasHazardType ?hazardType .
  OPTIONAL { ?hazardType rdfs:label ?typeLabel }

  OPTIONAL { ?hazardEvent kwgl-ont:hasName          ?name                     } 
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate     ?startDate                } 
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate       ?endDate                  } 
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres   ?affectedAreaAcres    } 
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars     ?damageCropsDollars      } 
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructureDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths   ?numberOfDeaths          }

  FILTER(?hazardType = kwglr:earthquake)
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?event
  ?type
  ?name
  ?startDate
  ?endDate
  ?affectedAreaInAcres
  ?damageToCropsInDollars
  ?damageToInfrastructureInDollars
  ?numberOfDeaths
WHERE {
  ?event a kwgl-ont:HazardEvent .

  OPTIONAL { ?event kwgl-ont:hasHazardType ?type . }
  OPTIONAL { ?event kwgl-ont:hasName ?name . }
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?numberOfDeaths . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?damageCrops ?damageInfrastructure
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:damageToCropsInDollars ?damageCrops ;
         kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure .
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
  ?hazardEvent      # hurricane hazard event (instance of HazardEvent with hasHazardType = kwglr:hurricane)
  ?startDate        # temporal start date of the hurricane event, if available
  ?endDate          # temporal end date of the hurricane event, if available
  ?place            # geographical place impacted by the hurricane
  ?damageDollars    # damage impact details (dollarDamageOfHurricanesImpactingPlace* properties)
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType kwglr:hurricane .   # filter for hurricane-specific events

  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate   ?endDate . }

  ?hazardEvent kwgl-ont:hasImpacted ?place .               # link to the impacted geographical place

  # Retrieve all hurricane‑damage properties defined for the place
  {
    SELECT ?place (SAMPLE(?damageProp) AS ?damageProp) (SAMPLE(?value) AS ?value)
    WHERE {
      ?place a kwgl-ont:Place .
      BIND(kwgl-ont:dollarDamageOfHurricanesImpactingPlace AS ?baseProp)
      # Include the generic damage property and all year‑specific subproperties
      { ?place ?damageProp ?value }
      UNION
      { ?damageProp rdfs:subPropertyOf* ?baseProp ; ?place ?value } .
    }
  }
  BIND(?damageProp AS ?damageDollars)
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazard ?type ?startDate ?endDate ?affectedAreaInAcres 
       ?damageToInfrastructureInDollars ?damageToCropsInDollars 
       ?numberOfDeaths 
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate   ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres      ?affectedAreaInAcres . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars          ?damageToCropsInDollars . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths                 ?numberOfDeaths . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?population ?households
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?hazard (COUNT(*) AS ?count)
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType ?hazard .
}
GROUP BY ?hazard

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?hazardAttr (COUNT(DISTINCT ?place) AS ?count)
WHERE {
  ?place a kwgl-ont:Place .
  FILTER EXISTS {
    ?event a kwgl-ont:Tornado ;
           kwgl-ont:hasImpacted ?place .
  }
  BIND(?place AS ?hazardAttr)
}
GROUP BY ?hazardAttr

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?attributeName ?value
WHERE {
  ?place a kwgl-ont:Place .
  {
    SELECT ?place ?place ?attributeName ?value
    WHERE {
      { ?place kwgl-ont:averageCoolingDegreeDaysPerMonth ?value } 
      UNION { ?place kwgl-ont:averageHeatingDegreeDaysPerMonth ?value }
      UNION { ?place kwgl-ont:averageMonthlyTemperatureInCelsius ?value }
      UNION { ?place kwgl-ont:maximumMonthlyTemperatureInCelsius ?value }
      UNION { ?place kwgl-ont:minimumMonthlyTemperatureInCelsius ?value }

      UNION { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?value }
      UNION { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?value }
      UNION { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?value }
      UNION { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?value }
      UNION { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?value }

