      UNION { ?place kwgl-ont:averageMonthlyTemperatureInCelsiusDec2021 ?value }
      UNION { ?place kwgl-ont:averageMonthlyTemperatureInCelsiusFeb2021 ?value }
      UNION { ?place kwgl-ont:averageMonthlyTemperatureInCelsiusJan2021 ?value }
      UNION { ?place kwgl-ont:averageMonthlyTemperatureInCelsiusJul2021 ?value }
