      UNION { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?value }
      UNION { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?value }
      UNION { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 ?value }
      UNION { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 ?value }
      UNION { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 ?value }

      UNION { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace2018 ?value }
      UNION { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace2019 ?value }
      UNION { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace2020 ?value }
      UNION { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace2021 ?value }
      UNION { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace2022 ?value }

      UNION { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2018 ?value }
      UNION { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2019 ?value }
      UNION { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2020 ?value }
      UNION { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2021 ?value }
      UNION { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2022 ?value }

      UNION { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2018 ?value }
      UNION { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2019 ?value }
      UNION { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2020 ?value }
      UNION { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2021 ?value }
      UNION { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2022 ?value }

      # Population / demographic attributes
      UNION { ?place kwgl-ont:hasPopulation ?value }
      UNION { ?place kwgl-ont:hasNumberOfHouseHolds ?value }
      UNION { ?place kwgl-ont:percentBelowPovertyLine ?value }
      UNION { ?place kwgl-ont:percentDiabetic ?value }
      UNION { ?place kwgl-ont:percentObese ?value }
    }
  }
  BIND (strafter(str(?predicate), "kwgl-ont:") AS ?attributeName)
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?type ?name ?startDate ?endDate 
       ?affectedAreaInAcres ?numberOfDeaths 
       ?damageToInfrastructureInDollars ?damageToCropsInDollars
WHERE {
  ?hazardEvent a kwgl-ont:Earthquake .
  ?hazardEvent kwgl-ont:hasHazardType ?type .

  OPTIONAL { ?hazardEvent kwgl-ont:hasName          ?name                     } 
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate     ?startDate                } 
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate       ?endDate                  } 
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres   ?affectedAreaInAcres    } 
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths   ?numberOfDeaths           } 
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars        ?damageToCropsInDollars      }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?event ?damageType ?value
WHERE {
  ?event a kwgl-ont:HazardEvent .
  VALUES ?damageType {
    kwgl-ont:damageToCropsInDollars
    kwgl-ont:damageToInfrastructureInDollars
  }
  OPTIONAL { ?event ?damageType ?value . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?damageDetail
WHERE {
  ?place kwgl-ont:impactedBy ?hazardEvent .
  ?place (kwgl-ont:damageToCropsInDollars|kwgl-ont:damageToInfrastructureInDollars) ?damageDetail .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?attrName ?attrValue ?impactDetailName ?impactDetailValue ?startDate ?endDate
WHERE {
  ?hazard a kwgl-ont:Hurricane ;
          kwgl-ont:hasImpacted ?place .

  # Hurricane-specific hazard attributes (e.g., number of hurricanes impacting the place)
  OPTIONAL { 
    BIND ("numberOfHurricanesImpactingPlace" AS ?attrName) .
    ?hazard kwgl-ont:numberOfHurricanesImpactingPlace ?attrValue . 
  }
  OPTIONAL {
    BIND ("numberOfHurricanesImpactingPlace2020" AS ?attrName) .
    ?hazard kwgl-ont:numberOfHurricanesImpactingPlace2020 ?attrValue .
  }
  OPTIONAL {
    BIND ("numberOfHurricanesImpactingPlace2018" AS ?attrName) .
    ?hazard kwgl-ont:numberOfHurricanesImpactingPlace2018 ?attrValue .
  }
  OPTIONAL {
    BIND ("numberOfHurricanesImpactingPlace2019" AS ?attrName) .
    ?hazard kwgl-ont:numberOfHurricanesImpactingPlace2019 ?attrValue .
  }
  OPTIONAL {
    BIND ("numberOfHurricanesImpactingPlace2021" AS ?attrName) .
    ?hazard kwgl-ont:numberOfHurricanesImpactingPlace2021 ?attrValue .
  }
  OPTIONAL {
    BIND ("numberOfHurricanesImpactingPlace2022" AS ?attrName) .
    ?hazard kwgl-ont:numberOfHurricanesImpactingPlace2022 ?attrValue .
  }

  # Damage impact details for the place affected by the hurricane
  OPTIONAL {
    BIND ("damageToInfrastructureInDollars" AS ?impactDetailName) .
    ?place kwgl-ont:damageToInfrastructureInDollars ?impactDetailValue .
  }
  OPTIONAL {
    BIND ("damageToCropsInDollars" AS ?impactDetailName) .
    ?place kwgl-ont:damageToCropsInDollars ?impactDetailValue .
  }

  # Temporal data of the hurricane event (if available)
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate   ?endDate   . }
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazardEvent ?damageDetails
WHERE {
  ?hazardEvent a kwgl-ont:Tornado ;
               kwgl-ont:hasHazardType kwgl-ont:tornado .
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamage . }
  BIND(COALESCE(?infDamage, 0) + COALESCE(?cropDamage, 0) AS ?damageDetails)
  FILTER ( EXISTS {
    ?hazardEvent kwgl-ont:hasStartDate ?startDate ;
                 kwgl-ont:hasEndDate   ?endDate .
    FILTER (?startDate <= "2022-12-31"^^xsd:date && ?endDate >= "2022-01-01"^^xsd:date)
  })
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?event ?damageToInfrastructure ?damageToCrops 
       ?placeName ?startDate ?endDate
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType ?hazardType ;
         kwgl-ont:impactedBy ?place .

  FILTER(?hazardType IN (kwglr:hurricane,
                         kwglr:tropicalStorm,
                         kwglr:tropicalDepression,
                         kwglr:stormSurgeTide))

  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCrops }
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?placeName .

  OPTIONAL {
    ?event kwgl-ont:hasStartDate ?startDate ;
           kwgl-ont:hasEndDate   ?endDate .

    FILTER(?startDate >= "2020-01-01"^^xsd:date)
    FILTER(?endDate   <= "2022-12-31"^^xsd:date)
  }
}

