PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?state ?universityName
WHERE {
  SELECT ?state (MAX(?pubCount) AS ?maxPubCount)
  {
    SELECT ?state ?university ?pubCount
    WHERE {
      ?author a coress-ont:Author ;
             coress-ont:submits ?publication .
      ?publication a coress-ont:Publication .

      ?agent a coress-ont:Agent ;
             coress-ont:worksInDepartment ?department ;
             coress-ont:performsRole ?author .

      ?department a coress-ont:Department ;
                  coress-ont:departmentOf ?college .
      ?college a coress-ont:College ;
               coress-ont:collegeOf ?university .

      ?university a coress-ont:University ;
                  coress-ont:atState ?state ;
                  coress-ont:hasTitle ?universityName .

      {
        SELECT (COUNT(DISTINCT ?publication) AS ?pubCount)
        WHERE { ?author coress-ont:submits ?publication }
      }
    }
    GROUP BY ?state ?university
  }
  GROUP BY ?state
}
JOIN {
  SELECT ?state ?universityName ?pubCount
  WHERE {
    ?author a coress-ont:Author ;
           coress-ont:submits ?publication .
    ?publication a coress-ont:Publication .

    ?agent a coress-ont:Agent ;
           coress-ont:worksInDepartment ?department ;
           coress-ont:performsRole ?author .

    ?department a coress-ont:Department ;
                coress-ont:departmentOf ?college .
    ?college a coress-ont:College ;
             coress-ont:collegeOf ?university .

    ?university a coress-ont:University ;
                coress-ont:atState ?state ;
                coress-ont:hasTitle ?universityName .

    {
      SELECT (COUNT(DISTINCT ?publication) AS ?pubCount)
      WHERE { ?author coress-ont:submits ?publication }
    }

    FILTER NOT EXISTS {
      ?otherUniv a coress-ont:University ;
                 coress-ont:atState ?state ;
                 coress-ont:hasTitle ?otherName .
      BIND(?otherName AS ?universityNameAlt)
      FILTER(?universityNameAlt != ?universityName)
      ?otherAuthor a coress-ont:Author ;
                   coress-ont:submits ?publication2 .
      ?publication2 a coress-ont:Publication .

      ?otherAgent a coress-ont:Agent ;
                  coress-ont:worksInDepartment ?deptOther ;
                  coress-ont:performsRole ?otherAuthor .
      ?deptOther a coress-ont:Department ;
                 coress-ont:departmentOf ?collegeOther .
      ?collegeOther a coress-ont:College ;
                    coress-ont:collegeOf ?otherUniv .

      {
        SELECT (COUNT(DISTINCT ?publication2) AS ?pubCountAlt)
        WHERE { ?otherAuthor coress-ont:submits ?publication2 }
      }

      FILTER(?pubCountAlt > ?pubCount)
    }
  }
}
GROUP BY ?state ?universityName

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?pubType (AVG(?diffDays) AS ?avgDiff)
FROM <http://example.org/core_scholar_shallow/>
WHERE {
  ?pub a coress-ont:Publication ;
       coress-ont:dateOfSubmission ?subDate ;
       coress-ont:dateOfPublication ?pubDate ;
       coress-ont:hasPublicationType ?pubType .
  FILTER (BOUND(?subDate) && BOUND(?pubDate))
  BIND (xsd:integer((xs:dateTime(?pubDate) - xs:dateTime(?subDate)) / 86400) AS ?diffDays)
}
GROUP BY ?pubType
ORDER BY DESC(?avgDiff)
LIMIT 1

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?author
WHERE {
  ?author a coress-ont:Author ;
          coress-ont:advisedBy ?advisor .   # ensures the author has an advisor
  ?pub a coress-ont:Publication ;
       coress-ont:submittedBy ?author ;
       coress-ont:associatedFieldOfStudy ?field .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department
WITH {
  SELECT ?dept (COUNT(*) AS ?missingCount)
  WHERE {
    ?agent a coress-ont:Agent ;
           coress-ont:worksInDepartment ?dept .
    FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName }
  }
  GROUP BY ?dept
} AS %counts
SELECT ?department
WHERE {
  BIND (MAX(?missingCount) AS ?maxMissing)
  {
    SELECT ?dept ?missingCount
    WHERE { 
      INCLUDE <#counts>
    }
  } 
  FILTER (?missingCount = ?maxMissing)
  BIND (IRI(CONCAT('http://example.org/core_scholar_shallow/Department', STRHASH(STR(?dept)))) AS ?department)
}

