PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?city ?college
WHERE {
  ?univ a coresr-ont:University ;
        coresr-ont:locatedAt ?loc .
  ?loc a coresr-ont:Location ;
       coresr-ont:atState ?state .
  ?state coresr-ont:inCity ?city .
  ?college a coresr-ont:College ;
           coresr-ont:partOf ?univ .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?publication
WHERE {
  ?publication a coresr-ont:Publication .
  ?contributor a coresr-ont:Contributor ;
               coresr-ont:contributedTo ?publication ;
               coresr-ont:performsRole [ 
                 a coresr-ont:Agent ;
                 coresr-ont:associatedWith ?department
               ] .
  FILTER NOT EXISTS {
    ?otherContributor a coresr-ont:Contributor ;
                      coresr-ont:contributedTo ?publication ;
                      coresr-ont:performsRole [ 
                        a coresr-ont:Agent ;
                        coresr-ont:associatedWith ?department
                      ] .
    FILTER(?otherContributor != ?contributor)
  }
}
GROUP BY ?publication
HAVING (COUNT(DISTINCT ?department) > 1)

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?pubType (AVG(?diff) AS ?avgDiff)
FROM <http://example.org/kg>
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:dateOfSubmission ?submissionDate ;
       coresr-ont:dateOfPublication ?publicationDate ;
       coresr-ont:hasPublicationType ?pubTypeNode .

  ?pubTypeNode coresr-ont:typeAsString ?pubType .

  BIND (xsd:integer(?publicationDate) - xsd:integer(?submissionDate) AS ?diff)
}
GROUP BY ?pubType
ORDER BY DESC(?avgDiff)
LIMIT 1

