PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?state ?university
WHERE {
  # Count publications per university, grouped by the state of its location
  SELECT ?state (MAX(?pubCount) AS ?maxPubCount)
  {
    SELECT ?university ?state (COUNT(DISTINCT ?publication) AS ?pubCount)
    WHERE {
      ?university a coresr-ont:University ;
                  coresr-ont:locatedAt ?location .
      ?location   a coresr-ont:Location ;
                  coresr-ont:atState  ?state .
      # Publications contributed by agents associated with the university
      ?contributor a coresr-ont:Contributor ;
                   coresr-ont:contributedTo ?publication ;
                   coresr-ont:isPerformedBy ?agent .
      ?agent       a coresr-ont:Agent ;
                   coresr-ont:associatedWith ?department .
      ?department  a coresr-ont:Department ;
                   coresr-ont:partOf ?university .
    }
    GROUP BY ?university ?state
  }
  GROUP BY ?state
}
# Retrieve the university (or universities) that achieve the max count per state
{
  SELECT ?state ?university ?pubCount
  WHERE {
    ?university a coresr-ont:University ;
                coresr-ont:locatedAt ?location .
    ?location   a coresr-ont:Location ;
                coresr-ont:atState  ?state .
    # Publications contributed by agents associated with the university
    ?contributor a coresr-ont:Contributor ;
                 coresr-ont:contributedTo ?publication ;
                 coresr-ont:isPerformedBy ?agent .
    ?agent       a coresr-ont:Agent ;
                 coresr-ont:associatedWith ?department .
    ?department  a coresr-ont:Department ;
                 coresr-ont:partOf ?university .
    {
      SELECT ?university (COUNT(DISTINCT ?publication) AS ?pubCount)
      WHERE { 
        FILTER(?university = ?university)
        ?contributor2 a coresr-ont:Contributor ;
                      coresr-ont:contributedTo ?publication2 ;
                      coresr-ont:isPerformedBy ?agent2 .
        ?agent2       a coresr-ont:Agent ;
                      coresr-ont:associatedWith ?department2 .
        ?department2  a coresr-ont:Department ;
                      coresr-ont:partOf ?university .
      }
      GROUP BY ?university
    }
  }
}
HAVING (?pubCount = ?maxPubCount)
ORDER BY ?state

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?pub
WHERE {
  ?pub a coresr-ont:Publication .
  SELECT ?pub (COUNT(DISTINCT ?dept) AS ?deptCount)
  WHERE {
    ?contributor a coresr-ont:Contributor ;
                 coresr-ont:contributedTo ?pub .
    ?agent a coresr-ont:Agent ;
           coresr-ont:performsRole ?contributor .
    ?agent coresr-ont:associatedWith ?dept .
  }
  GROUP BY ?pub
  HAVING (?deptCount > 1)
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?pubType (AVG(?diffDays) AS ?avgDiff)
FROM <http://example.org/core_scholar_rich/>
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:dateOfSubmission ?subDate ;
       coresr-ont:dateOfPublication ?pubDate ;
       coresr-ont:hasPublicationType ?pt .

  BIND (xsd:integer(?pubDate) - xsd:integer(?subDate) AS ?diffDays)

  BIND (strafter(str(?pt), "#") AS ?pubType)   # extract local name of the publication type
}
GROUP BY ?pubType
ORDER BY DESC(?avgDiff)
LIMIT 1

