PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?city ?college
WHERE {
  ?university a coresr-ont:University ;
              coresr-ont:locatedAt ?location .
  ?location a coresr-ont:Location ;
            coresr-ont:atState ?state .
  ?state a coresr-ont:State ;
         coresr-ont:inCity ?city .
  ?college a coresr-ont:College ;
           coresr-ont:partOf ?university .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?publication
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:submittedBy ?author .
  ?author coresr-ont:associatedWith ?department .

  SELECT DISTINCT ?publication
  WHERE {
    ?publication a coresr-ont:Publication ;
                 coresr-ont:submittedBy ?author1 ;
                 coresr-ont:submittedBy ?author2 .
    ?author1 coresr-ont:associatedWith ?dept1 .
    ?author2 coresr-ont:associatedWith ?dept2 .
    FILTER (?author1 != ?author2 && ?dept1 != ?dept2)
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?pubType (AVG(?diff) AS ?avgDays)
WHERE {
  ?publication coresr-ont:dateOfSubmission ?submissionDate ;
               coresr-ont:dateOfPublication ?pubDate ;
               coresr-ont:hasPublicationType ?pubType .
  FILTER (BOUND(?submissionDate) && BOUND(?pubDate))
  BIND ((xsddate:?pubDate - xsddate:?submissionDate) AS ?diff)
}
GROUP BY ?pubType
ORDER BY DESC(?avgDays)
LIMIT 1

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?author ?fieldOfStudy
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .   # has an advisor
  ?pub a coresr-ont:Publication ;
       coresr-ont:submittedBy ?author ;    # submitted by the author
       coresr-ont:associatedFieldOfStudy ?fieldOfStudy .  # belongs to a field of study
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?detail ?when
WHERE {
  ?hazard a kwg-ont:Hazard .

  OPTIONAL { ?hazard ?p ?o . FILTER(?p != geo:hasDefaultGeometry && ?p != kwg-ont:hasGeometry) }
  BIND(COALESCE(str(?p), '') AS ?detailProp)
  BIND(COALESCE(str(?o), '') AS ?detailValue)

  OPTIONAL { 
    ?hazard kwg-ont:hasTemporalScope ?temp .
    BIND(IF(isLiteral(?temp), str(?temp), STRDT(?temp, time:dateTime)) AS ?when) 
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
SELECT ?place ?name WHERE {
  ?place a geo:Feature ;
         rdfs:label ?name .
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?place ?property ?value
WHERE {
  { 
    # Health care facilities (Hospital, Pharmacy, PublicHealthDepartment)
    VALUES ?FacilityClass { kwg-ont:Hospital kwg-ont:Pharmacy kwg-ont:PublicHealthDepartment }
    ?place a ?FacilityClass ;
           geo:hasDefaultGeometry|kwg-ont:hasGeometry ?geom .

    # Hospital‑specific attributes
    OPTIONAL { ?place kwg-ont:hospitalType ?hospitalType . }
    OPTIONAL { ?place kwg-ont:helipadAvailability ?helipadAvail . }
    OPTIONAL { ?place kwg-ont:hospitalStatus ?hospitalStatus . }
    OPTIONAL { ?place kwg-ont:noHospitalBeds ?noBeds . }
    OPTIONAL { ?place kwg-ont:hospitalAddress ?address . }
    OPTIONAL { ?place kwg-ont:telephoneNo ?phone . }
    OPTIONAL { ?place kwg-ont:website ?web . }

    # Pharmacy‑specific attributes
    OPTIONAL { ?place kwg-ont:pharmacyType ?pharmType . }
    OPTIONAL { ?place kwg-ont:pharmacyName ?pharmName . }

    # PublicHealthDepartment‑specific observations (public‑health metrics)
    OPTIONAL {
      ?obs a kwg-ont:PublicHealthObservation ;
          sosa:hasFeatureOfInterest ?place ;
          sosa:observedProperty ?property ;
          sosa:result ?value .
    }
  }

  UNION

  { 
    # Public‑health observations attached directly to any geographical place
    ?place a geo:SpatialObject ;               # covers all geographic entities (AdministrativeRegion, S2Cell, etc.)
    ?obs a kwg-ont:PublicHealthObservation ;
        sosa:hasFeatureOfInterest ?place ;
        sosa:observedProperty ?property ;
        sosa:result ?value .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?place ?observableProperty ?observationResult
WHERE {
  ?place a kwg-ont:CensusACS5YearEstimatesObservationCollection ;
         sosa:hasFeatureOfInterest ?feature .
  ?collection a sosa:ObservationCollection ;
              sosa:hasMember ?observation .
  ?observation a sosa:Observation ;
               sosa:observedProperty ?observableProperty ;
               sosa:result ?observationResult .
  FILTER(?observableProperty IN (
    kwg-ont:censusObservableProperty.totalPopulation,
    kwg-ont:censusObservableProperty.malePopulation,
    kwg-ont:censusObservableProperty.femalePopulation,
    kwg-ont:censusObservableProperty.householdUnits
  ))
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?earthquake (COUNT(?earthquake) AS ?count)
WHERE {
  ?earthquake a kwg-ont:Earthquake .
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?attribute (COUNT(DISTINCT ?hazard) AS ?count)
WHERE {
  ?hazard a kwg-ont:NOAATornado ;
          sosa:observedProperty ?attribute .
  ?place a geo:SpatialObject ;
          kwg-ont:spatialRelation ?hazard .
} 
GROUP BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?hazardEvent ?observableProperty ?observationValue
WHERE {
  # Storm-specific hazard events (NOAAHazardEvent that are storm-related)
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
               a/(kwg-ont:isA|rdf:type) ?stormType .   # capture any subclass indicating a storm

  # Observations of the event
  ?observation a sosa:Observation ;
                sosa:hasFeatureOfInterest ?hazardEvent ;
                sosa:observedProperty ?observableProperty .

  OPTIONAL {
    ?observation kwg-ont:value ?observationValue .   # retrieve any literal value if present
  }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?hazard ?attribute ?value
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          a kwg-ont:Flood .
  ?obs a sosa:Observation ;
       sosa:observedProperty ?attribute ;
       sosa:hasFeatureOfInterest ?hazard ;
       sosa:result ?value .
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?climateProp
WHERE {
  ?place a geo:Feature .
  ?obs a sosa:Observation ;
       sosa:observedProperty ?climateProp ;
       sosa:hasFeatureOfInterest ?place .
  FILTER (isIRI(?climateProp) && ?climateProp =<kwg-ont:ClimateObservableProperty>)
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?hazardEvent ?impactProperty ?impactValue
WHERE {
  ?impactObservationCollection a kwg-ont:ImpactObservationCollection ;
                              sosa:hasFeatureOfInterest ?hazardEvent .
  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:observedProperty ?impactProperty ;
                     sosa:result ?impactValue ;
                     sosa:isMemberOf ?impactObservationCollection .
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?impactObservation
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
               kwg-ont:affectedByInverse ?impactObservation .
  ?impactObservation a kwg-ont:ImpactObservation .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?attributeValue ?impactProperty ?impactValue (COALESCE(?temporal, "") AS ?temporalData)
WHERE {
  # Hurricane-specific hazard and its attributes
  ?hazard a kwg-ont:NOAAHurricane ;
          sosa:hasFeatureOfInterest ?place .

  OPTIONAL {
    ?obs a sosa:Observation ;
         sosa:observedProperty ?attributeProp ;
         sosa:hasFeatureOfInterest ?hazard ;
         sosa:resultValue ?attributeValue .
    # Include temporal data if present
    OPTIONAL { ?obs sosa:phenomenonTime ?temporal . }
  }

  # Damage impact details and their temporal data (if any)
  ?impactObs a kwg-ont:ImpactObservation ;
             sosa:hasFeatureOfInterest ?hazard .

  ?impactObs sosa:observedProperty ?impactProp ;
             sosa:resultValue ?impactValue .

  OPTIONAL {
    ?impactObs sosa:phenomenonTime ?temporal .
  }

  # Bind the place (geographical entity) related to the hurricane
  BIND(?place AS ?place)
}

