PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?pubType (MAX(?avgDays) AS ?maxAvgDays)
WHERE {
  SELECT ?pubType (AVG(?daysDiff) AS ?avgDays)
  WHERE {
    ?pub a coress-ont:Publication ;
         coress-ont:hasPublicationType ?pubType ;
         coress-ont:dateOfSubmission ?subDate ;
         coress-ont:dateOfPublication ?pubDate .
    BIND (xsd:integer(?pubDate - ?subDate) AS ?daysDiff)
  }
  GROUP BY ?pubType
}
ORDER BY DESC(?avgDays)
LIMIT 1

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author (COUNT(DISTINCT ?field) AS ?fieldCount)
WHERE {
  ?author a coress-ont:Author ;
          coress-ont:advisedBy ?advisor .
  ?pub a coress-ont:Publication ;
       coress-ont:submittedBy ?author ;
       coress-ont:associatedFieldOfStudy ?field .
}
GROUP BY ?author

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department (COUNT(*) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coress-ont:Agent ;
         coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?name WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?name .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?attribute ?value
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name }
  UNION
  # Health-related attributes of places
  {
    SELECT ?place (kwgl-ont:percentBelowPovertyLine AS ?attribute) ?value
    WHERE { ?place kwgl-ont:percentBelowPovertyLine ?value }
  }
  UNION
  {
    SELECT ?place (kwgl-ont:percentDiabetic AS ?attribute) ?value
    WHERE { ?place kwgl-ont:percentDiabetic ?value }
  }
  UNION
  {
    SELECT ?place (kwgl-ont:percentObese AS ?attribute) ?value
    WHERE { ?place kwgl-ont:percentObese ?value }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazardType (COUNT(DISTINCT ?event) AS ?count)
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType ?hazardType .
  FILTER(?hazardType = kwglr:earthquake)
}
GROUP BY ?hazardType

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?attribute (COUNT(DISTINCT ?place) AS ?count)
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType kwglr:tornado .
  ?hazard ?p ?o .      # any property-value pair on the tornado hazard event
  BIND(?p AS ?attribute)
  FILTER NOT EXISTS { ?hazard a kwgl-ont:Tornado }   # exclude class-level attributes of Tornado itself
  {
    SELECT ?place
    WHERE {
      ?place a kwgl-ont:Place ;
             kwgl-ont:impactedBy ?hazard .
    }
  }
}
GROUP BY ?attribute

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hazardEvent ?hazardType ?placeName 
       ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars
       ?startDate ?endDate ?numberOfDeaths
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType ?hazardType ;
               kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres ;
               kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars ;
               kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars ;
               kwgl-ont:hasStartDate ?startDate ;
               kwgl-ont:hasEndDate   ?endDate ;
               kwgl-ont:numberOfDeaths ?numberOfDeaths .

  FILTER ( ?hazardType IN (
            kwglr:hurricane,
            kwglr:tornado,
            kwglr:stormSurgeTide,
            kwglr:thunderstormWind,
            kwglr:strongWind,
            kwglr:highWind,
            kwglr:winterStorm,
            kwglr:winterWeather ) )

  ?hazardEvent kwgl-ont:hasImpacted ?place .
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?placeName .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?place ?property ?value
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:averageCoolingDegreeDaysPerMonth ?value }      # property pattern repeated for each climate-specific attribute
  OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonth ?value }
  OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsius ?value }
  OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsius ?value }
  OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsius ?value }
  OPTIONAL { BIND (kwgl-ont:averageCoolingDegreeDaysPerMonth AS ?property) } 
  # ... repeat BIND for each property to map it back to the variable ?property
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hazardEvent ?name ?startDate ?endDate ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths ?hazardType
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType ?hazardType .

  FILTER(?hazardType = kwglr:earthquake)

  OPTIONAL { ?hazardEvent kwgl-ont:hasName          ?name }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate     ?startDate }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate       ?endDate }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres   ?affectedAreaInAcres }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths   ?numberOfDeaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?damageToCropsInDollars ?damageToInfrastructureInDollars
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars ;
               kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars .
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?attributeValue ?damageImpact ?temporalData
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType kwglr:hurricane .  # filter for hurricane events

  # Hurricane-specific attributes (generic hazard event properties)
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?attributeValue . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?attributeValue . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?attributeValue . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?attributeValue . }

  # Temporal data if available
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?temporalData . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate   ?temporalData . }

  # Damage impact details on the related place (impactedBy relationship)
  ?place a kwgl-ont:Place ;
         kwgl-ont:impactedBy ?hazardEvent .

  # All hurricane damage impact properties defined for Place
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?damageImpact . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?damageImpact . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?damageImpact . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 ?damageImpact . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 ?damageImpact . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 ?damageImpact . }

  # Number of hurricanes impacting the place
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?damageImpact . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2018 ?damageImpact . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2019 ?damageImpact . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2020 ?damageImpact . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2021 ?damageImpact . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2022 ?damageImpact . }
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hazardEvent ?placeName ?damageCrops ?damageInfrastructure
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType kwglr:tornado ;
               kwgl-ont:damageToCropsInDollars ?damageCrops ;
               kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure .
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate   ?endDate   . }

  FILTER (bound(?startDate) && bound(?endDate))
  FILTER (?startDate >= "2020-01-01"^^xsd:date && ?endDate <= "2022-12-31"^^xsd:date)

  ?hazardEvent kwgl-ont:hasImpacted ?place .
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?placeName .
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazardEvent ?damageCrops ?damageInfrastructure
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType ?hazardType .

  FILTER (?hazardType IN (
    kwglr:hurricane,
    kwglr:tornado,
    kwglr:stormSurgeTide,
    kwglr:thunderstormWind,
    kwglr:strongWind,
    kwglr:highWind,
    kwglr:winterStorm,
    kwglr:winterWeather,
    kwglr:tropicalDepression,
    kwglr:tropicalStorm
  ))

  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageCrops }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure }

  FILTER EXISTS {
    ?hazardEvent kwgl-ont:hasImpacted ?place .
    ?place a kwgl-ont:Place ;
           kwgl-ont:hasStartDate ?startDate ;
           kwgl-ont:hasEndDate ?endDate .

    FILTER (?startDate >= "2020-01-01"^^xsd:date && ?endDate <= "2023-12-31"^^xsd:date)
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?doiValue
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:hasIdentifier ?doi .
  ?doi a coresr-ont:DOI ;
       coresr-ont:doiAsString ?doiValue .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?university ?city
WHERE {
  ?university a coresr-ont:University ;
              coresr-ont:locatedAt ?location .
  ?location a coresr-ont:Location ;
            coresr-ont:atState ?state .
  ?state a coresr-ont:State ;
         coresr-ont:inCity ?city .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author ?advisor
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .
  ?advisor a coresr-ont:Advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?pubType
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:hasPublicationType ?pubType .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?agent ?department
WHERE {
  ?agent a coresr-ont:Agent ;
         coresr-ont:associatedWith ?department .
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?fieldOfStudy ?publication
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?city ?college
WHERE {
  ?univ a coresr-ont:University ;
        coresr-ont:locatedAt [ a coresr-ont:Location ; coresr-ont:inCity ?city ] .
  ?col a coresr-ont:College ;
       coresr-ont:partOf ?univ .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?pubCount)
FROM <http://example.org/kg>
WHERE {
  ?department a coresr-ont:Department ;
              coresr-ont:partOf ?college .

  ?college a coresr-ont:College ;
           coresr-ont:partOf ?university .

  ?university a coresr-ont:University ;
              coresr-ont:locatedAt ?location .

  ?location a coresr-ont:Location ;
            coresr-ont:atState ?state .

  ?author a coresr-ont:Author ;
          coresr-ont:associatedWith ?department .

  ?publication a coresr-ont:Publication ;
               coresr-ont:submittedBy ?author .
}
GROUP BY ?state ?university
ORDER BY ?state DESC(?pubCount)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?publication
WHERE {
  ?publication a coresr-ont:Publication .
  SELECT ?publication (COUNT(DISTINCT ?department) AS ?deptCount)
  WHERE {
    ?author a coresr-ont:Author ;
           coresr-ont:submits ?publication .
    ?author coresr-ont:associatedWith ?department .
    FILTER (?department != '')
  }
  GROUP BY ?publication
  HAVING (?deptCount > 1)
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?pubType (AVG(?diffDays) AS ?avgDiff)
FROM :data
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:dateOfSubmission ?submissionDate ;
       coresr-ont:dateOfPublication ?publicationDate ;
       coresr-ont:hasPublicationType ?pubType .
  FILTER (BOUND(?submissionDate) && BOUND(?publicationDate))
  BIND ((xsd:dateTime(?publicationDate) - xsd:dateTime(?submissionDate)) / ^xsdduration:"P1D" AS ?diffDays)
}
GROUP BY ?pubType
ORDER BY DESC(?avgDiff)
LIMIT 1

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author ?fieldOfStudy
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .   # author has an advisor
  ?pub a coresr-ont:Publication ;
       coresr-ont:submittedBy ?author ;    # the publication is submitted by that author
       coresr-ont:associatedFieldOfStudy ?fieldOfStudy .  # publication's field of study
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author
WHERE {
  ?author a coress-ont:Author .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?doi
WHERE {
  ?publication a coress-ont:Publication .
  OPTIONAL { ?publication coress-ont:hasDOI ?doi . }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department
WHERE {
  ?department a coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication a coress-ont:Publication .
  OPTIONAL { ?publication coress-ont:dateOfSubmission ?submissionDate . }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?university ?city
WHERE {
  ?university a coress-ont:University .
  OPTIONAL { ?university coress-ont:atCity ?city . }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author ?advisor
WHERE {
  ?author a coress-ont:Author ;
          coress-ont:advisedBy ?advisor .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?type
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:hasPublicationType ?type .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?agent ?department
WHERE {
  ?agent a coress-ont:Agent ;
         coress-ont:worksInDepartment ?department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?fieldOfStudy ?publication
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?city ?college
WHERE {
  ?univ a coress-ont:University ;
        coress-ont:atCity ?city ;
        coress-ont:hasCollege ?college .
  ?college a coress-ont:College .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?state ?university (COUNT(DISTINCT ?pub) AS ?publicationCount)
WHERE {
  ?author a coress-ont:Author ;
          coress-ont:submits ?pub .

  ?pub a coress-ont:Publication .

  ?dept a coress-ont:Department ;
        coress-ont:hasAgent ?author .

  ?college a coress-ont:College ;
           coress-ont:hasDepartment ?dept .

  ?univ a coress-ont:University ;
        coress-ont:hasCollege ?college ;
        coress-ont:atState ?state .

  BIND(?univ AS ?university)
}
GROUP BY ?state ?university
ORDER BY DESC(?publicationCount)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?pub
WHERE {
  ?pub a coress-ont:Publication .
  ?pub coress-ont:submittedBy ?author .
  ?author a coress-ont:Author ;
          coress-ont:performsRole ?role .
  ?role coress-ont:isPerformedBy ?agent .
  ?agent coress-ont:worksInDepartment ?dept1 .
  FILTER NOT EXISTS {
    ?otherAuthor coress-ont:submittedBy ?pub .
    ?otherAuthor a coress-ont:Author ;
                 coress-ont:performsRole ?otherRole .
    ?otherRole coress-ont:isPerformedBy ?otherAgent .
    ?otherAgent coress-ont:worksInDepartment ?dept2 .
    FILTER (?dept1 != ?dept2)
  }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?pubType (MAX(?avgDays) AS ?maxAvgDays)
WHERE {
  SELECT ?pubType (AVG(?daysDiff) AS ?avgDays)
  WHERE {
    ?pub a coress-ont:Publication ;
         coress-ont:hasPublicationType ?pubType ;
         coress-ont:dateOfSubmission ?submissionDate ;
         coress-ont:dateOfPublication ?publicationDate .
    FILTER (bound(?submissionDate) && bound(?publicationDate))
    BIND (daysAfterYearMonthDay(?publicationDate) - daysAfterYearMonthDay(?submissionDate) AS ?daysDiff)
  }
  GROUP BY ?pubType
}
ORDER BY DESC(?avgDays)
LIMIT 1

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT DISTINCT ?author
WHERE {
  ?author a coress-ont:Author .
  ?author coress-ont:advisedBy ?advisor .  # has an advisor
  ?publication a coress-ont:Publication ;
               coress-ont:submittedBy ?author ;   # submitted by the author
               coress-ont:associatedFieldOfStudy ?field .  # each field
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department (COUNT(*) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coress-ont:Agent ;
        coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazardEvent
       ?typeLabel
       ?startDate
       ?endDate
       ?affectedAreaInAcres
       ?damageToCropsInDollars
       ?damageToInfrastructureInDollars
       ?numberOfDeaths
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazardEvent kwgl-ont:hasHazardType ?type ; rdfs:label ?typeLabel . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate   ?endDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres      ?affectedAreaInAcres . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars    ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths            ?numberOfDeaths . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?name WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?name .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?place
  (CONCAT('hasPopulation of ', STR(?population)) AS ?attribute)
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population . }
}
UNION
SELECT DISTINCT
  ?place
  (CONCAT('hasNumberOfHouseHolds of ', STR(?households)) AS ?attribute)
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households . }
}
UNION
SELECT DISTINCT
  ?place
  (CONCAT('percentBelowPovertyLine of ', STR(?poverty)) AS ?attribute)
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?poverty . }
}
UNION
SELECT DISTINCT
  ?place
  (CONCAT('percentDiabetic of ', STR(?diabetic)) AS ?attribute)
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabetic . }
}
UNION
SELECT DISTINCT
  ?place
  (CONCAT('percentObese of ', STR(?obese)) AS ?attribute)
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:percentObese ?obese . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?population ?households
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazardType (COUNT(DISTINCT ?event) AS ?count)
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType ?hazardType .
}
GROUP BY ?hazardType
ORDER BY ?hazardType

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute (COUNT(DISTINCT ?place) AS ?count)
WHERE {
  ?attribute rdf:type owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place ;
             rdfs:label ?label .
  FILTER (CONTAINS(LCASE(STR(?label)), "tornado") || CONTAINS(LCASE(STR(?attribute)), "tornado"))
  ?place a kwgl-ont:Place ;
         ?attribute ?value .
}
GROUP BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?label
  ?range
WHERE {
  ?attribute rdf:type owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place .

  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?label . }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "storm") ||
    CONTAINS(LCASE(STR(?label)), "storm")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?label
WHERE {
  ?attribute rdf:type owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place ;
             rdfs:label ?label .

  FILTER (CONTAINS(LCASE(STR(?attribute)), "flood") || CONTAINS(LCASE(STR(?label)), "flood"))
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
WHERE {
  ?attribute rdf:type owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazardEvent
  ?type
  ?name
  ?startDate
  ?endDate
  ?affectedAreaInAcres
  ?damageToCropsInDollars
  ?damageToInfrastructureInDollars
  ?numberOfDeaths
WHERE {
  ?hazardEvent rdf:type kwgl-ont:Earthquake ;
               kwgl-ont:hasHazardType ?type .

  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?event
       ?affectedAreaInAcres
       ?damageToCropsInDollars
       ?damageToInfrastructureInDollars
       ?hasStartDate
       ?hasEndDate
       ?numberOfDeaths
WHERE {
  ?event a kwgl-ont:HazardEvent .
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?event kwgl-ont:hasStartDate ?hasStartDate . }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?hasEndDate . }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?numberOfDeaths . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?damageProperty ?damageValue
WHERE {
  ?place kwgl-ont:impactedBy ?hazard .
  OPTIONAL { ?place ?damageProperty ?damageValue }
  FILTER (isIRI(?damageProperty) && 
          EXISTS { ?x ?damageProperty ?y . })
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?damageProp
  ?place
  ?damageValue
  (COALESCE(?startDate,?endDate) AS ?temporalData)
WHERE {
  { ?hazard a kwgl-ont:Hurricane ;
            kwgl-ont:hasImpacted ?place . }
  UNION
  { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?count . }

  # Hurricane‑specific damage properties on places
  VALUES ?damageProp {
    kwgl-ont:dollarDamageOfHurricanesImpactingPlace
    kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018
    kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019
    kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020
    kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021
    kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022
  }
  ?place ?damageProp ?damageValue .

  # Optional temporal data from the related hazard event (if any)
  OPTIONAL {
    ?hazard kwgl-ont:hasStartDate ?startDate ;
            kwgl-ont:hasEndDate   ?endDate .
  }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?event ?damageCrops ?damageInfrastructure
WHERE {
  ?event rdf:type kwgl-ont:Tornado ;
         kwgl-ont:hasHazardType kwglr:tornado .

  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }

  FILTER ( EXISTS {
    ?event kwgl-ont:hasImpacted ?place .
    ?place a kwgl-ont:Place .
  } )

  FILTER ( EXISTS {
    ?event kwgl-ont:hasStartDate ?startDate .
    ?event kwgl-ont:hasEndDate   ?endDate .
    FILTER ( ?startDate <= "2025-01-01"^^xsd:date && ?endDate >= "2020-01-01"^^xsd:date )
  } )
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?event ?damageCrops ?damageInfrastructure
WHERE {
  ?event rdf:type/rdfs:subClassOf* kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType ?hazardType .

  FILTER (?hazardType IN (
    kwglr:hurricane,
    kwglr:stormSurgeTide,
    kwglr:tornado
  ))

  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }

  FILTER EXISTS {
    ?event kwgl-ont:hasImpacted ?place .
    ?place rdf:type/rdfs:subClassOf* kwgl-ont:Place .

    OPTIONAL {
      ?event kwgl-ont:hasStartDate ?startDate .
      FILTER (?startDate >= "2020-01-01"^^xsd:date && ?startDate <= "2023-12-31"^^xsd:date)
    }
    OPTIONAL {
      ?event kwgl-ont:hasEndDate ?endDate .
      FILTER (?endDate >= "2020-01-01"^^xsd:date && ?endDate <= "2023-12-31"^^xsd:date)
    }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazardEvent ?type ?startDate ?endDate ?impactedPlace
       ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasHazardType ?type . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate   ?endDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres          ?affectedAreaInAcres . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars       ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths               ?numberOfDeaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasImpacted ?impactedPlace .
             ?impactedPlace a kwgl-ont:Place ;
                            kwgl-ont:hasName ?placeName . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?name
WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?name .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?population ?households
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population } .
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
SELECT DISTINCT ?hazardType (COUNT(DISTINCT ?event) AS ?count)
FROM <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
WHERE {
  ?event a kwglr:Earthquake ;
         kwgl-ont:hasHazardType ?hazardType .
}
GROUP BY ?hazardType
ORDER BY ?hazardType

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?attr (COUNT(DISTINCT ?place) AS ?count)
WHERE {
  ?event a kwgl-ont:Tornado ;
         kwgl-ont:hasImpacted ?place .
  ?place ?attr ?value .
}
GROUP BY ?attr
ORDER BY ?attr

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?property
WHERE {
  {
    SELECT ?property WHERE { ?p a kwgl-ont:averageCoolingDegreeDaysPerMonth . }
