    SELECT ?property WHERE { ?p a kwgl-ont:averageMonthlyTemperatureInCelsius . }
  } UNION {
    SELECT ?property WHERE { ?p a kwgl-ont:maximumMonthlyTemperatureInCelsius . }
  } UNION {
    SELECT ?property WHERE { ?p a kwgl-ont:minimumMonthlyTemperatureInCelsius . }
  } UNION {
    SELECT ?property WHERE { ?p a kwgl-ont:dollarDamageOfFiresImpactingPlace . }
  } UNION {
    SELECT ?property WHERE { ?p a kwgl-ont:dollarDamageOfFloodsImpactingPlace . }
  } UNION {
    SELECT ?property WHERE { ?p a kwgl-ont:dollarDamageOfHurricanesImpactingPlace . }
  } UNION {
    SELECT ?property WHERE { ?p a kwgl-ont:dollarDamageOfLandslidesImpactingPlace . }
  } UNION {
    SELECT ?property WHERE { ?p a kwgl-ont:dollarDamageOfStormSurgesImpactingPlace . }
  } UNION {
    SELECT ?property WHERE { ?p a kwgl-ont:dollarDamageOfTornadoesImpactingPlace . }
  } UNION {
    SELECT ?property WHERE { ?p a kwgl-ont:hasNumberOfHouseHolds . }
  } UNION {
    SELECT ?property WHERE { ?p a kwgl-ont:hasPopulation . }
  } UNION {
    SELECT ?property WHERE { ?p a kwgl-ont:numberOfEarthquakesImpactingPlace . }
  } UNION {
    SELECT ?property WHERE { ?p a kwgl-ont:numberOfFiresImpactingPlace . }
  } UNION {
    SELECT ?property WHERE { ?p a kwgl-ont:numberOfFloodsImpactingPlace . }
  } UNION {
    SELECT ?property WHERE { ?p a kwgl-ont:numberOfHurricanesImpactingPlace . }
  } UNION {
    SELECT ?property WHERE { ?p a kwgl-ont:numberOfLandslidesImpactingPlace . }
  } UNION {
    SELECT ?property WHERE { ?p a kwgl-ont:numberOfStormSurgesImpactingPlace . }
  } UNION {
    SELECT ?property WHERE { ?p a kwgl-ont:numberOfTornadoesImpactingPlace . }
  } UNION {
    SELECT ?property WHERE { ?p a kwgl-ont:percentBelowPovertyLine . }
  } UNION {
    SELECT ?property WHERE { ?p a kwgl-ont:percentDiabetic . }
  } UNION {
    SELECT ?property WHERE { ?p a kwgl-ont:percentObese . }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazardEvent ?type ?name ?startDate ?endDate ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths
WHERE {
  ?hazardEvent a kwgl-ont:Earthquake ;
               kwgl-ont:hasHazardType ?type .
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate   ?endDate }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres      ?affectedAreaInAcres }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars    ?damageToCropsInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths            ?numberOfDeaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?damageProperty ?damageValue
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               ?damageProperty ?damageValue .
  FILTER ( ?damageProperty IN (
    kwgl-ont:damageToCropsInDollars,
    kwgl-ont:damageToInfrastructureInDollars,
    kwgl-ont:numberOfDeaths
  ))
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazardEvent ?attributeValue
WHERE {
  ?hazardEvent a kwgl-ont:Hurricane ;
               kwgl-ont:hasHazardType kwglr:hurricane .
  OPTIONAL { 
    ?hazardEvent kwgl-ont:affectedAreaInAcres ?area .
    BIND(?area AS ?attributeValue)
  }
  UNION
  {
    ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropsDamage .
    BIND(?cropsDamage AS ?attributeValue)
  }
  UNION
  {
    ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage .
    BIND(?infraDamage AS ?attributeValue)
  }
  UNION
  {
    ?hazardEvent kwgl-ont:numberOfDeaths ?deaths .
    BIND(?deaths AS ?attributeValue)
  }
  OPTIONAL { 
    ?hazardEvent kwgl-ont:hasStartDate ?startDate .
    BIND(?startDate AS ?temporalData)
  }
  OPTIONAL { 
    ?hazardEvent kwgl-ont:hasEndDate ?endDate .
    BIND(?endDate AS ?temporalData)
  }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?event ?damageCrops ?damageInfrastructure 
WHERE {
  ?event a kwgl-ont:Tornado ;
         kwgl-ont:hasHazardType kwglr:tornado .
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageCrops }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure }
  FILTER ( EXISTS {
    ?event kwgl-ont:hasStartDate ?startDate ;
           kwgl-ont:hasEndDate   ?endDate .
    FILTER (?startDate >= "2020-01-01"^^xsd:date && ?endDate <= "2023-12-31"^^xsd:date)
  })
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?event ?damageCrops ?damageInfrastructure
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType ?hazardType .

  FILTER (?hazardType IN (
    kwglr:hurricane,
    kwglr:stormSurgeTide,
    kwglr:tornado,
    kwglr:tropicalStorm,
    kwglr:tropicalDepression
  ))

  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageCrops }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure }

  # Temporal extent (example: events occurring in 2023)
  FILTER (YEAR(?event^kwgl-ont:hasStartDate) = 2023 || YEAR(?event^kwgl-ont:hasEndDate) = 2023)
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?doiValue
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:hasIdentifier ?doi .
  ?doi a coresr-ont:DOI ;
       coresr-ont:doiAsString ?doiValue .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?university ?city
WHERE {
  ?university a coresr-ont:University ;
              coresr-ont:locatedAt [ a coresr-ont:Location ; coresr-ont:atState [ a coresr-ont:State ; coresr-ont:inCity ?city ] ] .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?author ?advisor
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .
  ?advisor a coresr-ont:Advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?type
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:hasPublicationType ?pubType .

  ?pubType a coresr-ont:PublicationType ;
           coresr-ont:typeAsString ?type .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?agent ?department
WHERE {
  ?agent a coresr-ont:Agent ;
         coresr-ont:associatedWith ?department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?fieldOfStudy ?publication
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
  OPTIONAL { ?publication coresr-ont:hasTitle ?title }
  BIND(COALESCE(?title, STR(?publication)) AS ?pubLabel)
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?city ?college
WHERE {
  ?univ a coresr-ont:University ;
        coresr-ont:locatedAt [ a coresr-ont:Location ; coresr-ont:atState ?state ] .
  ?col a coresr-ont:College ;
       coresr-ont:partOf ?univ .
  OPTIONAL { ?state coresr-ont:inCity ?city . }
  BIND (COALESCE(?city, "Unknown City") AS ?city)
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?state ?university (COUNT(*) AS ?pubCount)
FROM   DEFAULT GRAPH
WHERE  {
  ?pub    a                     coresr-ont:Publication ;
         coresr-ont:submittedBy ?author .
  ?author a                     coresr-ont:Author ;
         coresr-ont:associatedWith ?department .
  ?department a                 coresr-ont:Department ;
                    coresr-ont:partOf / coresr-ont:partOf ?university .
  ?university a                 coresr-ont:University ;
                coresr-ont:locatedAt [ 
                     coresr-ont:atState ?state ] .
}
GROUP BY ?state ?university
ORDER BY ?state DESC(?pubCount)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication WHERE {
  ?pub a coresr-ont:Publication .
  SELECT ?pub (COUNT(DISTINCT ?dept) AS ?deptCount)
    WHERE {
      ?author a coresr-ont:Author ;
             coresr-ont:submits ?pub ;
             coresr-ont:associatedWith ?dept .
      FILTER(?dept != "")
    }
    GROUP BY ?pub
  HAVING (?deptCount > 1)
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?pubType (AVG(?diff) AS ?avgDiff)
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:dateOfSubmission ?submissionDate ;
       coresr-ont:dateOfPublication ?publicationDate ;
       coresr-ont:hasPublicationType ?pt .

  BIND ((xsd:dateTime(?publicationDate) - xsd:dateTime(?submissionDate)) / xsd:dayTimeDuration('P1D') AS ?diff)

  BIND (strafter(str(?pt), '#') AS ?pubType)  # extract local name as type identifier
}
GROUP BY ?pubType
ORDER BY DESC(?avgDiff)
LIMIT 1

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author ?fieldOfStudy
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .   # has an advisor
  ?pub    a coresr-ont:Publication ;
          coresr-ont:submittedBy ?author ;   # submitted by the author
          coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department (COUNT(*) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coresr-ont:Agent ;
        coresr-ont:associatedWith ?department .

  OPTIONAL { ?agent coresr-ont:hasContactInformation [ a coresr-ont:FamilyName ] } .

  FILTER (!BOUND(?familyName))
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

