PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?pubType (AVG(?diff) AS ?avgDays)
WHERE {
  ?pub a coress-ont:Publication ;
       coress-ont:dateOfSubmission ?subDate ;
       coress-ont:dateOfPublication ?pubDate ;
       coress-ont:hasPublicationType ?pubType .
  FILTER (BOUND(?subDate) && BOUND(?pubDate))
  BIND ((xsd:dateTime(?pubDate) - xsd:dateTime(?subDate)) / ^xsdt:dayTimeDuration('P1D') AS ?diff)
}
GROUP BY ?pubType
ORDER BY DESC(?avgDays)
LIMIT 1

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author
WHERE {
  ?author a coress-ont:Author ;
          coress-ont:advisedBy ?advisor .  # ensures the author has an advisor
  ?pub a coress-ont:Publication ;
       coress-ont:submittedBy ?author ;
       coress-ont:associatedFieldOfStudy ?field .
  FILTER NOT EXISTS {
    ?otherPub a coress-ont:Publication ;
             coress-ont:submittedBy ?author ;
             coress-ont:associatedFieldOfStudy ?field2 .
    FILTER (?field2 != ?field)
  }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department (COUNT(*) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coress-ont:Agent ;
        coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?hazard ?property ?value
WHERE {
  ?hazard a kwg-ont:Hazard .

  OPTIONAL { 
    ?hazard ?property ?value . 
    FILTER ( ?property != rdf:type && ?property != rdfs:subClassOf )
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?place ?name
WHERE {
  ?place a geo:SpatialObject ;
         rdfs:label ?name .
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?place ?property ?value
WHERE {
  { ?place a kwg-ont:DroughtZone . }
  UNION
  { ?place a geo:Feature ; sosa:isFeatureOfInterestOf ?obs ; sosa:hasResult ?result .
    ?obs sosa:observedProperty ?property ; sosa:usedProcedure ?sensor .
    OPTIONAL { ?result ?valuePred ?value . } }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?place ?property ?value
WHERE {
  ?obs a kwg-ont:CensusACS5YearEstimatesObservation ;
       sosa:hasFeatureOfInterest ?place ;
       sosa:observedProperty ?property ;
       sosa:resultValue ?value .
  FILTER (?property IN (kwg-ont:censusObservableProperty.totalPopulation,
                        kwg-ont:censusObservableProperty.malePopulation,
                        kwg-ont:censusObservableProperty.femalePopulation,
                        kwg-ont:censusObservableProperty.householdUnits))
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT (COUNT(DISTINCT ?earthquake) AS ?count)
WHERE {
  ?earthquake a kwg-ont:Earthquake .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?attribute (COUNT(DISTINCT ?hazard) AS ?count)
WHERE {
  ?hazard a kwg-ont:NOAATornado ;
          ?property ?value .
  BIND(?property AS ?attribute)
} 
GROUP BY ?attribute

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?stormTrack ?property ?value
WHERE {
  ?stormTrack a kwg-ont:StormTrack .
  OPTIONAL { 
    ?obs a sosa:Observation ;
         sosa:hasFeatureOfInterest ?stormTrack ;
         sosa:observedProperty ?property ;
         ?property ?value .
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?hazardType ?property ?value
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          rdfs:subClassOf* kwg-ont:Flood .

  OPTIONAL { 
    BIND (IF(isURI(?hazard), iri(str(?hazard)), ?hazard) AS ?hazardType)
  }

  OPTIONAL {
    ?obs a sosa:Observation ;
         sosa:hasFeatureOfInterest ?hazard ;
         ?property ?value .
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?hazard ?type ?property ?value
WHERE {
  ?hazard a kwg-ont:Earthquake .
  OPTIONAL { ?hazard rdfs:subClassOf* ?type . }
  OPTIONAL { ?hazard ?property ?value . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?hazardEvent ?impactProperty ?impactValue
WHERE {
  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:observedProperty ?impactProperty ;
                     sosa:resultValue ?impactValue ;
                     sosa:hasFeatureOfInterest ?hazardEvent .
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?impactObservation ?property ?value
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
               sosa:hasFeatureOfInterest ?hazard .
  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:observedProperty ?property ;
                     sosa:hasFeatureOfInterest ?hazardEvent .
  OPTIONAL { ?impactObservation ?valuePredicate ?value . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
SELECT ?hazard ?attribute ?impactProperty ?impactValue ?temporal
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          a kwg-ont:Hurricane .  # Hurricane‑specific hazard class

  # Hazard attributes (any property/value pair attached to the hurricane event)
  ?hazard ?attribute ?attrVal .

  # Damage impact details linked to the same hazard
  ?impactObservation a sosa:Observation ;
                     sosa:observedProperty ?impactProperty ;
                     sosa:result ?impactValue ;
                     sosa:featureOfInterest ?hazard .

  # Temporal data if available (phenomenonTime or temporal scope)
  OPTIONAL {
    { ?impactObservation sosa:phenomenonTime ?temporal } 
    UNION
    { ?hazard kwg-ont:hasTemporalScope ?temporal }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?hazard ?property ?value
WHERE {
  ?hazard a kwg-ont:NOAATornado ;
          sosa:hasFeatureOfInterest ?place .

  OPTIONAL { ?hazard ?property ?value . }

  FILTER ( EXISTS {
    ?place a geo:SpatialObject ;
           geo:sfWithin|geo:sfContains|kwg-ont:spatialRelation ?adminRegion .
    } )

  FILTER ( EXISTS {
    ?hazard kwg-ont:hasTemporalScope ?temporalExtent .
    } )
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?hazard ?damageProperty ?damageValue
WHERE {
  SERVICE <http://localhost:7200/sparql> {
    ?hazard a kwg-ont:NOAAHazardEvent ;
           a ?specificStorm .   # bind to storm‑specific hazard classes (e.g., NOAAHurricane, NOAATornado, etc.)

    # Temporal filter – adjust the literals as needed
    FILTER EXISTS { 
      ?hazard kwg-ont:hasTemporalScope ?temp .
      FILTER( ?temp >= "2023-01-01"^^xsd:dateTime && ?temp <= "2024-12-31"^^xsd:dateTime )
    }

    # Geographical relation – the hazard is related to a place (AdministrativeRegion, S2Cell, etc.)
    ?hazard kwg-ont:spatialRelation ?place .
    FILTER(?place a kwg-ont:AdministrativeRegion || ?place a kwg-ont:S2Cell)

    # Damage details via ImpactObservation
    ?impact a kwg-ont:ImpactObservation ;
            sosa:observedProperty ?damageProp ;
            sosa:result ?damageVal .
    FILTER(?damageProp = kwg-ont:impactObservableProperty.damageCrop ||
           ?damageProp = kwg-ont:impactObservableProperty.damageProperty)

    BIND(?hazard AS ?hazard)
    BIND(?damageProp AS ?damageProperty)
    BIND(?damageVal AS ?damageValue)
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author
WHERE {
  ?author rdf:type coress-ont:Author .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?doi
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:hasDOI ?doi .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT DISTINCT ?department
WHERE {
  ?department rdf:type coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:dateOfSubmission ?submissionDate .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?university ?city
WHERE {
  ?university a coress-ont:University ;
              coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?author ?advisor
WHERE {
  ?author a coress-ont:Author ;
          coress-ont:advisedBy ?advisor .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?pubType
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:hasPublicationType ?pubType .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?agent ?department
WHERE {
  ?agent a coress-ont:Agent ;
         coress-ont:worksInDepartment ?department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?fieldOfStudy
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?city ?collegeName
WHERE {
  ?univ a coress-ont:University ;
        coress-ont:atCity ?city ;
        coress-ont:hasCollege ?college .
  ?college a coress-ont:College ;
           rdfs:label ?collegeName .   # using rdfs:label as placeholder for college name
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?state ?universityName
WHERE {
  ?author a coress-ont:Author ;
          coress-ont:submits ?publication .

  ?publication a coress-ont:Publication ;
               coress-ont:submittedBy ?author .

  # Find the department of the author, then the college and university
  ?author coress-ont:worksInDepartment ?department .
  ?department coress-ont:departmentOf ?college .
  ?college coress-ont:collegeOf ?university .

  # Extract university details
  ?university a coress-ont:University ;
              coress-ont:atState ?state ;
              coress-ont:hasTitle ?universityName .

  # Count publications per university (within the same state)
  {
    SELECT ?university (COUNT(DISTINCT ?publication) AS ?pubCount)
    WHERE {
      ?author2 a coress-ont:Author ;
               coress-ont:submits ?publication .
      ?author2 coress-ont:worksInDepartment ?department2 .
      ?department2 coress-ont:departmentOf ?college2 .
      ?college2 coress-ont:collegeOf ?university .
    }
    GROUP BY ?university
  } [AS ?cnt] .

  # Keep only the university with the maximum count per state
  {
    SELECT ?state (MAX(?pubCount) AS ?maxCnt)
    WHERE { 
      ?u a coress-ont:University ;
         coress-ont:atState ?state ;
         coress-ont:hasTitle ?universityName .
      {
        SELECT ?u (COUNT(DISTINCT ?p) AS ?pubCount)
        WHERE {
          ?a a coress-ont:Author ;
             coress-ont:submits ?p .
          ?a coress-ont:worksInDepartment ?d .
          ?d coress-ont:departmentOf ?c .
          ?c coress-ont:collegeOf ?u .
        }
        GROUP BY ?u
      }
    }
    GROUP BY ?state
  } [AS ?maxCnt] .

  FILTER ( ?cnt = ?maxCnt )
}
ORDER BY ?state

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?publication
WHERE {
  ?pub coress-ont:type coress-ont:Publication .
  ?author1 coress-ont:type coress-ont:Author ;
           coress-ont:submits ?pub ;
           coress-ont:isPerformedBy ?agent1 ;
           coress-ont:worksInDepartment ?dept1 .
  ?author2 coress-ont:type coress-ont:Author ;
           coress-ont:submits ?pub ;
           coress-ont:isPerformedBy ?agent2 ;
           coress-ont:worksInDepartment ?dept2 .
  FILTER (?author1 != ?author2)
  FILTER (?dept1 != ?dept2)
  BIND(?pub AS ?publication)
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?pubType (AVG(?diffDays) AS ?avgDiff)
FROM : 
WHERE {
  ?pub a coress-ont:Publication ;
       coress-ont:dateOfSubmission ?subDate ;
       coress-ont:dateOfPublication ?pubDate ;
       coress-ont:hasPublicationType ?pubType .
  FILTER (BOUND(?subDate) && BOUND(?pubDate))
  BIND (xsd:integer((xs:dateTime(?pubDate) - xs:dateTime(?subDate)) / xs:dayTimeDuration('P1D')) AS ?diffDays)
}
GROUP BY ?pubType
ORDER BY DESC(?avgDiff)
LIMIT 1

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?author
WHERE {
  ?author a coress-ont:Author ;
          coress-ont:advisedBy ?advisor .   # has an advisor
  ?publication a coress-ont:Publication ;
               coress-ont:associatedFieldOfStudy ?field ;
               coress-ont:submittedBy ?author .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department (COUNT(*) AS ?missingFamilyNameCount)
WHERE {
  ?agent coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

