  ?pubContribution1 coresr-ont:contributedTo ?publication ;
                   a coresr-ont:Contributor ;
                   coresr-ont:associatedWith ?dept1 .
  ?pubContribution2 coresr-ont:contributedTo ?publication ;
                   a coresr-ont:Contributor ;
                   coresr-ont:associatedWith ?dept2 .
