}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?pubType (AVG(?diff) AS ?avgDiff)
WHERE {
  ?pub coresr-ont:dateOfSubmission ?submissionDate ;
       coresr-ont:dateOfPublication ?publicationDate ;
       coresr-ont:hasPublicationType ?type .
  BIND((xsddate(?publicationDate) - xsddate(?submissionDate)) / 86400 AS ?diff)
  ?type coresr-ont:typeAsString ?pubType
}
GROUP BY ?pubType
ORDER BY DESC(?avgDiff)
LIMIT 1

