ORDER BY DESC(?missingFamilyNameCount)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazard ?type ?name ?startDate ?endDate
   ?deaths ?damageInfrastructure ?damageCrops ?affectedArea
WHERE {
  ?hazard a kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type . }
  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate   ?endDate   . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths          ?deaths          . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars          ?damageCrops          . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres           ?affectedArea         . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?name WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?population ?households
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT COUNT(DISTINCT ?hazard) AS ?earthquakeHazardCount
WHERE {
  ?hazard a kwgl-ont:Earthquake .
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?attribute (STR(?attribute) AS ?attrStr)
WHERE {
  ?attribute rdf:type owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place .
  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") ||
    CONTAINS(LCASE(?attrStr), "flood")
  )
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?event
       ?dollarDamageOfFiresImpactingPlace2021
       ?numberOfDeaths
WHERE {
  ?event a kwgl-ont:HazardEvent .
  OPTIONAL { ?event kwgl-ont:dollarDamageOfFiresImpactingPlace2021 ?dollarDamageOfFiresImpactingPlace2021 . }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?numberOfDeaths . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazardAttr        # hurricane‑specific attribute name (e.g., numberOfHurricanesImpactingPlace2021)
  ?damageAttr       # damage impact attribute name (e.g., dollarDamageOfHurricanesImpactingPlace2019)
  ?place            # the geographical place
  ?attrValue        # value of the hurricane attribute on the place
  ?damageValue      # value of the damage impact attribute on the place
  ?startDateOpt     # optional start date of a related HazardEvent (if present)
  ?endDateOpt       # optional end date of a related HazardEvent (if present)
WHERE {
  {                                            # hurricane‑specific attributes that can be defined for a Place
    ?place a kwgl-ont:Place ;
           ?hazardAttr ?attrValue .
    FILTER (
      CONTAINS(str(?hazardAttr), "Hurricane") ||
      STRSTARTS(str(?hazardAttr), "numberOfHurricanesImpactingPlace") ||
      STRSTARTS(str(?hazardAttr), "dollarDamageOfHurricanesImpactingPlace")
    )
  }
  UNION
  {                                            # damage‑impact attributes (damage to infrastructure or crops) on the same Place
    ?place a kwgl-ont:Place ;
           ?damageAttr ?damageValue .
    FILTER (
      CONTAINS(str(?damageAttr), "dollarDamageOfHurricanesImpactingPlace") ||
      ?damageAttr IN (kwgl-ont:damageToInfrastructureInDollars, kwgl-ont:damageToCropsInDollars)
    )
  }
  OPTIONAL {                                   # temporal data of any HazardEvent that impacted the place
    ?event a kwgl-ont:HazardEvent ;
           kwgl-ont:hasImpacted ?place .
    OPTIONAL { ?event kwgl-ont:hasStartDate ?startDateOpt . }
    OPTIONAL { ?event kwgl-ont:hasEndDate   ?endDateOpt . }
  }
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?damageProperty ?damageValue
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType ?hazardType .

  FILTER (?hazardType IN (kwgl-ont:hurricane, kwgl-ont:tornado, kwgl-ont:stormSurgeTide))

  ?hazard kwgl-ont:hasStartDate ?startDate ;
          kwgl-ont:hasEndDate   ?endDate .

  FILTER (?startDate >= "2020-01-01"^^xsd:date && ?endDate <= "2022-12-31"^^xsd:date)

  ?hazard kwgl-ont:hasImpacted ?place .

  OPTIONAL { 
    BIND (IF(BOUND(?d2021), ?d2021,
             IF(BOUND(?d2020), ?d2020,
                 IF(BOUND(?d2019), ?d2019, ?damageValue))) AS ?damageValue)

    VALUES ?damageProperty {
      kwgl-ont:dollarDamageOfHurricanesImpactingPlace
      kwgl-ont:dollarDamageOfTornadoesImpactingPlace
      kwgl-ont:dollarDamageOfStormSurgesImpactingPlace
    }

    OPTIONAL { ?place ?damageProperty ?d2022 . BIND(?d2022 AS ?d2021) }
    OPTIONAL { ?place ?damageProperty ?d2021 . BIND(?d2021 AS ?d2020) }
    OPTIONAL { ?place ?damageProperty ?d2020 . BIND(?d2020 AS ?d2019) }
    OPTIONAL { ?place ?damageProperty ?d2019 }
  }
}
ORDER BY ?place

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?hazard ?temporalScope ?property ?value
WHERE {
  ?hazard a kwg-ont:Hazard .
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?temporalScope . }
  OPTIONAL { ?hazard ?property ?value . }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?place ?name
WHERE {
  ?place a kwg-ont:AdministrativeRegion ;
         rdfs:label ?name .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?place ?concern ?attribute
WHERE {
  ?place a kwg-ont:Hazard .
  OPTIONAL { ?place a ?concern . }
  OPTIONAL { ?place ?attribute ?value . }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?place ?attribute ?value
WHERE {
  ?place a kwg-ont:AdministrativeRegion .
  ?obs a kwg-ont:CensusACS5YearEstimatesObservation ;
       sosa:hasFeatureOfInterest ?place ;
       sosa:observedProperty ?attribute .
  OPTIONAL { ?obs sosa:hasSimpleResult ?value . }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?hazardType (COUNT(DISTINCT ?hazard) AS ?count)
WHERE {
  ?hazard a kwg-ont:Hazard .
  OPTIONAL { ?hazard rdfs:subClassOf* ?hazardType . }
  FILTER (!isBLANK(?hazardType))
}
GROUP BY ?hazardType

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?tornadoAttribute (COUNT(DISTINCT ?place) AS ?count)
WHERE {
  ?hazard a kwg-ont:NOAATornado ;
          kwg-ont:hasTemporalScope ?time ;
          kwg-ont:spatialRelation ?place .
  ?place a kwg-ont:AdministrativeRegion .
  OPTIONAL { ?hazard ?tornadoAttribute ?value . }
}
GROUP BY ?tornadoAttribute

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?hazardType ?property ?value
WHERE {
  ?hazardType a kwg-ont:NOAAHazardEvent .
  OPTIONAL { 
    ?observation sosa:hasFeatureOfInterest ?hazardType ;
                 sosa:observedProperty ?property ;
                 sosa:hasSimpleResult ?value .
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?hazardType ?property ?value
WHERE {
  ?hazardType a kwg-ont:NOAAHazardEvent ;
              rdfs:subClassOf+ kwg-ont:NOAAFlood .   # flood-specific hazards
  OPTIONAL { ?hazardType ?property ?value . }       # retrieve any available details (properties and values)
}

PREFIX qudt: <http://qudt.org/1.1/schema/qudt#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?place ?property ?value
WHERE {
  ?place a kwg-ont:AdministrativeRegion .
  ?result a kwg-ont:ClimateDivisionObservationResult ;
          sosa:hasFeatureOfInterest ?place ;
          kwg-ont:mean|kwg-ont:value ?quantity .
  ?quantity a kwg-ont:Quantity ;
            qudt:value ?value ;
            qudt:unit ?unit .
  BIND (kwg-ont:ClimateObservableProperty AS ?property)
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?hazardType ?superType ?property ?value
WHERE {
  ?hazardType a kwg-ont:Hazard .
  OPTIONAL { ?hazardType rdfs:subClassOf ?superType . }
  OPTIONAL { ?hazardType ?property ?value . }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?hazardEvent ?impactProperty ?impactValue
WHERE {
  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:hasFeatureOfInterest ?hazardEvent ;
                     sosa:observedProperty ?impactProperty ;
                     sosa:hasSimpleResult ?impactValue .
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?impactDetail
WHERE {
  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:hasFeatureOfInterest ?hazard .
  FILTER ( ?hazard a kwg-ont:Hazard )
  OPTIONAL { ?impactObservation sosa:hasSimpleResult ?impactDetail . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hazard ?attribute ?impactDetail ?temporalData
WHERE {
  # Hurricane-specific hazard (NOAAHazardEvent sub‑class)
  ?hazard a kwg-ont:NOAAHurricane ;
          geo:hasGeometry|geo:hasDefaultGeometry ?geom .   # ensure it is related to a geographical place

  # Hazard attributes that are observable properties
  ?hazard sosa:observedProperty ?attribute .

  # Damage impact details and optional temporal information
  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:hasFeatureOfInterest ?hazard ;
                     sosa:observedProperty ?impactAttribute ;
                     sosa:hasSimpleResult ?impactDetail .

  OPTIONAL {
    ?impactObservation sosa:phenomenonTime ?temporalData .
    FILTER (isIRI(?temporalData) && ?temporalData != "")
  }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?impactProperty ?impactValue
WHERE {
  ?hazard a kwg-ont:NOAATornado ;
          kwg-ont:hasTemporalScope ?temporalExtent .

  OPTIONAL { ?hazard geo:hasGeometry ?geometry . }

  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:hasFeatureOfInterest ?hazard ;
                     sosa:observedProperty ?impactProperty ;
                     sosa:hasSimpleResult ?impactValue .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?impact ?property ?value
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          kwg-ont:hasTemporalScope ?temporalExtent .

  FILTER ( ?temporalExtent >= _:START_TIME && ?temporalExtent <= _:END_TIME )

  ?hazard geo:hasGeometry ?geometry .
  ?geometry geo:asWKT ?wkt .   # ensures a geographical place is involved

  ?impact a kwg-ont:ImpactObservation ;
          sosa:hasFeatureOfInterest ?hazard ;
          sosa:observedProperty ?property ;
          sosa:hasSimpleResult ?value .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?details ?when
WHERE {
  ?hazard a kwg-ont:Hazard .
  OPTIONAL { ?hazard geo:hasGeometry ?geometry . }
  OPTIONAL { ?hazard geo:hasDefaultGeometry ?defaultGeometry . }
  OPTIONAL { ?hazard kwg-ont:spatialRelation ?spatialRelation . }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?temporalScope . }

  BIND(COALESCE(
         STR(?geometry), 
         STR(?defaultGeometry),
         STR(?spatialRelation),
         STR(?temporalScope)
       ) AS ?details)

  ?hazard kwg-ont:hasTemporalScope ?ts .
  BIND(time:inXSDDateTimeStamp(?ts) AS ?when)
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?place ?name
WHERE {
  ?place a geo:SpatialObject ;
         rdfs:label ?name .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?place ?property ?value
WHERE {
  ?place a kwg-ont:AdministrativeRegion ;
         kwg-ont:spatialRelation ?cell .
  ?obs a kwg-ont:PublicHealthObservation ;
       sosa:hasFeatureOfInterest ?place ;
       sosa:observedProperty ?property ;
       sosa:hasSimpleResult ?value .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>

SELECT ?place ?attribute ?value
WHERE {
  ?obs a kwg-ont:CensusACS5YearEstimatesObservation ;
       sosa:hasFeatureOfInterest ?place ;
       sosa:observedProperty ?observableProp ;
       sosa:hasSimpleResult ?value .

  VALUES ?observableProp {
    kwgr:censusObservableProperty.totalPopulation
    kwgr:censusObservableProperty.malePopulation
    kwgr:censusObservableProperty.femalePopulation
    kwgr:censusObservableProperty.householdUnits
  }

  BIND (strafter(str(?observableProp), "#") AS ?attribute)
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?hazard (COUNT(?hazard) AS ?count)
WHERE {
  ?hazard a kwg-ont:Hazard ;
          a kwg-ont:Earthquake .
} GROUP BY ?hazard

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT DISTINCT ?attribute (COUNT(DISTINCT ?hazard) AS ?count)
WHERE {
  ?hazard a kwg-ont:NOAATornado ;
          sosa:observedProperty ?attribute .
}
GROUP BY ?attribute

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
SELECT DISTINCT ?hazardEvent ?observableProperty ?propertyLabel
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
               geo:hasGeometry ?geometry .  # ensure it is a geographical place
  ?observation sosa:hasFeatureOfInterest ?hazardEvent ;
               sosa:observedProperty ?observableProperty .
  FILTER ( ?observableProperty IN (
    kwg-ont:StormTrackletObservableProperty,
    kwg-ont:StormTrackObservableProperty ) )
  OPTIONAL { ?observableProperty rdfs:label ?propertyLabel }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT DISTINCT ?hazardEvent ?observableProperty ?propertyValue
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
               a kwg-ont:Flood .  # Flood-specific hazard events
  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:hasFeatureOfInterest ?hazardEvent ;
                     sosa:observedProperty ?observableProperty .
  ?impactObservation sosa:hasSimpleResult ?propertyValue .
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?hazard ?type ?detail
WHERE {
  ?hazard a kwg-ont:Hazard .
  OPTIONAL { ?hazard geo:hasGeometry ?geometry . BIND(?geometry AS ?detail) }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?temporalScope . BIND(?temporalScope AS ?detail) }
  OPTIONAL { ?hazard rdfs:label ?label . BIND(?label AS ?detail) }
  SERVICE {
    SELECT ?type WHERE {
      VALUES ?type {
        kwg-ont:Earthquake
        kwg-ont:NOAAHazardEvent   # other specific hazard types can be added here if needed
      }
      ?hazard a ?type .
    }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?hazardEvent ?impactProperty ?impactValue
WHERE {
  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:hasFeatureOfInterest ?hazardEvent ;
                     sosa:observedProperty ?impactProperty ;
                     sosa:hasSimpleResult ?impactValue .
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?damageDetail
WHERE {
  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:hasSimpleResult ?damageDetail ;
                     sosa:hasFeatureOfInterest ?hazard .
  ?hazard a kwg-ont:Hazard .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?doiValue
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:hasIdentifier ?doi .
  ?doi a coresr-ont:DOI ;
       coresr-ont:doiAsString ?doiValue .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?university ?city
WHERE {
  ?university coresr-ont:locatedAt ?location .
  ?location coresr-ont:inCity ?city .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author ?advisor
WHERE {
  ?author coresr-ont:advisedBy ?advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?pubType
WHERE {
  ?publication coresr-ont:hasPublicationType ?type .
  ?type coresr-ont:typeAsString ?pubType .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?agent ?department
WHERE {
  ?agent coresr-ont:associatedWith ?department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?fieldOfStudy
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication
WHERE {
  ?publication a coresr-ont:Publication .
  ?pubContribution1 coresr-ont:contributedTo ?publication ;
                   a coresr-ont:Contributor ;
                   coresr-ont:associatedWith ?dept1 .
  ?pubContribution2 coresr-ont:contributedTo ?publication ;
                   a coresr-ont:Contributor ;
                   coresr-ont:associatedWith ?dept2 .
  FILTER (?dept1 != ?dept2)
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?author ?field
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .  # author has an advisor
  ?pub a coresr-ont:Publication ;
       coresr-ont:submittedBy ?author ;
       coresr-ont:associatedFieldOfStudy ?field .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department (COUNT(*) AS ?missingFamilyNameCount)
WHERE {
  ?agent coresr-ont:associatedWith ?department .
  OPTIONAL { ?agent coresr-ont:hasContactInformation [ a coresr-ont:FamilyName ] } 
  FILTER (!BOUND(?familyName))
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?property ?value
WHERE {
  ?hazard a kwg-ont:Hazard .
  OPTIONAL { ?hazard ?property ?value . }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?place ?name
WHERE {
  ?place a kwg-ont:AdministrativeRegion .
  OPTIONAL { ?place rdfs:label ?name . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?place ?hazardType ?property ?value
WHERE {
  # All geographical places (AdministrativeRegion)
  ?place a kwg-ont:AdministrativeRegion .

  # Health-related concerns or attributes that affect these places
  OPTIONAL { 
    ?hazard a kwg-ont:Hazard ;
           sosa:hasFeatureOfInterest ?place ;
           a ?hazardType .   # capture the specific hazard type (e.g., DroughtZone, Earthquake)
  }

  # Any additional properties/values describing the health-related concern
  OPTIONAL { 
    ?hazard ?property ?value .
  }
}

ORDER BY ?place ?hazardType

PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT DISTINCT ?place ?property ?value
WHERE {
  ?place a kwg-ont:AdministrativeRegion .
  ?obs a sosa:Observation ;
       sosa:hasFeatureOfInterest ?place ;
       sosa:observedProperty ?property ;
       sosa:hasSimpleResult ?value .
  FILTER ( ?property IN (
    kwgr:censusObservableProperty.totalPopulation,
    kwgr:censusObservableProperty.malePopulation,
    kwgr:censusObservableProperty.femalePopulation,
    kwgr:censusObservableProperty.householdUnits
  ))
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT COUNT(DISTINCT ?earthquake) ?earthquake
WHERE {
  ?earthquake a kwg-ont:Earthquake .
} GROUP BY ?earthquake

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?attribute (COUNT(DISTINCT ?hazard) AS ?count)
WHERE {
  ?hazard a kwg-ont:NOAATornado ;
          ?property ?value .
  BIND (?property AS ?attribute)
}
GROUP BY ?attribute

PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazardType ?property ?value
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          a/skos:broader* kwg-ont:StormTrack .   # restrict to storm-specific hazards (those that are sub‑classes of StormTrack)

  OPTIONAL { 
    ?obs sosa:hasFeatureOfInterest ?hazard ;
         sosa:observedProperty ?property ;
         sosa:resultTime ?time .

    FILTER NOT EXISTS {
      ?obs2 sosa:hasFeatureOfInterest ?hazard ;
            sosa:observedProperty ?property ;
            sosa:resultTime ?laterTime .
      FILTER (?laterTime > ?time)
    }   # keep only the most recent observation per property

    BIND(?obs as ?selectedObs)
    OPTIONAL { ?selectedObs sosa:hasSimpleResult ?value }
  }

  BIND(xsd:string(str(?hazard)) AS ?hazardType)
}

PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazardType ?property ?value
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          a/skos:broader* kwg-ont:Flood .

  OPTIONAL { 
    ?obs sosa:hasFeatureOfInterest ?hazard ;
         sosa:observedProperty ?property ;
         sosa:hasSimpleResult ?value .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT DISTINCT ?place ?property ?value
WHERE {
  ?observation a sosa:Observation ;
               sosa:observedProperty ?property ;
               sosa:resultTime ?time .

  OPTIONAL { ?observation sosa:hasSimpleResult ?value . }

  FILTER EXISTS {
    ?feature a kwg-ont:Region ;
             sosa:isFeatureOfInterestOf ?observation .
  }
  BIND(?feature AS ?place)
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?hazard ?type ?property ?value
WHERE {
  ?hazard a kwg-ont:Earthquake .
  OPTIONAL { ?hazard rdfs:subClassOf ?type . }
  OPTIONAL { ?hazard ?property ?value . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?hazardEvent ?impactProperty ?impactValue
WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?hazardEvent ;
       sosa:observedProperty ?impactProperty ;
       sosa:hasSimpleResult ?impactValue .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?impactObservation ?property ?value
WHERE {
  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:hasFeatureOfInterest ?hazard .
  FILTER (?hazard a kwg-ont:Hazard)
  OPTIONAL { 
    ?impactObservation ?property ?value .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?property ?value ?impactProperty ?impactValue ?temp
WHERE {
  # Hurricane-specific hazard and its attributes related to a geographical place
  ?hazard a kwg-ont:NOAAHurricane ;
          geo:hasDefaultGeometry|geo:hasGeometry ?geom .
  OPTIONAL { ?hazard ?property ?value . }

  # Damage impact details and their temporal data if available
  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:hasFeatureOfInterest ?hazard ;
                     sosa:observedProperty ?impactProperty ;
                     sosa:hasSimpleResult ?impactValue .
  OPTIONAL { ?impactObservation sosa:phenomenonTime ?temp . }
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?property ?value
WHERE {
  ?hazard a kwg-ont:NOAATornado ;
          sosa:hasSimpleResult ?value .

  OPTIONAL { 
    ?hazard ?property ?value .   # capture any additional property-value pairs describing the tornado damage details
  }

  FILTER EXISTS {
    ?hazard geo:hasGeometry ?geom .
    ?hazard kwg-ont:hasTemporalScope ?ts .

    # Ensure the hazard is related to a geographical place (via geometry) and falls within the given temporal extent
    FILTER(?ts >= "2023-01-01T00:00:00"^^xsd:dateTime && ?ts <= "2024-12-31T23:59:59"^^xsd:dateTime)
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?detail ?when
WHERE {
  { ?hazard a kwg-ont:FEMADisaster . }
  UNION
  { ?hazard a kwg-ont:HazardEpisode . }
  UNION
  { ?hazard a kwg-ont:Earthquake . }
  UNION
  { ?hazard a kwg-ont:NOAAHazardEvent . }
  UNION
  { ?hazard a kwg-ont:DroughtZone . }
  UNION
  { ?hazard a kwg-ont:StormTrack . }
  UNION
  { ?hazard a kwg-ont:SmokePlumeSnapshot . }

  OPTIONAL {
    # Details via subclass-specific properties or generic property-value pairs
    { ?hazard ?detailPredicate ?detailValue .
      FILTER NOT EXISTS { ?detailPredicate = rdf:type } }
    BIND (CONCAT(STR(?detailPredicate), " : ", STR(?detailValue)) AS ?detail)
  }

  OPTIONAL {
    # Temporal information via startsFrom, endsAt, hasTemporalScope, or time:inXSD* properties
    { ?hazard kwg-ont:startsFrom ?fix . 
      ?fix geo:hasDefaultGeometry/geo:asWKT ?when } .
    UNION
    { ?hazard kwg-ont:endsAt ?fix . 
      ?fix geo:hasDefaultGeometry/geo:asWKT ?when } .
    UNION
    { ?hazard kwg-ont:hasTemporalScope ?temporalEntity .
      OPTIONAL { ?temporalEntity time:inXSDDateTime ?when } }
  }
}

PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?place ?name
WHERE {
  ?place a (gnis:County gnis:State usgs:Area usgs:Airport usgs:Arch usgs:Arroyo usgs:Basin usgs:Bay usgs:Beach usgs:Bench usgs:Bend usgs:Bridge usgs:Building usgs:BuiltUpArea usgs:Canal usgs:Cape usgs:Cemetery usgs:Census usgs:Channel usgs:Church usgs:CivilGovernment usgs:Cliff usgs:Crater usgs:Crossing usgs:Dam usgs:Division usgs:EcologicalRegime usgs:Embankment usgs:Feature usgs:Flat usgs:Forest usgs:Gap usgs:Glacier usgs:Gut usgs:Harbor usgs:Hospital usgs:Island usgs:Isthmus usgs:Lake usgs:Lava usgs:Levee usgs:Locale usgs:Military usgs:Mine usgs:MountainRange usgs:Ocean usgs:OilField usgs:Park usgs:Plain usgs:PopulatedPlace usgs:PostOffice usgs:Rapids usgs:Reserve usgs:Reservoir usgs:Ridge usgs:Rock usgs:School usgs:Sea usgs:Slope usgs:Spring usgs:Stream usgs:Summit usgs:SurfaceWater usgs:Swamp usgs:Terrain usgs:Tower usgs:Trail usgs:Tunnel usgs:Unknown usgs:Valley usgs:Waterfall usgs:Well usgs:Woodland) ;
         rdfs:label ?name .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?property ?value
WHERE {
  ?place a kwg-ont:HealthCareFacility ;
         geo:hasGeometry ?geom .

  OPTIONAL { ?place kwg-ont:hospitalStatus ?property . BIND(?place AS ?value) }
  OPTIONAL { ?place kwg-ont:hospitalType   ?property . BIND(?place AS ?value) }
  OPTIONAL { ?place kwg-ont:helipadAvailability ?property . BIND(?place AS ?value) }
  OPTIONAL { ?place kwg-ont:noHospitalBeds    ?property . BIND(?place AS ?value) }
  OPTIONAL { ?place kwg-ont:hospitalAddress   ?property . BIND(?place AS ?value) }
  OPTIONAL { ?place kwg-ont:hospitalName      ?property . BIND(?place AS ?value) }
  OPTIONAL { ?place kwg-ont:website           ?property . BIND(?place AS ?value) }
  OPTIONAL { ?place kwg-ont:telephoneNo       ?property . BIND(?place AS ?value) }
  OPTIONAL { ?place kwg-ont:zipCode           ?property . BIND(?place AS ?value) }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?attributeType ?value
WHERE {
  # Identify all geographical places (administrative regions or S2 cells)
  { ?place a kwg-ont:AdministrativeRegion }
  UNION
  { ?place a kwg-ont:S2Cell }

  # Retrieve demographic attributes and their values for each place
  OPTIONAL { 
    ?place ?attributeType ?value .
    FILTER (
      ?attributeType IN (
        kwg-ont:censusGeographyTime,          # time-related census geography info (if needed)
        kwg-ont:hasTemporalScope               # temporal scope of the demographic data
      )
    )
  }
}
ORDER BY ?place ?attributeType

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT COUNT(DISTINCT ?earthquake) {
  ?earthquake a kwg-ont:Earthquake .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?property (COUNT(DISTINCT ?hazard) AS ?count)
WHERE {
  ?hazard a kwg-ont:NOAATornado ;
          ?property ?value .
}
GROUP BY ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hazardType ?property ?value
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          rdfs:subClassOf+ ?hazardType .

  OPTIONAL { 
    ?hazard ?property ?value . 
    FILTER (regex(str(?property), "kwg-ont:") || regex(str(?property), "geo:"))
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hazardType ?property ?value
WHERE {
  ?hazard a kwg-ont:Flood ;
          rdfs:subClassOf* ?hazardType .

  OPTIONAL { ?hazard ?property ?value . }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?hazard ?type ?property ?value
WHERE {
  ?hazard a kwg-ont:Earthquake .

  # Retrieve the direct type (kwg-ont:Earthquake) and any super‑types via rdfs:subClassOf
  { 
    BIND(kwg-ont:Earthquake AS ?type)
  }
  UNION
  {
    ?hazard rdfs:subClassOf ?type .
  }

  # Collect all available property/value pairs for the hazard instance
  OPTIONAL { ?hazard ?property ?value . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?event ?impactProperty ?impactValue
WHERE {
  ?event a kwg-ont:NOAAHazardEvent ;
         sosa:hasMember ?impactObservation .
  ?impactObservation a sosa:Observation ;
                     sosa:observedProperty ?impactProperty ;
                     sosa:result ?result .
  OPTIONAL { ?result kwg-ont:value ?impactValue . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?damageDetail
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
               kwg-ont:affectedByInverse ?hazard .
  ?impactObservation a sosa:Observation ;
                     sosa:observedProperty ?damageProp ;
                     sosa:resultTime ?time ;
                     sosa:hasFeatureOfInterest ?hazardEvent .
  BIND(?impactObservation AS ?damageDetail)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?attribute ?damageImpact ?temporalData
WHERE {
  # Hurricane-specific hazard instances linked to a geographical place
  ?hazard a kwg-ont:NOAAHazardEvent ;
          rdfs:subClassOf+ <https://undrr.org/hazard/hip/MetereologicalAndHydrological> ;
          kwg-ont:sfWithin|kwg-ont:spatialRelation ?place .

  # Hazard-specific attributes (e.g., magnitude, category)
  OPTIONAL {
    ?hazard ?attributePredicate ?attributeValue .
    BIND (str(?attributePredicate) AS ?attribute)
    BIND (str(?attributeValue) AS ?attributeValueStr)
  }

  # Damage impact details related to the same hazard
  OPTIONAL {
    ?impact a kwg-ont:ImpactObservation ;
            sosa:observedProperty ?damageProp ;
            sosa:resultTime|time:inXSDDateTime ?temporalData .
    BIND (str(?damageProp) AS ?damageImpact)
    BIND (COALESCE(str(?temporalData), "") AS ?temporalDataStr)
  }
}
ORDER BY ?hazard ?attribute ?damageImpact

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?damageDetail
WHERE {
  ?tornado rdf:type kwg-ont:NOAATornado ;
           rdfs:label ?damageLabel .

  OPTIONAL { ?tornado kwg-ont:hasTemporalScope ?temporalExtent . }
  FILTER (BOUND(?temporalExtent))

  OPTIONAL { 
    ?tornado kwg-ont:affectedByInverse ?place .
    ?place a geo:SpatialObject ;
           rdfs:label ?placeLabel .
  }
  FILTER (BOUND(?place))

  BIND(CONCAT('Tornado ', ?damageLabel, ' affecting ', ?placeLabel, ' from ', STR(?temporalExtent)) AS ?damageDetail)
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazardEvent ?damageProperty ?damageCrop
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
               kwg-ont:hasTemporalScope ?temporalExtent .

  FILTER ( ?temporalExtent >= "2020-01-01"^^xsd:date && ?temporalExtent <= "2023-12-31"^^xsd:date )

  OPTIONAL {
    ?impactObservation a kwg-ont:ImpactObservation ;
                       sosa:observedProperty ?damagePropPred .
    FILTER (?damagePropPred = kwg-ont:impactObservableProperty.damageProperty)
    ?impactObservation sosa:result ?damageProperty .
  }

  OPTIONAL {
    ?impactObservation2 a kwg-ont:ImpactObservation ;
                        sosa:observedProperty ?damageCropPred .
    FILTER (?damageCropPred = kwg-ont:impactObservableProperty.damageCrop)
    ?impactObservation2 sosa:result ?damageCrop .
  }

  # Ensure the hazard event is related to a geographical place
  {
    ?hazardEvent geo:hasGeometry ?geom .
    BIND(bound(?geom) AS ?isGeolocated)
  } UNION {
    ?hazardEvent kwg-ont:sfWithin ?place .
    FILTER NOT EXISTS { ?place a kwg-ont:S2Cell }
  }

  FILTER (?isGeolocated || bound(?place))
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
