SELECT ?fieldOfStudy ?publication
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?city ?college
WHERE {
  ?univ a coress-ont:University ;
        coress-ont:atCity ?city ;
        coress-ont:hasCollege ?college .
  ?college a coress-ont:College .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?state ?university
WHERE {
  # Count publications per university (via agents in departments)
  SELECT ?u (COUNT(DISTINCT ?pub) AS ?pubCount)
  WHERE {
    ?dep a coress-ont:Department ;
         coress-ont:departmentOf ?college .
    ?college a coress-ont:College ;
             coress-ont:collegeOf ?u .
    ?agent a coress-ont:Agent ;
           coress-ont:worksInDepartment ?dep ;
           coress-ont:performsRole ?authorRole .
    ?authorRole a coress-ont:Author ;
                coress-ont:submits ?pub .
    ?pub a coress-ont:Publication .
  }
  GROUP BY ?u

  # Associate each university with its state
  {
    SELECT ?u ?state
    WHERE { ?u a coress-ont:University ; coress-ont:atState ?state . }
  }

  # Bind the publication count to the university‑state pair
  BIND(?pubCount AS ?cnt)

  # Keep only the universities with the maximum count per state
  {
    SELECT ?state (MAX(?cnt) AS ?maxCnt)
    WHERE { BIND(?cnt AS ?cnt) }   # reuse the same variable from outer query
  }
  FILTER (?cnt = ?maxCnt)
}
ORDER BY ?state

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication
WHERE {
  ?pub a coress-ont:Publication .
  SELECT ?pub (COUNT(DISTINCT ?dept) AS ?deptCount)
  WHERE {
    ?author a coress-ont:Author ;
            coress-ont:submits ?pub .
    ?author coress-ont:isPerformedBy ?agent .
    ?agent coress-ont:worksInDepartment ?dept .
  }
  GROUP BY ?pub
  HAVING (?deptCount > 1)
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?pubType (AVG(?diffDays) AS ?avgDiff)
WHERE {
  ?pub a coress-ont:Publication ;
       coress-ont:dateOfSubmission ?subDate ;
       coress-ont:dateOfPublication ?pubDate ;
       coress-ont:hasPublicationType ?pubType .
  FILTER (BOUND(?subDate) && BOUND(?pubDate))
  BIND (daysAfterYearMonthDay(?pubDate) - daysAfterYearMonthDay(?subDate) AS ?diffDays)
}
ORDER BY DESC(?avgDiff)
LIMIT 1

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT DISTINCT ?author ?fieldOfStudy
WHERE {
  ?author a coress-ont:Author ;
          coress-ont:advisedBy ?advisor .  # ensures the author has an advisor
  ?pub a coress-ont:Publication ;
       coress-ont:submittedBy ?author ;
       coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department (?cnt AS ?missingFamilyNameCount)
WHERE {
  SELECT ?department (COUNT(*) AS ?cnt)
  WHERE {
    ?agent a coress-ont:Agent ;
           coress-ont:worksInDepartment ?department .
    FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName }
  }
  GROUP BY ?department
}
ORDER BY DESC(?cnt)

