PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?pubCount)
WHERE {
  ?university a coresr-ont:University ;
              coresr-ont:locatedAt ?loc .
  ?loc coresr-ont:atState ?state .

  ?author a coresr-ont:Author ;
          coresr-ont:associatedWith ?department .
  ?department a coresr-ont:Department ;
              coresr-ont:partOf/coresr-ont:hasPart* ?university . 

  ?publication a coresr-ont:Publication ;
               coresr-ont:submittedBy ?author .
}
GROUP BY ?state ?university
ORDER BY ?state DESC(?pubCount)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:submittedBy ?author .
  BIND(coresr-ont:associatedWith AS ?deptProp)
  FILTER EXISTS {
    ?author ?deptProp ?dept1 .
    ?otherAuthor ?deptProp ?dept2 .
    FILTER(?dept1 != ?dept2 && ?otherAuthor != ?author)
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?pubType (AVG(?diff) AS ?avgDays)
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:dateOfSubmission ?submissionDate ;
               coresr-ont:dateOfPublication ?pubDate ;
               coresr-ont:hasPublicationType ?pubType .
  FILTER (BOUND(?submissionDate) && BOUND(?pubDate))
  BIND ((xsddate(?pubDate) - xsddate(?submissionDate)) / 86400000 AS ?diff)
}
ORDER BY DESC(?avgDays)
LIMIT 1

