PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?state ?university
WHERE {
  # Count publications per university and rank universities within each state
  {
    SELECT ?state (COUNT(DISTINCT ?publication) AS ?pubCount)
    WHERE {
      ?university a coresr-ont:University ;
                  coresr-ont:locatedAt ?location .
      ?location coresr-ont:atState ?state .
      # Publications can be directly associated with the university or via its colleges/departments
      { 
        ?publication a coresr-ont:Publication ;
                     coresr-ont:submittedBy/coresr-ont:performsRole/^coresr-ont:associatedWith ?dept . 
        ?dept a coresr-ont:Department ; coresr-ont:partOf+ ?university .
      }
      UNION
      {
        ?publication a coresr-ont:Publication ;
                     coresr-ont:submittedBy/coresr-ont:performsRole/^coresr-ont:hasAssociatedAgent ?agent . 
        ?agent a coresr-ont:Agent ; coresr-ont:associatedWith ?dept .
        ?dept a coresr-ont:Department ; coresr-ont:partOf+ ?university .
      }
    }
    GROUP BY ?state
  } ORDER BY DESC(?pubCount) LIMIT 1

  # Retrieve the university (or universities in case of tie) with that max count for each state
  {
    SELECT ?state ?university (COUNT(DISTINCT ?publication) AS ?pubCount)
    WHERE {
      ?university a coresr-ont:University ;
                  coresr-ont:locatedAt ?location .
      ?location coresr-ont:atState ?state .
      { 
        ?publication a coresr-ont:Publication ;
                     coresr-ont:submittedBy/coresr-ont:performsRole/^coresr-ont:associatedWith ?dept . 
        ?dept a coresr-ont:Department ; coresr-ont:partOf+ ?university .
      }
      UNION
      {
        ?publication a coresr-ont:Publication ;
                     coresr-ont:submittedBy/coresr-ont:performsRole/^coresr-ont:hasAssociatedAgent ?agent . 
        ?agent a coresr-ont:Agent ; coresr-ont:associatedWith ?dept .
        ?dept a coresr-ont:Department ; coresr-ont:partOf+ ?university .
      }
    }
    GROUP BY ?state ?university
  } ORDER BY DESC(?pubCount) LIMIT 1
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?pub WHERE {
  ?pub a coresr-ont:Publication .
  SELECT (COUNT(DISTINCT ?dept) AS ?cnt)
  WHERE {
    ?contrib coresr-ont:contributedTo ?pub ;
             coresr-ont:isPerformedBy ?agent .
    ?agent coresr-ont:associatedWith ?dept .
  }
  HAVING (?cnt > 1)
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?pubType (AVG(?diffDays) AS ?avgDiff)
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:dateOfSubmission ?submissionDate ;
       coresr-ont:dateOfPublication ?publicationDate ;
       coresr-ont:hasPublicationType ?pt .

  BIND(DAYs(?publicationDate) - DAYs(?submissionDate) AS ?diffDays)

  ?pt a coresr-ont:PublicationType ;
      coresr-ont:typeAsString ?pubType .
}
GROUP BY ?pubType
ORDER BY DESC(?avgDiff)
LIMIT 1

