WHERE {
  ?author a coress-ont:Author .
  FILTER EXISTS { ?author coress-ont:advisedBy ?advisor } .

  SELECT DISTINCT ?a
  WHERE {
    ?pub a coress-ont:Publication ;
         coress-ont:submittedBy ?a ;
         coress-ont:associatedFieldOfStudy ?field .
  }
  GROUP BY ?a
}

