PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication
WHERE {
  ?pub a coress-ont:Publication .
  ?pub coress-ont:submittedBy ?author1 .
  ?author1 coress-ont:worksInDepartment ?dept1 .

  MINUS {
    ?pub coress-ont:submittedBy ?author2 .
    ?author2 coress-ont:worksInDepartment ?dept1
  }

  FILTER (EXISTS {
    ?pub coress-ont:submittedBy ?author3 .
    ?author3 coress-ont:worksInDepartment ?dept2
    FILTER (?dept2 != ?dept1)
  })
}

