       coress-ont:hasPublicationType ?pubType .
  FILTER (BOUND(?submissionDate) && BOUND(?publicationDate))
  BIND ((xsd:dateTime(?publicationDate) - xsd:dateTime(?submissionDate)) / ^xsdduration:"P1D"^^xsd:dayTimeDuration AS ?diff)
}
GROUP BY ?pubType
ORDER BY DESC(?avgDays)
