PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
SELECT ?hazard ?property ?value (COALESCE(?time,?temporalScope) AS ?when)
WHERE {
  { ?hazard a kwg-ont:NOAAHazardEvent . }
  UNION
  { ?hazard a kwg-ont:Earthquake . }
  UNION
  { ?hazard a kwg-ont:DroughtZone . }
  UNION
  { ?hazard a kwg-ont:Fire . }
  UNION
  { ?hazard a kwg-ont:NIFCFire . }
  UNION
  { ?hazard a kwg-ont:MTBSFire . }
  UNION
  { ?hazard a kwg-ont:SmokePlumeSnapshot . }

  OPTIONAL {
    { ?hazard time:hasTime ?time } 
    UNION 
    { ?hazard kwg-ont:hasTemporalScope ?temporalScope }
  }

  OPTIONAL { 
    ?obs a sosa:Observation ;
         sosa:observedProperty ?property ;
         sosa:result ?value .
    {
      SELECT DISTINCT * WHERE {
        { ?obs sosa:hasFeatureOfInterest ?hazard . }
        UNION
        { ?obs sosa:phenomenonTime ?when . FILTER (isIRI(?when)) }
      }
    }
  }

  OPTIONAL {
    ?hazard ?property ?value .
    FILTER (?property != rdf:type)
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?place ?name
WHERE {
  ?place a geo:SpatialObject ;
         rdfs:label ?name .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?place ?hazard ?property ?value
WHERE {
  ?place a geo:SpatialObject .

  OPTIONAL { 
    ?hazard a kwg-ont:Hazard ;
           sosa:isFeatureOfInterestOf ?observation .
    ?observation sosa:hasFeatureOfInterest ?place ;
                 sosa:observedProperty ?property ;
                 sosa:result ?value .
  }

  UNION

  {
    ?health a kwg-ont:HealthCareFacility ;
            sosa:isFeatureOfInterestOf ?healthObs .
    ?healthObs sosa:hasFeatureOfInterest ?place ;
               sosa:observedProperty ?property ;
               sosa:result ?value .
  }

  UNION

  {
    ?pharm a kwg-ont:Pharmacy ;
           sosa:isFeatureOfInterestOf ?pharmObs .
    ?pharmObs sosa:hasFeatureOfInterest ?place ;
              sosa:observedProperty ?property ;
              sosa:result ?value .
  }

  UNION

  {
    ?publicHealth a kwg-ont:PublicHealthDepartment ;
                  sosa:isFeatureOfInterestOf ?pubHealthObs .
    ?pubHealthObs sosa:hasFeatureOfInterest ?place ;
                  sosa:observedProperty ?property ;
                  sosa:result ?value .
  }

  UNION

  {
    ?hosp a kwg-ont:Hospital ;
          sosa:isFeatureOfInterestOf ?hospitalObs .
    ?hospitalObs sosa:hasFeatureOfInterest ?place ;
                 sosa:observedProperty ?property ;
                 sosa:result ?value .
  }
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?place ?attribute ?value
WHERE {
  ?observation a kwg-ont:CensusACS5YearEstimatesObservation ;
               sosa:hasFeatureOfInterest ?place ;
               sosa:observedProperty ?attribute ;
               sosa:result ?value .
  ?place a geo:Feature .   # all geographical places are features in the schema
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT (COUNT(DISTINCT ?earthquake) AS ?count)
WHERE {
  ?earthquake a kwg-ont:Earthquake .
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?attribute (COUNT(?attr) AS ?count)
WHERE {
  ?tornadoEvent a kwg-ont:NOAAHazardEvent ;
                a kwg-ont:Tornado .
  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?tornadoEvent ;
       sosa:observedProperty ?attr .
  BIND(STRBEFORE(STR(?attr), "#") AS ?attribute)
}
GROUP BY ?attribute

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?hazardType ?prop ?value
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          rdfs:subClassOf* kwg-ont:Hazard .  # all hazard types (storm‑specific hazards are subclasses of NOAAHazardEvent)

  OPTIONAL {
    ?hazard ?prop ?value .
    FILTER (?prop IN (
      kwg-ont:StormTrackObservableProperty,
      kwg-ont:StormTrackletObservableProperty,
      sosa:observedProperty,          # generic observed property links
      geo:hasDefaultGeometry,        # geometry details of the hazard location
      kwg-ont:spatialRelation        # relation to administrative places
    ))
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?hazardType ?property ?value
WHERE {
  ?hazardInstance a kwg-ont:NOAAHazardEvent .
  OPTIONAL { ?hazardInstance a ?hazardType . }
  OPTIONAL { ?obs sosa:hasFeatureOfInterest ?hazardInstance ;
                sosa:observedProperty ?property ;
                sosa:resultValue ?value . }
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?place ?property
WHERE {
  ?place a geo:Feature .
  ?obs sosa:hasFeatureOfInterest ?place ;
       sosa:observedProperty ?property .
  FILTER (isIRI(?property) && CONTAINS(str(?property), "kwg-ont:ClimateObservableProperty"))
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?earthquake ?type ?property ?value
WHERE {
  ?earthquake a kwg-ont:Earthquake .
  OPTIONAL { ?earthquake rdfs:subClassOf ?type . }
  OPTIONAL { ?earthquake ?property ?value . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?hazardEvent ?impactProperty ?impactValue
WHERE {
  ?observation a kwg-ont:ImpactObservation ;
               sosa:observedProperty ?impactProperty ;
               sosa:resultValue ?impactValue ;
               sosa:hasFeatureOfInterest ?hazardEvent .
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?damageDetail
WHERE {
  ?impactObservation a kwg-ont:ImpactObservation ;
                     sosa:observedProperty ?observable .
  OPTIONAL { ?impactObservation sosa:result/kwg-ont:value ?value . }
  OPTIONAL { ?impactObservation kwg-ont:hasNarrative ?narrative . }

  BIND (CONCAT('Damage detail: ', STR(?observable), ' with value ', COALESCE(STR(?value), ''), ' and narrative "', COALESCE(STR(?narrative), ''), '"') AS ?damageDetail)

  FILTER EXISTS {
    ?hazard a kwg-ont:Hazard ;
            kwg-ont:affectedBy ?impactObservation .
  }
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
SELECT ?hazardType ?property ?value (COALESCE(?impactProperty,?temp) AS ?temporalData)
WHERE {
  # Hurricane-specific hazard types related to a geographical place
  ?hazard a kwg-ont:NOAAHazardEvent ;
          a [ rdf:type owl:Class ; 
              rdfs:subClassOf* kwg-ont:Hazard ;
              rdfs:label ?hazardType ] .
  FILTER(regex(str(?hazardType), "Hurricane", "i"))

  # Optional direct attributes of the hurricane hazard
  OPTIONAL {
    ?hazard ?property ?value .
  }

  # All damage impact details for that hurricane event and any available temporal data
  OPTIONAL {
    ?impactObservation a kwg-ont:ImpactObservation ;
                       sosa:hasFeatureOfInterest ?hazard ;
                       ?impactProperty ?impactValue .
    OPTIONAL { ?impactObservation sosa:phenomenonTime ?temp . }
  }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?place ?tempStart ?tempEnd
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;                # storm‑specific hazard (any NOAA hazard event)
           sosa:hasFeatureOfInterest ?f ;
           geo:hasDefaultGeometry ?geom .

  ?place a geo:SpatialObject ;                       # related geographical place
          geo:sfWithin ?geom .                      # the place is within the hazard's geometry

  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?temp }   # temporal extent of the hazard (if present)
  OPTIONAL {
    ?temp a time:Interval ;
          time:hasStartTime ?tempStart ;
          time:hasEndTime   ?tempEnd .
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?details ?time
WHERE {
  ?hazard a kwg-ont:Hazard ;
          rdfs:label ?details .

  OPTIONAL { 
    ?hazard kwg-ont:hasTemporalScope ?temporalScope .
    BIND(COALESCE(?temporalScope/time:inXSDDateTime, ?temporalScope/time:inXSDDate) AS ?time)
  }
}

PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
SELECT ?place ?name
WHERE {
  ?place a ( gn<http://www.w3.org/2004/02/skos/core#prefLabel> ?name .
}is:County | gnis:State ) ;

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?placeUri ?attributeUri ?value
WHERE {
  ?placeUri a kwg-ont:AdministrativeRegion ;
            geo:hasGeometry ?geom .

  # Retrieve population attribute
  OPTIONAL {
    ?placeUri kwg-ont:censusGeographyTime ?census .
    ?census kwg-ont:value ?popValue ;
            skos:prefLabel "population"^^xsd:string .
    BIND(?popValue AS ?value)
    BIND(kwg-ont:population AS ?attributeUri)
  }

  # Retrieve household units attribute
  OPTIONAL {
    ?placeUri kwg-ont:censusGeographyTime ?census2 .
    ?census2 kwg-ont:value ?hhValue ;
             skos:prefLabel "household units"^^xsd:string .
    BIND(?hhValue AS ?value)
    BIND(kwg-ont:householdUnits AS ?attributeUri)
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT COUNT(DISTINCT ?hazard) {
  ?hazard a kwg-ont:Earthquake .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT DISTINCT ?attr (COUNT(DISTINCT ?event) AS ?count)
WHERE {
  ?event a kwg-ont:NOAATornado ;
         sosa:hasSimpleResult ?res .
  ?res a kwg-ont:TornadoMagnitudeObservationCollection ;
       sosa:observedProperty ?attr .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazard ?attribute ?value
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          geo:hasGeometry ?geom .

  # Retrieve specific storm-related observable properties and their values
  OPTIONAL { ?hazard kwg-ont:magnitudeObservableProperty ?attribute ; sosa:resultTime ?time ; kwg-ont:magnitudeObservablePropertyValue ?value . }
  OPTIONAL { ?hazard kwg-ont:impactObservableProperty ?attribute ; sosa:resultTime ?time ; kwg-ont:impactObservablePropertyValue ?value . }

  # Include geometry for the geographical place
  BIND(geo:asWKT(?geom) AS ?wkt)
}
ORDER BY ?hazard

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?hazard ?attributeType ?attributeValue
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          kwg-ont:hasPart* ?eventSegment .

  # Magnitude attributes for floods (e.g., flood width, length)
  OPTIONAL { 
    ?eventSegment kwg-ont:magnitudeObservationCollection ?magColl .
    ?magColl sosa:hasMember ?magnitudeObs .
    ?magnitudeObs a sosa:MagnitudeObservation ;
                  sosa:observedProperty ?attributeType ;
                  sosa:hasSimpleResult ?attributeValue .
  }

  # Impact attributes (damage to property, crops, injuries, deaths)
  OPTIONAL {
    ?eventSegment kwg-ont:impactObservationCollection ?impColl .
    ?impColl sosa:hasMember ?impactObs .
    ?impactObs a sosa:ImpactObservation ;
               sosa:observedProperty ?attributeType ;
               sosa:hasSimpleResult ?attributeValue .
  }

  # Specific flood‑related observable properties
  FILTER (
    EXISTS {
      ?magnitudeObs sosa:observedProperty kwg-ont:magnitudeObservableProperty.width |
                    kwg-ont:magnitudeObservableProperty.length |
                    kwg-ont:magnitudeObservableProperty.estimateSustainedWidth .
    } ||
    EXISTS {
      ?impactObs sosa:observedProperty kwg-ont:impactObservableProperty.damageCrop |
                              kwg-ont:impactObservableProperty.damageProperty |
                              kwg-ont:impactObservableProperty.injuryDirect |
                              kwg-ont:impactObservableProperty.deathDirect .
    }
  )
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX qudt: <http://qudt.org/1.1/schema/qudt#>

SELECT DISTINCT ?placeUri ?propUri ?value
WHERE {
  ?placeUri a kwg-ont:USClimateDivision ;
            geo:hasGeometry ?geom .

  # Climate-specific attributes (observation results)
  ?obs a kwg-ont:ClimateObservation ;
       sosa:observedProperty ?propUri ;
       sosa:hasFeatureOfInterest ?placeUri ;
       sosa:hasResult ?result .

  ?result a qudt:QuantityValue ;
          qudt:value ?value .
}
ORDER BY ?placeUri ?propUri

PREFIX : <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?hazard ?property ?value
WHERE {
  ?hazard a :Earthquake ;
          ?property ?value .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?event ?propertyURI ?value
WHERE {
  ?event a kwg-ont:NOAAHazardEvent ;
         sosa:hasMember/sosa:observedProperty ?propertyURI ;
         sosa:hasMember/sosa:hasSimpleResult ?value .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT ?damageDetail
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
               kwg-ont:affectedByInverse ?hazard .
  ?impactObservation a sosa:Observation ;
                     sosa:observedProperty ?damageProp ;
                     sosa:hasFeatureOfInterest ?hazardEvent ;
                     sosa:hasResult/sosa:value ?damageDetail .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX : <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazardEvent ?attributeUri ?attributeValue ?damageImpactDetail ?impactValue ?temporalData
WHERE {
  # Hurricane-specific hazard events linked to a geographical place (administrative region or S2 cell)
  ?hazardEvent a :NOAAHazardEvent ;
               :spatialRelation|geo:hasGeometry|kwg-ont:sfWithin ?place .

  # Retrieve all hurricane‑specific attribute properties and their values
  {
    SELECT ?hazardEvent ?attributeUri (SAMPLE(?attributeValue) AS ?attributeValue)
    WHERE {
      VALUES ?attributeUri {
        :magnitudeObservableProperty.fujitaScale
        :magnitudeObservableProperty.estimateSustainedWidth
        :magnitudeObservableProperty.length
        :magnitudeObservableProperty.measuredSustainedWind
        :magnitudeObservableProperty.measuredWind
        :magnitudeObservableProperty.width
        :magnitudeObservableProperty.windEstimatedGust
      }
      ?hazardEvent ?attributeUri ?attributeValue .
    }
    GROUP BY ?hazardEvent ?attributeUri
  }

  # Retrieve damage‑impact details and any associated temporal data (e.g., start/end of event segment)
  {
    SELECT ?hazardEvent ?damageImpactDetail (SAMPLE(?impactValue) AS ?impactValue) ?temporalData
    WHERE {
      VALUES ?damageImpactDetail {
        :impactObservableProperty.damageCrop
        :impactObservableProperty.damageProperty
        :impactObservableProperty.deathDirect
        :impactObservableProperty.deathIndirect
        :impactObservableProperty.injuryDirect
        :impactObservableProperty.injuryIndirect
      }

      # Impact observations linked to the same hazard event
      ?impactObservation a :ImpactObservation ;
                         sosa:observedProperty ?damageImpactDetail ;
                         sosa:result ?impactValue .
      FILTER (EXISTS { ?impactObservation sosa:hasFeatureOfInterest ?hazardEvent })

      # Optional temporal data from the associated event segment
      OPTIONAL {
        ?eventSegment a :EventSegment ;
                      kwg-ont:startsFrom|kwg-ont:endsAt ?temporalNode .
        ?temporalNode time:inXSDDateTime ?temporalData .
        FILTER (EXISTS { ?hazardEvent kwg-ont:hasSegment ?eventSegment })
      }
    }
    GROUP BY ?hazardEvent ?damageImpactDetail
  }
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?event ?damageType ?damageValue
WHERE {
  ?event a kwg-ont:NOAAHazardEvent ;
         geo:sfWithin|kwg-ont:sfWithin ?place ;
         kwg-ont:hasTemporalScope [ time:inXSDDateTime ?time ] .

  FILTER (contains(str(?event), "Hurricane") || contains(str(?event), "Tornado") || 
          contains(str(?event), "Blizzard") || contains(str(?event), "Flood") ||
          contains(str(?event), "Wildfire") || contains(str(?event), "Earthquake"))

  ?event kwg-ont:hasPart/kwg-ont:affectedBy ?impact .
  ?impact a kwg-ont:ImpactObservation ;
          kwg-ont:hasDamageType ?damageType ;
          kwg-ont:damageValue ?damageValue .

  FILTER (?time >= "2023-01-01T00:00:00"^^xsd:dateTime && 
          ?time <= "2024-12-31T23:59:59"^^xsd:dateTime)
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?type ?name ?startDate ?endDate 
       ?affectedArea ?damageCrops ?damageInfrastructure
WHERE {
  ?hazard a kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type . }
  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?property ?value
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name } .
  FILTER NOT EXISTS { ?place a kwgl-ont:HazardEvent }
  {
    SELECT ?place ?property ?value
    WHERE {
      ?place a kwgl-ont:Place ;
             ?property ?value .
      FILTER (isDATATYPE(?property))
      FILTER (?property != kwgl-ont:sfContains && 
              ?property != kwgl-ont:sfIntersects &&
              ?property != kwgl-ont:sfOverlaps &&
              ?property != kwgl-ont:sfTouches &&
              ?property != kwgl-ont:sfWithin)
    }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?population ?households
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazardType (COUNT(*) AS ?count)
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType ?hazardType .
}
GROUP BY ?hazardType

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?attribute (COUNT(DISTINCT ?place) AS ?count)
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place ?attribute ?value . }
  FILTER (CONTAINS(LCASE(STR(?attribute)), "tornado"))
}
GROUP BY ?attribute

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
  ?attribute
  OPTIONAL {?attribute rdfs:label ?attrLabel}
  OPTIONAL {?attribute rdfs:range ?range}
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  FILTER (
    STRSTARTS(STR(?attribute), "http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/dollarDamageOfHurricanesImpactingPlace") ||
    STRSTARTS(STR(?attribute), "http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/numberOfHurricanesImpactingPlace")
  )
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT
  ?attribute
  OPTIONAL {?attribute rdfs:label ?attributeLabel}
  OPTIONAL {?attribute rdfs:range ?range}
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "flood")
  )
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?attribute
WHERE {
  ?attribute rdf:type owl:DatatypeProperty ;
             rdfs:domain kwgl-ont:Place .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hazardEvent ?typeLabel ?name ?startDate ?endDate
       ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType ?type .

  OPTIONAL { ?type rdfs:label ?typeLabel }
  OPTIONAL { ?hazardEvent kwgl-ont:hasName          ?name }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate     ?startDate }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate       ?endDate }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres   ?affectedAreaInAcres }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths   ?numberOfDeaths }

  FILTER (?type = kwglr:earthquake)
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?event
  (OPTIONAL ?affectedArea) 
  (OPTIONAL ?damageCrops) 
  (OPTIONAL ?damageInfrastructure)
WHERE {
  ?event a kwgl-ont:HazardEvent .

  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?hurricaneAttr ?damageImpact ?tempData
WHERE {
  ?event a kwgl-ont:HazardEvent ;
         kwgl-ont:hasHazardType kwglr:hurricane .  # filter for hurricane events

  ?event kwgl-ont:impactedBy ?place .             # link to the impacted place

  # Hurricane‑specific attributes that are defined on places
  OPTIONAL { ?place ?hurricaneAttr ?value .
             FILTER(regex(STR(?hurricaneAttr), "Hurricane", "i")) }

  # Damage impact details (damage in dollars)
  OPTIONAL {
    ?event kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage ;
           kwgl-ont:damageToCropsInDollars ?cropsDamage .
    BIND(COALESCE(?infrastructureDamage, "") AS ?damageImpact) }

  # Temporal data if available (start/end dates)
  OPTIONAL {
    ?event kwgl-ont:hasStartDate ?startDate ;
           kwgl-ont:hasEndDate   ?endDate .
    BIND(CONCAT("Start:", STR(?startDate), " End:", STR(?endDate)) AS ?tempData) }
}
ORDER BY ?place

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?place ?damageYear ?damageAmount
WHERE {
  ?hazard a kwgl-ont:Tornado ;
          kwgl-ont:hasImpacted ?place .

  OPTIONAL { 
    BIND (YEAR(STR(?hazard)) AS ?year) .
    FILTER EXISTS {
      ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace? ?damageYear ;
             ?damageYear ?damageAmount .
      FILTER (?year = YEAR(STR(?damageYear)))
    }
  } .

  FILTER (YEAR(STR(?hazard)) >= 2018 && YEAR(STR(?hazard)) <= 2022)
}

ORDER BY ?place ?damageYear

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place ?damageProperty ?damageValue
WHERE {
  ?hazard a kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType ?hazardType .

  FILTER (?hazardType IN (kwglr:hurricane, kwglr:tornado, kwglr:stormSurgeTide))

  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate   ?endDate   . }

  FILTER (?startDate >= "2020-01-01"^^xsd:date && ?endDate <= "2022-12-31"^^xsd:date)

  ?hazard kwgl-ont:impactedBy ?place .

  BINDING (kwgl-ont:dollarDamageOfHurricanesImpactingPlace AS ?damageProperty) {
    OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?damageValue . }
  } UNION
  BINDING (kwgl-ont:dollarDamageOfTornadoesImpactingPlace AS ?damageProperty) {
    OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damageValue . }
  } UNION
  BINDING (kwgl-ont:dollarDamageOfStormSurgesImpactingPlace AS ?damageProperty) {
    OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?damageValue . }
  }
}
ORDER BY ?place

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author ?familyName ?firstName
WHERE {
  ?author a coress-ont:Author .
  OPTIONAL { ?author coress-ont:hasFamilyName ?familyName } .
  OPTIONAL { ?author coress-ont:hasFirstName ?firstName }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?doi
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:hasDOI ?doi .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?department
WHERE {
  ?department a coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?submissionDate
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:dateOfSubmission ?submissionDate .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?university ?city
WHERE {
  ?university a coress-ont:University ;
              coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?author ?advisor
WHERE {
  ?author a coress-ont:Author ;
          coress-ont:advisedBy ?advisor .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?type
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:hasPublicationType ?type .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?agent ?department
WHERE {
  ?agent a coress-ont:Agent ;
         coress-ont:worksInDepartment ?department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?fieldOfStudy ?publicationTitle
WHERE {
  ?pub a coress-ont:Publication ;
       coress-ont:associatedFieldOfStudy ?fieldOfStudy ;
       coress-ont:hasTitle ?publicationTitle .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?city ?college
WHERE {
  ?univ a coress-ont:University ;
        coress-ont:atCity ?city ;
        coress-ont:hasCollege ?college .
  ?college a coress-ont:College .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication
WHERE {
  SELECT ?publication (COUNT(DISTINCT ?department) AS ?deptCount)
  WHERE {
    ?author a coress-ont:Author ;
            coress-ont:submits ?publication .
    ?author coress-ont:worksInDepartment ?department .
  }
  GROUP BY ?publication
  HAVING (?deptCount > 1)
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?pubType (AVG(?daysDiff) AS ?avgDays)
FROM <http://example.org/kg>
WHERE {
  ?pub a coress-ont:Publication ;
       coress-ont:dateOfSubmission ?submissionDate ;
       coress-ont:dateOfPublication ?publicationDate ;
       coress-ont:hasPublicationType ?pubType .
  FILTER (BOUND(?submissionDate) && BOUND(?publicationDate))
  BIND ((xsd:dateTime(?publicationDate) - xsd:dateTime(?submissionDate)) / ^^^xsdayTInterval"PT1D" AS ?daysDiff)
}
GROUP BY ?pubType
ORDER BY DESC(?avgDays)
LIMIT 1

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?author ?field
WHERE {
  ?author a coress-ont:Author ;
          coress-ont:advisedBy ?advisor .  # has an advisor (optional details can be added if needed)
  ?pub a coress-ont:Publication ;
       coress-ont:submittedBy ?author ;
       coress-ont:associatedFieldOfStudy ?field .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department (COUNT(*) AS ?missingFamilyNameCount)
WHERE {
  ?agent coress-ont:worksInDepartment ?department .
  OPTIONAL { ?agent coress-ont:hasFamilyName ?familyName } 
  FILTER (!BOUND(?familyName))
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?property ?value
WHERE {
  ?hazard a kwg-ont:Hazard .

  OPTIONAL { 
    ?hazard ?property ?value . 
    FILTER (regex(str(?property), "kwg-ont:") || regex(str(?property), "sosa:"))
  }

  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?temporalScope .
    BIND(time:inXSDDateTimeStamp(?temporalScope) AS ?when)
    BIND(kwg-ont:occurredAt AS ?property)
    BIND(bnode() AS ?value) # placeholder for the temporal value; actual time can be extracted via BIND
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?place ?name
WHERE {
  ?place a kwg-ont:AdministrativeRegion ;
         rdfs:label ?name .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
SELECT ?place ?hazard ?property ?value
WHERE {
  ?place a geo:Feature ;
         rdfs:subClassOf|a kwg-ont:HazardEpisode |
                       kwg-ont:Hazard ;
         geo:hasDefaultGeometry|geo:hasGeometry ?geom .

  OPTIONAL { ?place kwg-ont:hasTemporalScope ?temporal . }
  OPTIONAL { ?place a ?hazardType . } 

  OPTIONAL {
    BIND (IF(BOUND(?hazardType), ?hazardType, ?place) AS ?hazard)
    FILTER NOT EXISTS { ?place sosa:resultTime [] }
    ?place ?property ?value .
  }
}
ORDER BY ?place ?hazard ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
SELECT DISTINCT ?place ?observableProperty ?value
WHERE {
  ?place a kwg-ont:AdministrativeRegion ;
         sosa:isFeatureOfInterestOf ?observation .

  ?observation a sosa:Observation ;
               sosa:observedProperty ?observableProperty ;
               sosa:hasSimpleResult ?value .

  FILTER ( 
    EXISTS { ?observableProperty rdfs:subClassOf kwg-ont:CensusObservableProperty } ||
    EXISTS { ?observableProperty rdfs:subClassOf kwg-ont:PublicHealthObservableProperty }
  )
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT (COUNT(DISTINCT ?earthquake) AS ?count)
WHERE {
  ?earthquake a kwg-ont:Earthquake .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?attribute (COUNT(DISTINCT ?hazard) AS ?count)
WHERE {
  ?hazard a kwg-ont:NOAATornado ;
          ?attribute ?value .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT DISTINCT ?hazard ?property ?value
WHERE {
  ?hazard a kwg-ont:Flood .
  OPTIONAL { ?hazard ?property ?value . }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?placeUri ?climateProp
WHERE {
  ?placeUri a geo:Feature .
  OPTIONAL { ?placeUri kwg-ont:sfWithin/kwg-ont:sfWithin ?adminRegion . }

  ?obs a sosa:Observation ;
       sosa:hasFeatureOfInterest ?placeUri ;
       sosa:observedProperty ?climateProp .

  FILTER (?climateProp IN (kwg-ont:ClimateObservableProperty, sosa:ObservableProperty))
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazard ?superType ?property ?value
WHERE {
  ?hazard a kwg-ont:Earthquake .

  OPTIONAL { ?hazard rdfs:subClassOf ?superType . }

  OPTIONAL { 
    ?obs sosa:hasFeatureOfInterest ?hazard ;
         sosa:observedProperty ?property ;
         sosa:hasSimpleResult ?value .
  }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?impactProperty ?impactValue
WHERE {
  ?obs a kwg-ont:ImpactObservation ;
       sosa:hasFeatureOfInterest ?hazardEvent ;
       sosa:observedProperty ?impactProperty ;
       sosa:hasSimpleResult ?impactValue .

  ?hazardEvent a kwg-ont:NOAAHazardEvent .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT DISTINCT ?impactProperty ?value
WHERE {
  ?hazard a kwg-ont:Hazard ;
          sosa:hasFeatureOfInterest/kwg-ont:affectedBy ?impact .

  ?impact a kwg-ont:ImpactObservation ;
          sosa:observedProperty ?impactProperty ;
          sosa:hasSimpleResult ?value .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazardUri ?property ?value ?impactProperty ?impactValue ?temp
WHERE {
  # Hurricane-specific hazard (any subclass of NOAAHazardEvent that is a hurricane)
  ?hazardUri a kwg-ont:NOAAHurricane .

  # Hazard attributes related to a geographical place
  OPTIONAL { 
    ?hazardUri geo:hasGeometry ?geom . 
    ?hazardUri geo:hasDefaultGeometry ?defGeom . 
    ?hazardUri kwg-ont:spatialRelation ?place . 
    FILTER(?place != ?hazardUri)  # ensure relation to a distinct place
  }

  # Retrieve any other properties/values describing the hurricane hazard
  OPTIONAL { ?hazardUri ?property ?value . }

  # Damage impact details for the same hurricane event
  {
    SELECT ?hazardUri ?impactProperty ?impactValue ?temp
    WHERE {
      SERVICE <wikipediaEndpoint> {
        # Impact observations linked to the hurricane hazard
        ?obs a kwg-ont:ImpactObservation ;
             sosa:hasFeatureOfInterest ?hazardUri ;
             sosa:observedProperty ?impactProperty ;
             sosa:hasSimpleResult ?impactValue .
        OPTIONAL { ?obs sosa:phenomenonTime ?temp . }
      }
    }
  }
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT DISTINCT ?hazard ?property ?value
WHERE {
  ?hazard a kwg-ont:NOAATornado ;
          ?property ?value .

  OPTIONAL { ?hazard geo:hasGeometry ?geometry . }
  FILTER NOT EXISTS {
    ?region a kwg-ont:AdministrativeRegion_3 ;
            geo:sfWithin ?geometry .
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?property ?value
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          a [ rdf:type sosa:FeatureOfInterest ;
              geo:hasGeometry ?geometry ] .

  OPTIONAL { 
    ?observation a sosa:Observation ;
                 sosa:phenomenonTime ?time ;
                 sosa:observedProperty ?property ;
                 sosa:hasSimpleResult ?value ;
                 sosa:hasFeatureOfInterest ?hazard .

    FILTER ( ?time >= "2023-01-01T00:00:00"^^xsd:dateTime && 
             ?time <= "2024-12-31T23:59:59"^^xsd:dateTime )
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?title ?submissionDate
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:hasTitle ?title ;
               coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?university ?city
WHERE {
  ?university a coresr-ont:University ;
              coresr-ont:locatedAt [ 
                a coresr-ont:Location ;
                coresr-ont:atState [ 
                  a coresr-ont:State ;
                  coresr-ont:inCity ?city 
                ]
              ] .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author ?advisor
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?agent ?department
WHERE {
  ?agent coresr-ont:associatedWith ?department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?fieldOfStudy
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?city ?college
WHERE {
  ?univ a coresr-ont:University ;
        coresr-ont:locatedAt ?loc .
  ?loc a coresr-ont:Location ;
       coresr-ont:atState ?state .
  ?state coresr-ont:inCity ?city .
  ?colleg a coresr-ont:College ;
          coresr-ont:partOf ?univ .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?publication
WHERE {
  ?publication a coresr-ont:Publication .
  SELECT ?publication (COUNT(DISTINCT ?department) AS ?deptCount)
  WHERE {
    ?contributor a coresr-ont:Contributor ;
                 coresr-ont:contributedTo ?publication .
    ?agent a coresr-ont:Agent ;
           coresr-ont:associatedWith ?department .
    FILTER(?contributor = ?agent)
  }
  GROUP BY ?publication
  HAVING (?deptCount > 1)
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?pubType (AVG(?diff) AS ?avgDiff)
FROM <http://example.org/kg-core-scholar-rich>
WHERE {
  ?pub a coresr-ont:Publication ;
       coresr-ont:dateOfSubmission ?submissionDate ;
       coresr-ont:dateOfPublication ?publicationDate ;
       coresr-ont:hasPublicationType ?pt .

  ?pt coresr-ont:typeAsString ?pubType .

  BIND (xsd:integer(?publicationDate) - xsd:integer(?submissionDate) AS ?diff)
}
GROUP BY ?pubType
ORDER BY DESC(?avgDiff)
LIMIT 1

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author ?field
WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .  # ensures the author has an advisor

  ?pub a coresr-ont:Publication ;
       coresr-ont:submittedBy ?author ;
       coresr-ont:associatedFieldOfStudy ?field .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department (COUNT(DISTINCT ?agent) AS ?missingCount)
WHERE {
  ?agent a coresr-ont:Agent ;
         coresr-ont:associatedWith ?department .
  OPTIONAL { ?agent coresr-ont:hasContactInformation [ a coresr-ont:FamilyName ] }
  FILTER (!BOUND(?familyName))
}
GROUP BY ?department
ORDER BY DESC(?missingCount)
LIMIT 1

